from fractions import Fraction

class CalcError(Exception):
    def __init__(self, message, position):
        super().__init__(f"{message} at position {position}")
        self.position = position

def tokenize(expr: str):
    """
    Scans the input string and returns a list of tokens.
    Each token is a tuple: (type, value, position)
    Types: 'NUM', 'OP', 'LPAREN', 'RPAREN'
    """
    tokens = []
    i = 0
    n = len(expr)

    while i < n:
        char = expr[i]

        # Skip whitespace
        if char in ' \t':
            i += 1
            continue

        # Numbers
        if char.isdigit():
            start = i
            # Scan digits
            while i < n and expr[i].isdigit():
                i += 1

            # Check for fractional part
            if i < n and expr[i] == '.':
                # Look ahead to see if there is a digit after the dot
                # If yes, it's part of the number. If no, the dot is not part of the number.
                if i + 1 < n and expr[i+1].isdigit():
                    i += 1 # consume '.'
                    while i < n and expr[i].isdigit():
                        i += 1
                # else: do not consume the dot. The number ends here.

            num_str = expr[start:i]
            tokens.append(('NUM', num_str, start))
            continue

        # Operators
        if char in '+-*/':
            tokens.append(('OP', char, i))
            i += 1
            continue

        # Parentheses
        if char == '(':
            tokens.append(('LPAREN', '(', i))
            i += 1
            continue

        if char == ')':
            tokens.append(('RPAREN', ')', i))
            i += 1
            continue

        # Invalid character
        raise CalcError(f"Invalid character '{char}'", i)

    return tokens

class Parser:
    def __init__(self, tokens, expr):
        self.tokens = tokens
        self.pos = 0
        self.expr_len = len(expr)

    def peek(self):
        if self.pos < len(self.tokens):
            return self.tokens[self.pos]
        return None

    def consume(self):
        if self.pos < len(self.tokens):
            tok = self.tokens[self.pos]
            self.pos += 1
            return tok
        raise CalcError("Unexpected end of expression", self.expr_len)

    def parse(self):
        result = self.expression()
        if self.peek() is not None:
            tok = self.peek()
            raise CalcError(f"Unexpected token {tok[1]}", tok[2])
        return result

    def expression(self):
        # Expression := Term (('+' | '-') Term)*
        val = self.term()
        while True:
            tok = self.peek()
            if tok is None:
                break
            if tok[0] == 'OP' and tok[1] in ('+', '-'):
                op = self.consume()[1]
                right = self.term()
                if op == '+':
                    val = val + right
                else:
                    val = val - right
            else:
                break
        return val

    def term(self):
        # Term := Factor (('*' | '/') Factor)*
        val = self.factor()
        while True:
            tok = self.peek()
            if tok is None:
                break
            if tok[0] == 'OP' and tok[1] in ('*', '/'):
                op_tok = self.consume()
                op = op_tok[1]
                right = self.factor()
                if op == '*':
                    val = val * right
                else:
                    if right == 0:
                        raise CalcError("Division by zero", op_tok[2])
                    val = val / right
            else:
                break
        return val

    def factor(self):
        # Factor := '-' Factor | Atom
        tok = self.peek()
        if tok is not None and tok[0] == 'OP' and tok[1] == '-':
            self.consume()
            return -self.factor()
        return self.atom()

    def atom(self):
        # Atom := 'NUM' | '(' Expression ')'
        tok = self.peek()
        if tok is None:
            raise CalcError("Unexpected end of expression", self.expr_len)

        if tok[0] == 'NUM':
            self.consume()
            return Fraction(tok[1])

        if tok[0] == 'LPAREN':
            self.consume()
            val = self.expression()
            tok = self.peek()
            if tok is None:
                raise CalcError("Expected ')'", self.expr_len)
            if tok[0] != 'RPAREN':
                raise CalcError(f"Expected ')', got '{tok[1]}'", tok[2])
            self.consume()
            return val

        # If we get here, the token cannot start an atom
        raise CalcError(f"Unexpected token '{tok[1]}'", tok[2])

def evaluate(expr: str) -> Fraction:
    try:
        tokens = tokenize(expr)
    except CalcError:
        raise

    parser = Parser(tokens, expr)
    return parser.parse()
