        if expr[i] == '*':
            if i + 1 < n and expr[i+1] == '*':
                tokens.append(('POW', '**', i))
                i += 2
            else:
                tokens.append(('MUL', '*', i))
                i += 1
            continue
        if expr[i] == '/':
            tokens.append(('DIV', '/', i))
            i += 1
            continue
        if expr[i] == '+':
            tokens.append(('PLUS', '+', i))
            i += 1
            continue
        if expr[i] == '-':
            tokens.append(('MINUS', '-', i))
            i += 1
            continue
        if expr[i] == '(':
            tokens.append(('LPAREN', '(', i))
            i += 1
            continue
        if expr[i] == ')':
            tokens.append(('RPAREN', ')', i))
            i += 1
            continue
        if expr[i] == ',':
            tokens.append(('COMMA', ',', i))
            i += 1
            continue

        raise CalcError(f"Unexpected character '{expr[i]}'", i)

    tokens.append(('EOF', '', n))
    return tokens

class Node:
    pass

class NumNode(Node):
    def __init__(self, value):
        self.value = value

class VarNode(Node):
    def __init__(self, name, pos):
        self.name = name
        self.pos = pos

class CallNode(Node):
    def __init__(self, name, pos, args):
        self.name = name
        self.pos = pos
        self.args = args

class BinNode(Node):
    def __init__(self, op, pos, left, right):
        self.op = op
        self.pos = pos
        self.left = left
        self.right = right

class UnaryNode(Node):
    def __init__(self, op, pos, operand):
        self.op = op
        self.pos = pos
        self.operand = operand

class Parser:
    def __init__(self, tokens, expr):
        self.tokens = tokens
        self.pos = 0
        self.expr_len = len(expr)

    def peek(self):
        return self.tokens[self.pos]

    def consume(self, expected_type=None):
        token = self.tokens[self.pos]
        if expected_type and token[0] != expected_type:
            raise CalcError(f"Expected {expected_type} but got {token[0]}", token[2])
        self.pos += 1
        return token

    def error(self, msg, pos=None):
        if pos is None:
            if self.pos < len(self.tokens):
                pos = self.tokens[self.pos][2]
            else:
                pos = self.expr_len
        raise CalcError(msg, pos)

    def parse(self):
        node = self.parse_expr()
        if self.peek()[0] != 'EOF':
            self.error("Unexpected token")
        return node

    def parse_expr(self):
        left = self.parse_term()
        while self.peek()[0] in ('PLUS', 'MINUS'):
            token = self.consume()
            right = self.parse_term()
            left = BinNode(token[0], token[2], left, right)
        return left

    def parse_term(self):
        left = self.parse_unary()
        while self.peek()[0] in ('MUL', 'DIV'):
            token = self.consume()
            right = self.parse_unary()
            left = BinNode(token[0], token[2], left, right)
        return left

    def parse_unary(self):
        if self.peek()[0] in ('PLUS', 'MINUS'):
            token = self.consume()
            operand = self.parse_unary()
            return UnaryNode(token[0], token[2], operand)
        return self.parse_power()

    def parse_power(self):
        left = self.parse_atom()
        if self.peek()[0] == 'POW':
            token = self.consume()
            right = self.parse_unary()
            return BinNode('**', token[2], left, right)
        return left

    def parse_atom(self):
        token = self.peek()

        if token[0] == 'NUM':
            self.consume()
            return NumNode(Fraction(token[1]))

        if token[0] == 'NAME':
            self.consume()
            name = token[1]
            name_pos = token[2]
            # Check if function call
            if self.peek()[0] == 'LPAREN':
                self.consume()
                args = []
                if self.peek()[0] != 'RPAREN':
                    args.append(self.parse_expr())
                    while self.peek()[0] == 'COMMA':
                        self.consume()
                        args.append(self.parse_expr())
                if self.peek()[0] != 'RPAREN':
                    self.error("Expected ')' or ','", self.peek()[2])
                self.consume() # consume RPAREN
                return CallNode(name, name_pos, args)
            else:
                return VarNode(name, name_pos)

        if token[0] == 'LPAREN':
            self.consume()
            node = self.parse_expr()
            if self.peek()[0] != 'RPAREN':
                self.error("Expected ')'", self.peek()[2])
            self.consume()
            return node

        self.error(f"Unexpected token '{token[1]}'", token[2])

def evaluate_ast(node, variables):
    if isinstance(node, NumNode):
        return node.value

    if isinstance(node, VarNode):
        if variables is None:
            raise CalcError("No variables allowed", node.pos)
        if node.name not in variables:
            raise CalcError(f"Unknown variable '{node.name}'", node.pos)
        return variables[node.name]

    if isinstance(node, UnaryNode):
        val = evaluate_ast(node.operand, variables)
        if node.op == 'MINUS':
            return -val
        return val

    if isinstance(node, BinNode):
        # For **, check right operand type before evaluating left? 
        # Spec: "A function's name and argument count are checked before its arguments are evaluated."
        # It doesn't explicitly say operators check types before eval, but implies standard eval order.
        # However, for 0 ** -1, we need to know rhs is -1.
        # If we eval lhs, then rhs, then check.
        # If lhs is 1/0, and rhs is 0.5. Error div by zero at lhs pos?
        # Spec: "0 raised to a negative power is a division by zero: the position of the **."
        # "An exponent that is not a whole number ... position of the **"
        # It implies these are checked during the application of **.

        left = evaluate_ast(node.left, variables)
        right = evaluate_ast(node.right, variables)

        if node.op == '+':
            return left + right
        if node.op == '-':
            return left - right
        if node.op == 'MUL':
            return left * right
        if node.op == 'DIV':
            if right == 0:
                raise CalcError("Division by zero", node.pos)
            return left / right
        if node.op == '**':
            if not isinstance(right, Fraction) or right.denominator != 1:
                raise CalcError("Exponent must be a whole number", node.pos)
            exp = int(right)
            if left == 0 and exp < 0:
                raise CalcError("Division by zero", node.pos)
            return left ** exp

    if isinstance(node, CallNode):
        # Check name and arg count first
        valid_funcs = {'abs': 1, 'min': -1, 'max': -1}
        if node.name not in valid_funcs:
            raise CalcError(f"Unknown function '{node.name}'", node.pos)

        expected_count = valid_funcs[node.name]
        arg_count = len(node.args)

        if expected_count != -1 and arg_count != expected_count:
            raise CalcError(f"Wrong number of arguments to '{node.name}'", node.pos)
        if expected_count == -1 and arg_count < 1:
            raise CalcError(f"Wrong number of arguments to '{node.name}'", node.pos)

        # Now evaluate args
        values = [evaluate_ast(arg, variables) for arg in node.args]

        if node.name == 'abs':
            return abs(values[0])
        if node.name == 'min':
            return min(values)
        if node.name == 'max':
            return max(values)

    raise CalcError("Internal error: unknown node type", 0)

def evaluate(expr: str, variables=None) -> Fraction:
    try:
        tokens = tokenize(expr)
        parser = Parser(tokens, expr)
        ast = parser.parse()
        return evaluate_ast(ast, variables)
    except CalcError:
        raise
