        # Spec: "A function's name and argument count are checked before its arguments are evaluated."
        # It doesn't explicitly say operators check types before eval, but implies standard eval order.
        # However, for 0 ** -1, we need to know rhs is -1.
        # If we eval lhs, then rhs, then check.
        # If lhs is 1/0, and rhs is 0.5. Error div by zero at lhs pos?
        # Spec: "0 raised to a negative power is a division by zero: the position of the **."
        # "An exponent that is not a whole number ... position of the **"
        # It implies these are checked during the application of **.

        left = evaluate_ast(node.left, variables)
        right = evaluate_ast(node.right, variables)

        if node.op == '+':
            return left + right
        if node.op == '-':
            return left - right
        if node.op == 'MUL':
            return left * right
        if node.op == 'DIV':
            if right == 0:
                raise CalcError("Division by zero", node.pos)
            return left / right
        if node.op == '**':
            if not isinstance(right, Fraction) or right.denominator != 1:
                raise CalcError("Exponent must be a whole number", node.pos)
            exp = int(right)
            if left == 0 and exp < 0:
                raise CalcError("Division by zero", node.pos)
            return left ** exp

    if isinstance(node, CallNode):
        # Check name and arg count first
        valid_funcs = {'abs': 1, 'min': -1, 'max': -1}
        if node.name not in valid_funcs:
            raise CalcError(f"Unknown function '{node.name}'", node.pos)

        expected_count = valid_funcs[node.name]
        arg_count = len(node.args)

        if expected_count != -1 and arg_count != expected_count:
            raise CalcError(f"Wrong number of arguments to '{node.name}'", node.pos)
        if expected_count == -1 and arg_count < 1:
            raise CalcError(f"Wrong number of arguments to '{node.name}'", node.pos)

        # Now evaluate args
        values = [evaluate_ast(arg, variables) for arg in node.args]

        if node.name == 'abs':
            return abs(values[0])
        if node.name == 'min':
            return min(values)
        if node.name == 'max':
            return max(values)

    raise CalcError("Internal error: unknown node type", 0)

def evaluate(expr: str, variables=None) -> Fraction:
    try:
        tokens = tokenize(expr)
        parser = Parser(tokens, expr)
        ast = parser.parse()
        return evaluate_ast(ast, variables)
    except CalcError:
        raise

