import collections.abc
from typing import Any, Union, List

# Sentinel for default values
class _Sentinel:
    pass

_sentinel = _Sentinel()


class PathError(LookupError):
    def __init__(self, message: str, path: str):
        super().__init__(message)
        self.path = path

# Unique object for wildcard
WILDCARD = object()


def parse(path: str) -> List[Union[str, int, object]]:
    """
    Parse a JSON path string into a list of segments.
    Segments can be str (key), int (index), or WILDCARD.
    """
    segments: List[Union[str, int, object]] = []
    i = 0
    n = len(path)

    if n == 0:
        return segments

    # Helper to parse quoted string
    def parse_quoted(start: int) -> tuple[str, int]:
        quote_char = path[start]
        j = start + 1
        chars = []
        while j < n:
            if path[j] == '\\':
                if j + 1 < n:
                    next_char = path[j+1]
                    if next_char == 'n': chars.append('\n')
                    elif next_char == 'r': chars.append('\r')
                    elif next_char == 't': chars.append('\t')
                    elif next_char == '\\': chars.append('\\')
                    elif next_char == quote_char: chars.append(quote_char)
                    else:
                        chars.append(next_char)
                    j += 2
                else:
                    raise PathError("Unexpected end of string after backslash", path)
            elif path[j] == quote_char:
                return ''.join(chars), j + 1
            else:
                chars.append(path[j])
                j += 1
        raise PathError("Unterminated quoted string", path)

    while i < n:
        if path[i] == '.':
            if i + 1 >= n:
                raise PathError("Unexpected end after dot", path)
            if path[i+1] == '[':
                # Next segment is bracket, skip dot and let loop handle '['
                i += 1
                continue
            else:
                # Key segment
                start = i + 1
                if start < n and path[start] in ("'", '"'):
                    key, new_i = parse_quoted(start)
                    i = new_i
                else:
                    end = start
                    while end < n and path[end] not in ('.', '['):
                        end += 1
                    key = path[start:end]
                    if not key:
                        raise PathError("Empty key after dot", path)
                    i = end
                segments.append(key)
        elif path[i] == '[':
            i += 1
            if i >= n:
                raise PathError("Unexpected end after '['", path)

            if path[i] == '*':
                # Wildcard
                if i + 1 >= n or path[i+1] != ']':
                    raise PathError("Invalid wildcard syntax", path)
                segments.append(WILDCARD)
                i += 2
            elif path[i] in ("'", '"'):
                key, new_i = parse_quoted(i)
                i = new_i
                if i >= n or path[i] != ']':
                    raise PathError("Expected ']' after quoted key", path)
                i += 1
                segments.append(key)
            else:
                # Number (possibly negative)
                start = i
                # Handle optional negative sign
                if i < n and path[i] == '-':
                    i += 1
                if i >= n or not path[i].isdigit():
                    raise PathError("Expected integer or quoted key inside brackets", path)
                while i < n and path[i].isdigit():
                    i += 1
                num_str = path[start:i]
                num = int(num_str)
                if i >= n or path[i] != ']':
                    raise PathError("Expected ']' after integer", path)
                i += 1
                segments.append(num)
        else:
            # First segment could be a key if not starting with dot or bracket
            start = i
            if i < n and path[i] in ("'", '"'):
                key, new_i = parse_quoted(i)
                i = new_i
            else:
                while i < n and path[i] not in ('.', '['):
                    i += 1
                key = path[start:i]
                if not key:
                    raise PathError("Empty key at start", path)
            segments.append(key)
            # Continue to next char (which might be . or [ or end)
            continue

    return segments


def get(obj: Any, path: str, default: Any = _sentinel) -> Any:
    """
    Get a value or list of values from a nested JSON-like object using a path string.

    Args:
        obj: The object to traverse.
        path: The path string.
        default: The value to return if the path is not found (only used if no wildcards).

    Returns:
        If no wildcards: The value at the path, or default if not found.
        If wildcards present: A list of all values matching the path.

    Raises:
        PathError: If the path syntax is invalid.
    """
    segments = parse(path)

    # Check if path contains any wildcards
    if WILDCARD in segments:
        return _get_wildcard(obj, segments)

    # Existing non-wildcard logic
    current = obj
    for seg in segments:
        try:
            if isinstance(seg, str):
                if isinstance(current, collections.abc.Mapping):
                    if seg in current:
                        current = current[seg]
                    else:
                        raise KeyError(seg)
                else:
                    raise TypeError(f"Cannot use string key on {type(current)}")
            elif isinstance(seg, int):
                if isinstance(current, (list, tuple)):
                    try:
                        # Python list/tuple indexing handles negatives
                        current = current[seg]
                    except IndexError:
                        raise IndexError(f"Index {seg} out of range")
                else:
                    raise TypeError(f"Cannot use integer index on {type(current)}")
            else:
                raise PathError("Invalid segment type", path)

        except (KeyError, IndexError, TypeError) as e:
            if default is not _sentinel:
                return default
            raise PathError(str(e), path) from e

    return current


def _get_wildcard(obj: Any, segments: List[Union[str, int, Any]]) -> List[Any]:
    """
    Recursively collect all values matching the path segments starting from obj.
    """
    if not segments:
        return [obj]

    seg = segments[0]
    rest = segments[1:]

    if seg is WILDCARD:
        results = []
        if isinstance(obj, (list, tuple)):
            for item in obj:
                results.extend(_get_wildcard(item, rest))
        elif isinstance(obj, collections.abc.Mapping):
            # Insertion order preserved in Python 3.7+ dicts
            for val in obj.values():
                results.extend(_get_wildcard(val, rest))
        # else: matches nothing
        return results

    elif isinstance(seg, str):
        if isinstance(obj, collections.abc.Mapping):
            if seg in obj:
                return _get_wildcard(obj[seg], rest)
        return []

    elif isinstance(seg, int):
        if isinstance(obj, (list, tuple)):
            try:
                item = obj[seg]
                return _get_wildcard(item, rest)
            except IndexError:
                return []
        return []

    else:
        return []


def set(obj: Any, path: str, value: Any) -> None:
    """
    Set a value at the given path in the object, creating intermediate containers if needed.

    Args:
        obj: The object to modify.
        path: The path string.
        value: The value to set.

    Raises:
        PathError: If the path is empty, contains a wildcard, or is invalid for the structure.
                   When raised, obj is left exactly as it was.
    """
    segments = parse(path)

    if not segments:
        raise PathError("Path cannot be empty", path)

    if WILDCARD in segments:
        raise PathError("Wildcard not allowed in set", path)

    # To ensure atomicity, we maintain a stack of actions to undo if a failure occurs.
    # Each action is a callable that reverts a specific change.
    undo_stack: List[Any] = []

    current = obj
    for i, seg in enumerate(segments):
        is_last = (i == len(segments) - 1)

        if isinstance(seg, str):
            if not isinstance(current, collections.abc.Mapping):
                # Cannot traverse or set if current is not a Mapping
                # But we might be able to create the container if current was "missing"?
                # No, current is the result of previous navigation. 
                # If previous step created it, it's a Mapping.
                # If we are at step 0, obj must be a Mapping.
                # Spec: "A container can only be created ... inside a dict ... or a list"
                # So if current is not a Mapping, and seg is str, it's an error.
                raise PathError(f"Cannot set key '{seg}' on {type(current)}", path)

            if is_last:
                # Set value in current mapping
                old_val = current.get(seg, _sentinel)
                if old_val is _sentinel:
                    # New key
                    current[seg] = value
                    undo_stack.append(lambda c=current, k=seg: c.pop(k, None))
                else:
                    # Existing key
                    current[seg] = value
                    undo_stack.append(lambda c=current, k=seg, ov=old_val: c.__setitem__(k, ov))
            else:
                # Navigate deeper
                if seg not in current:
                    # Create container
                    next_seg = segments[i+1]
                    new_container: Any
                    if isinstance(next_seg, int):
                        new_container = []
                    elif isinstance(next_seg, str):
                        new_container = {}
                    else:
                        raise PathError("Invalid next segment for creation", path)

                    current[seg] = new_container
                    undo_stack.append(lambda c=current, k=seg: c.pop(k, None))
                    current = new_container
                else:
                    val = current[seg]
                    # Check compatibility: val must be a container we can navigate into or modify
                    if not isinstance(val, (collections.abc.Mapping, list)):
                        # If it's a string/number/None/Tuple, we can't go deeper if we need to create things
                        # But if we are just navigating through a Tuple? No, tuples are read-only.
                        # If we are just reading (not creating), we might be ok, but set requires modification eventually.
                        # If val is a String, and we try to set 'a.b.c', and 'b' is a string, we fail at 'b.c'.
                        # We just pass current=val and let the next iteration handle the error.
                        pass
                    current = val

        elif isinstance(seg, int):
            if not isinstance(current, (list, tuple)):
                raise PathError(f"Cannot set index {seg} on {type(current)}", path)

            if isinstance(current, tuple):
                # Tuples are immutable. We can read, but we cannot create containers inside them or set values in them.
                # Spec: "any segment on ... a tuple that would have to change" raises.
                # If we are navigating (not last), we don't change the tuple itself, but we might need to change its children.
                # However, we cannot change the tuple structure. 
                # If we are at last segment, we are trying to set an element -> raise.
                # If we are not at last segment, we are navigating into it. That is allowed (read).
                # BUT, if the next step requires modifying something inside that tuple's element, it will fail then.
                # The error "index segment on a dict" suggests type checks are strict.
                # Let's check if we are modifying. 
                # If we are not last, we are just moving. This is allowed. 
                # If we are last, we are setting -> Error.
                if is_last:
                    raise PathError("Cannot set value in tuple", path)

                # Navigate
                try:
                    current = current[seg]
                except IndexError:
                    raise PathError("Index out of bounds", path)
            else:
                # It's a list
                # Validate index for creation or access
                # Rules:
                # -len to len-1 : existing element
                # len : append (only if creating?)
                # "newly created list only accepts index 0"
                # This implies if we just created the list, its length is 0. Valid indices: 0 (append).
                # If list exists, valid indices for setting: -len to len (append).

                is_new_list = False
                # How to detect new list? 
                # If the parent step created it? 
                # Actually, if we are here, the list exists. 
                # If we are navigating through a newly created list, the previous step created it.
                # In the previous step (str seg), we created a list and added it to current.
                # We didn't track "is_new" in the current variable.
                # However, if the list is empty and we try to access index > 0, it's invalid if it's new?
                # Spec: "set({}, 'a[1]', 1) raises". Here 'a' is created as []. Index 1 is len+1 (len=0). Invalid.
                # Spec: "set({}, 'a[0].b', 1) gives {'a': [{'b': 1}]}". Index 0 is len (0). Valid append.

                # So rule for list index:
                # If index < -len or index >= len: 
                #   If index == len: Append is allowed.
                #   Else: Error.

                try:
                    # Check if existing
                    current[seg]
