        if _solve_recursive(grid):
            return True
        grid[r][c] = 0  # Undo

    return False

def solve(grid) -> list[list[int]] | None:
    """
    Solves the Sudoku puzzle.
    Returns a completed, valid grid that keeps every given of grid, or None if none exists.
    The argument is never modified.
    """
    _validate_grid(grid)
    if not is_valid(grid):
        return None

    # Deep copy the grid to avoid modifying the original
    copy = [row[:] for row in grid]

    # _solve_recursive modifies in-place and returns True if solved
    if _solve_recursive(copy):
        return copy
    return None


def _count_solutions_recursive(grid, limit: int) -> int:
    """
    Counts the number of solutions for the grid in-place, up to the given limit.
    Restores the grid to its original state before returning.
    """
    # Find the empty cell with the fewest candidates (MRV)
    best_cell = None
    min_candidates = 10  # Max candidates is 9

    for r in range(9):
        for c in range(9):
            if grid[r][c] == 0:
                candidates = _get_candidates(grid, r, c)
                if len(candidates) == 0:
                    return 0  # Dead end, invalid branch
                if len(candidates) < min_candidates:
                    min_candidates = len(candidates)
                    best_cell = (r, c, candidates)
                    if min_candidates == 1:
                        break
        if min_candidates == 1:
            break

    if best_cell is None:
        return 1  # No empty cells, found one solution

    r, c, candidates = best_cell
    count = 0

    for val in candidates:
        grid[r][c] = val
        count += _count_solutions_recursive(grid, limit - count)
        grid[r][c] = 0  # Undo

        # Early stop if limit reached
        if count >= limit:
            break

    return count


def count_solutions(grid, limit: int = 2) -> int:
    """
    Counts the number of solutions, stopping at 'limit'.
    An invalid grid has 0 solutions.
    Raises ValueError if limit < 1.
    The argument is never modified.
    """
    _validate_grid(grid)

    if limit < 1:
        raise ValueError("Limit must be at least 1")

    if not is_valid(grid):
        return 0

    # Deep copy to avoid modifying the original, although the recursive helper
    # backtracks, it's good practice to keep the original pristine.
    copy = [row[:] for row in grid]

    return _count_solutions_recursive(copy, limit)


def hint(grid) -> tuple[int, int, int, str] | None:
    """
    Returns the next logical step for the Sudoku grid.

    Steps:
    1. Naked single: A cell with only one candidate.
       Scans row-major order. Reason: 'naked single'.
    2. Hidden single: A digit that appears as a candidate in only one empty cell
       of a unit (row, column, or box). Scans rows 0-8, cols 0-8, boxes 0-8.
       Reason: 'hidden single in row'/'column'/'box'.

    Returns (row, col, digit, reason) or None if no such step exists.
    Raises ValueError if grid is invalid.
    """
    _validate_grid(grid)
    if not is_valid(grid):
        raise ValueError("Grid is not valid")

    # 1. Look for naked singles
    for r in range(9):
        for c in range(9):
            if grid[r][c] == 0:
                candidates = _get_candidates(grid, r, c)
                if len(candidates) == 1:
                    return (r, c, candidates[0], 'naked single')

    # 2. Look for hidden singles
    # Helper to get empty cells in a unit
    def get_empty_cells_in_row(r):
        return [(r, c) for c in range(9) if grid[r][c] == 0]

    def get_empty_cells_in_col(c):
        return [(r, c) for r in range(9) if grid[r][c] == 0]

    def get_empty_cells_in_box(b):
        box_r = 3 * (b // 3)
        box_c = 3 * (b % 3)
        return [
            (box_r + i, box_c + j) 
            for i in range(3) 
            for j in range(3) 
            if grid[box_r + i][box_c + j] == 0
        ]

    def count_candidate_positions(digit, cells):
        """Count how many empty cells in the unit have this digit as a candidate."""
        count = 0
        target_cell = None
        for r, c in cells:
            if digit in _get_candidates(grid, r, c):
                count += 1
                target_cell = (r, c)
                if count > 1:
                    return count, None
        return count, target_cell

    # Check Rows
    for r in range(9):
        empty_cells = get_empty_cells_in_row(r)
        if not empty_cells:
            continue

        for digit in range(1, 10):
            # If digit already in row, skip
            if any(grid[r][c] == digit for c in range(9)):
                continue

            count, cell = count_candidate_positions(digit, empty_cells)
            if count == 1:
                return (cell[0], cell[1], digit, 'hidden single in row')

    # Check Columns
    for c in range(9):
        empty_cells = get_empty_cells_in_col(c)
        if not empty_cells:
            continue

        for digit in range(1, 10):
            # If digit already in col, skip
            if any(grid[r][c] == digit for r in range(9)):
                continue

            count, cell = count_candidate_positions(digit, empty_cells)
            if count == 1:
                return (cell[0], cell[1], digit, 'hidden single in column')

    # Check Boxes
    for b in range(9):
        empty_cells = get_empty_cells_in_box(b)
        if not empty_cells:
            continue

        for digit in range(1, 10):
            # If digit already in box, skip
            # Box start coords
            br = 3 * (b // 3)
            bc = 3 * (b % 3)
            if any(grid[br + i][bc + j] == digit for i in range(3) for j in range(3)):
                continue

            count, cell = count_candidate_positions(digit, empty_cells)
            if count == 1:
                return (cell[0], cell[1], digit, 'hidden single in box')

    return None


def difficulty(grid) -> dict[str, int] | None:
    """
    Determines the difficulty of the Sudoku puzzle by applying simple hints
    repeatedly until the grid is complete or stuck.

    Returns a dictionary {'naked': count, 'hidden': count} or None if the grid
    cannot be completed using these simple strategies.

    Raises ValueError if the grid is invalid (bad shape or conflicts).
    """
    # Validate and ensure grid is valid (hint does this too, but let's fail fast)
    _validate_grid(grid)
    if not is_valid(grid):
        raise ValueError("Grid is not valid")

    # Work on a copy to avoid modifying the original
    grid_copy = [row[:] for row in grid]

    counts = {'naked': 0, 'hidden': 0}

    while True:
        step = hint(grid_copy)

        if step is None:
            # Check if the grid is complete
            is_complete = True
            for r in range(9):
                for c in range(9):
                    if grid_copy[r][c] == 0:
                        is_complete = False
                        break
                if not is_complete:
                    break

            if is_complete:
                return counts
            else:
                # Stuck and not complete -> unsolvable with these steps
                return None

        r, c, digit, reason = step

        # Apply the step
        grid_copy[r][c] = digit

        # Update counts
        if reason == 'naked single':
            counts['naked'] += 1
        else:
            # Reasons for hidden singles start with 'hidden single in ...'
            counts['hidden'] += 1

