        self._items: dict[str, Item] = {}
        self._movements: list[Movement] = []
        self._next_seq: int = 1

    def add_item(self, item: Item) -> None:
        if item.sku in self._items:
            raise ValueError(f"Item with SKU {item.sku} already exists")
        self._items[item.sku] = item

    def item(self, sku: str) -> Item:
        if sku not in self._items:
            raise UnknownItemError(f"Unknown SKU: {sku}")
        return self._items[sku]

    def items(self) -> list[Item]:
        return sorted(self._items.values(), key=lambda x: x.sku)

    def _validate_recording(self, day: datetime.date, sku: str, qty: int) -> None:
        # 1. UnknownItemError
        if sku not in self._items:
            raise UnknownItemError(f"Unknown SKU: {sku}")

        # 2. ValueError for a quantity that is not a positive int
        if not isinstance(qty, int) or isinstance(qty, bool) or qty <= 0:
            raise ValueError("Quantity must be a positive integer")

        # 3. ValueError if day is earlier than the day of the last recorded movement
        if self._movements:
            last_day = self._movements[-1].day
            if day < last_day:
                raise ValueError(f"Day {day} is earlier than last movement day {last_day}")

    def _coerce_unit_cost(self, unit_cost) -> Decimal:
        if isinstance(unit_cost, float):
            raise TypeError("float unit_cost not allowed")
        if isinstance(unit_cost, int):
            dec = Decimal(unit_cost)
        elif isinstance(unit_cost, str):
            try:
                dec = Decimal(unit_cost)
            except Exception:
                raise ValueError("Invalid string for unit_cost")
        elif isinstance(unit_cost, Decimal):
            dec = unit_cost
        else:
            raise TypeError("unit_cost must be Decimal, int, or numeric string")

        if dec < 0:
            raise ValueError("unit_cost must not be negative")
        return dec

    def _on_hand_at(self, sku: str, location: str, as_of: datetime.date) -> int:
        qty = 0
        for m in self._movements:
            if m.sku != sku:
                continue
            if as_of and m.day > as_of:
                continue
            if m.kind == "receive" and m.location == location:
                qty += m.qty
            elif m.kind == "issue" and m.location == location:
                qty -= m.qty
            elif m.kind == "transfer":
                if m.location == location:
                    qty -= m.qty
                elif m.to_location == location:
                    qty += m.qty
        return qty

    def receive(self, day: datetime.date, sku: str, location: str, qty: int, unit_cost) -> Movement:
        self._validate_recording(day, sku, qty)

        cost_dec = self._coerce_unit_cost(unit_cost)

        m = Movement(
            seq=self._next_seq,
            day=day,
            kind="receive",
            sku=sku,
            qty=qty,
            location=location,
            to_location=None,
            unit_cost=cost_dec
        )
        self._movements.append(m)
        self._next_seq += 1
        return m

    def issue(self, day: datetime.date, sku: str, location: str, qty: int) -> Movement:
        self._validate_recording(day, sku, qty)

        # 4. InsufficientStockError
        available = self._on_hand_at(sku, location, day)
        if available < qty:
            raise InsufficientStockError(f"Insufficient stock in {location} for {sku}")

        m = Movement(
            seq=self._next_seq,
            day=day,
            kind="issue",
            sku=sku,
            qty=qty,
            location=location,
            to_location=None,
            unit_cost=None
        )
        self._movements.append(m)
        self._next_seq += 1
        return m

    def transfer(self, day: datetime.date, sku: str, from_location: str, to_location: str, qty: int) -> Movement:
        self._validate_recording(day, sku, qty)

        if from_location == to_location:
            raise ValueError("From and to locations must differ")

        available = self._on_hand_at(sku, from_location, day)
        if available < qty:
            raise InsufficientStockError(f"Insufficient stock in {from_location} for {sku}")

        m = Movement(
            seq=self._next_seq,
            day=day,
            kind="transfer",
            sku=sku,
            qty=qty,
            location=from_location,
            to_location=to_location,
            unit_cost=None
        )
        self._movements.append(m)
        self._next_seq += 1
        return m

    def movements(self, sku: Optional[str] = None, as_of: Optional[datetime.date] = None) -> list[Movement]:
        result = []
        for m in self._movements:
            if sku and m.sku != sku:
                continue
            if as_of and m.day > as_of:
                continue
            result.append(m)
        return result

    def on_hand(self, sku: str, location: Optional[str] = None, as_of: Optional[datetime.date] = None) -> int:
        if sku not in self._items:
            raise UnknownItemError(f"Unknown SKU: {sku}")

        qty = 0
        for m in self._movements:
            if m.sku != sku:
                continue
            if as_of and m.day > as_of:
                continue

            if location is None:
                # Sum all locations
                if m.kind == "receive":
                    qty += m.qty
                elif m.kind == "issue":
                    qty -= m.qty
                # Transfers net to zero for total inventory
            else:
                # Specific location
                if m.kind == "receive" and m.location == location:
                    qty += m.qty
                elif m.kind == "issue" and m.location == location:
                    qty -= m.qty
                elif m.kind == "transfer" and m.location == location:
                    qty -= m.qty
                elif m.kind == "transfer" and m.to_location == location:
                    qty += m.qty

        return qty

    def locations(self) -> list[str]:
        locs = set()
        for m in self._movements:
            locs.add(m.location)
            if m.to_location:
                locs.add(m.to_location)
        return sorted(locs)
