from __future__ import annotations

import datetime
from dataclasses import dataclass
from decimal import Decimal


class InventoryError(Exception):
    """Base exception for inventory operations."""
    pass


class UnknownItemError(InventoryError):
    """Raised when a SKU that was never added is requested."""
    pass


class InsufficientStockError(InventoryError):
    """Raised when taking more stock out of a location than it holds."""
    pass


@dataclass(frozen=True)
class Item:
    """Represents an inventory item."""
    sku: str
    name: str
    category: str

    def __post_init__(self):
        if not isinstance(self.sku, str) or not self.sku.strip():
            raise ValueError("SKU must be a non-empty string")
        if "," in self.sku:
            raise ValueError("SKU must not contain a comma")
        if not isinstance(self.name, str) or not self.name.strip():
            raise ValueError("Name must be a non-empty string")
        if "," in self.name:
            raise ValueError("Name must not contain a comma")
        if not isinstance(self.category, str) or not self.category.strip():
            raise ValueError("Category must be a non-empty string")
        if "," in self.category:
            raise ValueError("Category must not contain a comma")


@dataclass(frozen=True)
class Movement:
    """Represents a stock movement."""
    seq: int
    day: datetime.date
    kind: str
    sku: str
    qty: int
    location: str
    to_location: str | None
    unit_cost: Decimal | None

    def __post_init__(self):
        if not isinstance(self.seq, int) or isinstance(self.seq, bool):
            raise ValueError("Sequence number must be an integer")
        if self.seq <= 0:
            raise ValueError("Sequence number must be positive")

        if not isinstance(self.day, datetime.date):
            raise TypeError("Day must be a datetime.date object")

        if self.kind not in ("receive", "issue", "transfer"):
            raise ValueError("Kind must be 'receive', 'issue', or 'transfer'")

        if not isinstance(self.sku, str) or not self.sku.strip():
            raise ValueError("SKU must be a non-empty string")

        if not isinstance(self.qty, int) or isinstance(self.qty, bool):
            raise ValueError("Quantity must be an integer")
        if self.qty <= 0:
            raise ValueError("Quantity must be positive")

        if not isinstance(self.location, str) or not self.location.strip():
            raise ValueError("Location must be a non-empty string")
        if "," in self.location:
            raise ValueError("Location must not contain a comma")

        if self.kind == "transfer":
            if not isinstance(self.to_location, str) or not self.to_location.strip():
                raise ValueError("to_location must be a non-empty string for transfers")
            if "," in self.to_location:
                raise ValueError("to_location must not contain a comma")
        else:
            if self.to_location is not None:
                raise ValueError("to_location must be None for non-transfer movements")

        if self.kind == "receive":
            if not isinstance(self.unit_cost, Decimal):
                raise TypeError("unit_cost must be a Decimal for receipts")
        else:
            if self.unit_cost is not None:
                raise ValueError("unit_cost must be None for non-receipt movements")
