             return "".join(_render_node(n, context, autoescape) for n in node.else_body)

        return "".join(output_parts)

    return ""


def render(template: 'Template', context: Optional[Dict[str, Any]] = None) -> str:
    """Render a template with the given context."""
    if context is None:
        context = {}
    return "".join(_render_node(node, context, template.autoescape) for node in template.nodes)


class DictLoader:
    """Loader that loads templates from a dictionary."""
    def __init__(self, templates: Dict[str, str]):
        self.templates = templates

    def get_source(self, name: str) -> str:
        if name not in self.templates:
            raise TemplateNotFound(name)
        return self.templates[name]


class Template:
    """A compiled template."""
    def __init__(self, source: str, *, loader=None, autoescape: bool = False, name: Optional[str] = None):
        self.source = source
        self.loader = loader
        self.autoescape = autoescape
        self.name = name
        self.nodes = parse(source)

    def render(self, context: Optional[Dict[str, Any]] = None) -> str:
        return render(self, context)


class Environment:
    """Central registry for loading templates."""
    def __init__(self, loader=None, autoescape: bool = False):
        self.loader = loader
        self.autoescape = autoescape

    def get_template(self, name: str) -> Template:
        if self.loader is None:
            raise TemplateNotFound(name)
        source = self.loader.get_source(name)
        try:
            return Template(source, loader=self.loader, autoescape=self.autoescape, name=name)
        except TemplateSyntaxError:
            raise
        except Exception as e:
            raise TemplateSyntaxError(str(e), 1)

    def from_string(self, source: str) -> Template:
        return Template(source, loader=self.loader, autoescape=self.autoescape, name=None)
