import typing
from .lexer import tokenize, Token, TemplateSyntaxError

# --- AST Node Definitions ---

class Node:
    pass

class TextNode(Node):
    def __init__(self, text: str):
        self.text = text

class VarNode(Node):
    def __init__(self, expr: "Expression"):
        self.expr = expr

class IfNode(Node):
    def __init__(self, conditions: list[tuple["Condition", list[Node]]], else_body: list[Node] | None):
        self.conditions = conditions
        self.else_body = else_body

class ForNode(Node):
    def __init__(self, name: str, expr: "Expression", body: list[Node], else_body: list[Node] | None):
        self.name = name
        self.expr = expr
        self.body = body
        self.else_body = else_body

# --- Expression Nodes ---

class Expression:
    pass

class ValueExpr(Expression):
    """Represents an atom with filters."""
    def __init__(self, atom: "Atom", filters: list["Filter"]):
        self.atom = atom
        self.filters = filters

class CondExpr(Expression):
    """Represents a condition tree."""
    pass

class BoolOpExpr(CondExpr):
    def __init__(self, op: str, operands: list[CondExpr]):
        self.op = op
        self.operands = operands

class NotExpr(CondExpr):
    def __init__(self, operand: CondExpr):
        self.operand = operand

class CompareExpr(CondExpr):
    def __init__(self, left: ValueExpr, op: str, right: ValueExpr):
        self.left = left
        self.op = op
        self.right = right

class ValueCond(CondExpr):
    """A bare value expression used as a condition."""
    def __init__(self, expr: ValueExpr):
        self.expr = expr

class Atom:
    def __init__(self, type: str, value):
        self.type = type # 'string', 'int', 'name'
        self.value = value # string content, int value, or list of path segments

    def __repr__(self):
        return f"Atom({self.type}, {self.value})"

class Filter:
    def __init__(self, name: str, arg=None):
        self.name = name
        self.arg = arg

    def __repr__(self):
        return f"Filter({self.name}, {self.arg})"


# --- Helper Functions for Validation ---

RESERVED = {'and', 'or', 'not', 'in'}
COMPARISON_OPS = {'==', '!=', '<', '<=', '>', '>='}
LOGICAL_OPS = {'and', 'or', 'not'}

FILTER_NAMES = {
    'upper', 'lower', 'trim', 'length', 'first', 'last', 'reverse', 'join', 'default', 'truncate', 'items'
}

# Filters that require an argument
FILTERS_WITH_ARG = {'join', 'default', 'truncate'}


def parse(source: str) -> list[Node]:
    tokens = tokenize(source)
    parser = Parser(tokens)
    return parser.parse_template()


class Parser:
    def __init__(self, tokens: list[Token]):
        self.tokens = tokens
        self.pos = 0

    def peek(self) -> Token | None:
        if self.pos < len(self.tokens):
            return self.tokens[self.pos]
        return None

    def consume(self, expected_kind: str | None = None) -> Token:
        tok = self.peek()
        if tok is None:
            # Should not happen if logic is correct, but handle gracefully
            raise TemplateSyntaxError("unexpected end of template", 0)
        if expected_kind and tok.kind != expected_kind:
            raise TemplateSyntaxError(f"expected {expected_kind}, got {tok.kind}", tok.lineno)
        self.pos += 1
        return tok

    def parse_template(self) -> list[Node]:
        return self._parse_body(ending_keywords=set())

    def _parse_body(self, ending_keywords: set[str]) -> list[Node]:
        """Parse a sequence of nodes until an ending keyword is encountered."""
        body: list[Node] = []
        while True:
            tok = self.peek()
            if tok is None:
                # Unexpected end of template
                if ending_keywords:
                     # This case is handled in _parse_block, should not reach here if block is open
                     pass
                break

            if tok.kind == 'block':
                # Check if this block is an ending keyword for current context
                parts = tok.value.split(None, 1)
                if parts and parts[0] in ending_keywords:
                    # Do not consume, let the caller handle it
                    break

            node = self._parse_node()
            body.append(node)
        return body

    def _parse_node(self) -> Node:
        tok = self.peek()
        if tok is None:
            raise TemplateSyntaxError("unexpected end of template", 0)

        if tok.kind == 'text':
            self.consume()
            return TextNode(tok.value)
        elif tok.kind == 'var':
            self.consume()
            expr = self._parse_value_expression(tok.value, tok.lineno)
            return VarNode(expr)
        elif tok.kind == 'block':
            return self._parse_block()
        else:
            raise TemplateSyntaxError(f"unexpected token kind: {tok.kind}", tok.lineno)

    def _parse_block(self) -> Node:
        tok = self.consume('block')
        lineno = tok.lineno
        parts = tok.value.split(None, 1)
        if not parts:
            raise TemplateSyntaxError("empty block", lineno)

        cmd = parts[0]
        rest = parts[1] if len(parts) > 1 else ""

        if cmd == 'if':
            return self._parse_if(lineno, rest)
        elif cmd == 'for':
            return self._parse_for(lineno, rest)
        else:
            raise TemplateSyntaxError(f"unknown statement '{cmd}'", lineno)

    def _parse_if(self, lineno: int, condition_str: str) -> IfNode:
        conditions = []
        else_body = None

        while True:
            cond = self._parse_condition(condition_str, lineno)
            body = self._parse_body({'elif', 'else', 'endif'})
            conditions.append((cond, body))

            next_tok = self.peek()
            if next_tok is None:
                raise TemplateSyntaxError("unclosed if", lineno)

            if next_tok.kind != 'block':
                 # Should have been caught by body parsing ending at block
                 raise TemplateSyntaxError("unexpected token in if", next_tok.lineno)

            next_parts = next_tok.value.split(None, 1)
            cmd = next_parts[0] if next_parts else ""
            rest = next_parts[1] if len(next_parts) > 1 else ""

            if cmd == 'elif':
                self.consume()
                condition_str = rest
                # Continue loop to parse next condition/body
            elif cmd == 'else':
                self.consume()
                # Else takes no arguments
                if rest.strip():
                    raise TemplateSyntaxError("else takes no arguments", next_tok.lineno)

                else_body = self._parse_body({'endif'})

                # After else, we must see endif
                next_tok = self.peek()
                if next_tok is None or next_tok.kind != 'block' or next_tok.value.split(None,1)[0] != 'endif':
                     raise TemplateSyntaxError("expected endif after else", next_tok.lineno if next_tok else lineno)
                self.consume()
                break
            elif cmd == 'endif':
                self.consume()
                if rest.strip():
                    raise TemplateSyntaxError("endif takes no arguments", next_tok.lineno)
                break
            else:
                # Unexpected block tag inside if
                raise TemplateSyntaxError(f"unexpected tag '{cmd}' inside if", next_tok.lineno)

        return IfNode(conditions, else_body)

    def _parse_for(self, lineno: int, args_str: str) -> ForNode:
        # Format: for NAME in EXPR
        parts = args_str.split()
        if len(parts) < 3:
            raise TemplateSyntaxError("malformed for statement", lineno)

        name = parts[0]
        in_kw = parts[1]
        expr_str = " ".join(parts[2:])

        if in_kw != 'in':
            raise TemplateSyntaxError("expected 'in' in for statement", lineno)

        if not name.isidentifier() or name in RESERVED:
            raise TemplateSyntaxError(f"invalid loop variable name '{name}'", lineno)

        expr = self._parse_value_expression(expr_str, lineno)

        body = self._parse_body({'else', 'endfor'})

        else_body = None

        next_tok = self.peek()
        if next_tok is None:
            raise TemplateSyntaxError("unclosed for", lineno)

        if next_tok.kind != 'block':
             raise TemplateSyntaxError("unexpected token in for", next_tok.lineno)

        next_parts = next_tok.value.split(None, 1)
        cmd = next_parts[0] if next_parts else ""
        rest = next_parts[1] if len(next_parts) > 1 else ""

        if cmd == 'else':
            self.consume()
            if rest.strip():
                raise TemplateSyntaxError("else takes no arguments", next_tok.lineno)

            else_body = self._parse_body({'endfor'})

            next_tok = self.peek()
            if next_tok is None or next_tok.kind != 'block' or next_tok.value.split(None,1)[0] != 'endfor':
                raise TemplateSyntaxError("expected endfor after else", next_tok.lineno if next_tok else lineno)
            self.consume()
            if next_tok.value.split(None,1)[1].strip() if len(next_parts) > 1 else "":
                 pass # already checked
        elif cmd == 'endfor':
            self.consume()
            if rest.strip():
                 raise TemplateSyntaxError("endfor takes no arguments", next_tok.lineno)
        else:
            raise TemplateSyntaxError(f"unexpected tag '{cmd}' in for", next_tok.lineno)

        return ForNode(name, expr, body, else_body)


    # --- Expression Parsing ---

    def _tokenize_expr(self, s: str) -> list[str]:
        """Split expression string into tokens, respecting strings."""
        tokens = []
        current = ""
        i = 0
        n = len(s)
        while i < n:
            char = s[i]
            if char in ' \\t':
                if current:
                    tokens.append(current)
                    current = ""
                i += 1
            elif char in '\"':
                if current:
                    tokens.append(current)
                    current = ""
                quote = char
                start = i + 1
                i += 1
