        i = 0
        n = len(s)
        in_str = None

        while i < n:
            c = s[i]
            if in_str:
                if c == in_str:
                    in_str = None
                i += 1
            elif c in '\"':
                in_str = c
                i += 1
            else:
                found = False
                for op in ops:
