import collections.abc
import html
from typing import Any, Callable, Dict, List, Optional, Union

from .lexer import TemplateRenderError, TemplateNotFound, TemplateSyntaxError
from .parser import (
    Atom, BoolOpExpr, CompareExpr, CondExpr, Expression, Filter, ForNode,
    IfNode, Node, NotExpr, TextNode, ValueCond, ValueExpr, VarNode,
    parse,
)


class LoopContext(dict):
    """A dictionary-like object for loop metadata."""
    pass


def _resolve_segment(value: Any, segment: str, lineno: int) -> Any:
    """Resolve a single segment against a value."""
    if value is None:
        return None

    if isinstance(value, collections.abc.Mapping):
        return value.get(segment)

    if isinstance(value, (list, tuple)):
        if segment.isdigit():
            idx = int(segment)
            if 0 <= idx < len(value):
                return value[idx]
            return None
        return None

    # Attribute lookup
    if not segment.startswith('_'):
        return getattr(value, segment, None)

    return None


def _resolve_atom(atom: Atom, context: Dict[str, Any], lineno: int) -> Any:
    """Resolve an atom (string, int, or variable path) to a value."""
    if atom.type == 'string':
        return atom.value
    if atom.type == 'int':
        return atom.value

    # Variable path
    path = atom.value
    if not path:
        return None

    name = path[0]
    value = context.get(name)

    for segment in path[1:]:
        value = _resolve_segment(value, segment, lineno)

    return value


def _apply_filter(value: Any, filter: Filter, lineno: int) -> Any:
    """Apply a filter to a value."""
    name = filter.name
    arg = filter.arg

    # Helper to get text representation
    def to_text(v):
        return "" if v is None else str(v)

    if name == 'upper':
        return to_text(value).upper()
    elif name == 'lower':
        return to_text(value).lower()
    elif name == 'trim':
        return to_text(value).strip()
    elif name == 'length':
        if value is None:
            return 0
        try:
            return len(value)
        except TypeError:
            raise TemplateRenderError(f"length filter cannot be applied to {type(value).__name__}", lineno)
    elif name == 'first':
        if value is None or len(value) == 0:
            return None
        return value[0]
    elif name == 'last':
        if value is None or len(value) == 0:
            return None
        return value[-1]
    elif name == 'reverse':
        if value is None:
            return None
        if isinstance(value, str):
            return value[::-1]
        if isinstance(value, (list, tuple)):
            return list(value[::-1])
        try:
            return list(reversed(value))
        except TypeError:
            raise TemplateRenderError(f"reverse filter cannot be applied to {type(value).__name__}", lineno)
    elif name == 'join':
        if value is None:
            return ""
        if not isinstance(value, (list, tuple, collections.abc.Iterable)):
             raise TemplateRenderError(f"join filter requires an iterable", lineno)
        try:
            return arg.join(to_text(item) for item in value)
        except TypeError:
            raise TemplateRenderError(f"join filter failed on {type(value).__name__}", lineno)
    elif name == 'default':
        if value is None or value == "":
            return arg
        return value
    elif name == 'truncate':
        text = to_text(value)
        if len(text) > arg:
            return text[:arg] + "..."
        return text
    elif name == 'items':
        if value is None:
            return []
        if isinstance(value, collections.abc.Mapping):
            return list(value.items())
        raise TemplateRenderError("items filter requires a mapping", lineno)
    elif name == 'safe':
        return value
    elif name == 'escape':
        return html.escape(to_text(value), quote=True)
    else:
        raise TemplateRenderError(f"unknown filter '{name}'", lineno)


def _eval_expr(expr: ValueExpr, context: Dict[str, Any], lineno: int) -> Any:
    """Evaluate a value expression (atom + filters)."""
    val = _resolve_atom(expr.atom, context, lineno)
    for f in expr.filters:
        val = _apply_filter(val, f, lineno)
    return val


def _eval_condition(cond: CondExpr, context: Dict[str, Any], lineno: int) -> bool:
    """Evaluate a condition expression."""
    if isinstance(cond, ValueCond):
        val = _eval_expr(cond.expr, context, lineno)
        return bool(val)

    if isinstance(cond, BoolOpExpr):
        if cond.op == 'and':
            for operand in cond.operands:
                if not _eval_condition(operand, context, lineno):
                    return False
            return True
        elif cond.op == 'or':
            for operand in cond.operands:
                if _eval_condition(operand, context, lineno):
                    return True
            return False

    if isinstance(cond, NotExpr):
        return not _eval_condition(cond.operand, context, lineno)

    if isinstance(cond, CompareExpr):
        left = _eval_expr(cond.left, context, lineno)
        right = _eval_expr(cond.right, context, lineno)
        op = cond.op

        # Handle None comparisons safely if Python would raise TypeError
        try:
            if op == '==':
                return left == right
            if op == '!=':
                return left != right
            if op == '<':
                return left < right
            if op == '<=':
                return left <= right
            if op == '>':
                return left > right
            if op == '>=':
                return left >= right
        except TypeError:
            raise TemplateRenderError(f"cannot compare {type(left).__name__} and {type(right).__name__}", lineno)

    raise TemplateRenderError("invalid condition node", lineno)


def _render_node(node: Node, context: Dict[str, Any], autoescape: bool = False) -> str:
    """Render a single AST node."""
    if isinstance(node, TextNode):
        return node.text

    if isinstance(node, VarNode):
        # Assuming node has lineno or using 1 as fallback if parser didn't set it
        lineno = getattr(node, 'lineno', 1)
        val = _eval_expr(node.expr, context, lineno)

        # Check if the last filter was 'safe'
        last_filter_safe = False
        if node.expr.filters:
            if node.expr.filters[-1].name == 'safe':
                last_filter_safe = True
            elif node.expr.filters[-1].name == 'escape':
                 # escape filter already escaped, so autoescape shouldn't double escape
                 # But the rule says: "When escape is the last filter, autoescaping does not escape that output a second time."
                 # So we treat it as safe for autoescape purposes.
                 last_filter_safe = True

        text_val = "" if val is None else str(val)

        if autoescape and not last_filter_safe:
            return html.escape(text_val, quote=True)

        return text_val

    if isinstance(node, IfNode):
        lineno = getattr(node, 'lineno', 1)
        if _eval_condition(node.cond, context, lineno):
            return "".join(_render_node(n, context, autoescape) for n in node.body)
        elif node.else_body:
            return "".join(_render_node(n, context, autoescape) for n in node.else_body)
        return ""

    if isinstance(node, ForNode):
        lineno = getattr(node, 'lineno', 1)
        items = _eval_expr(node.expr, context, lineno)
        if items is None:
            items = []

        output_parts = []
        loop_ctx = LoopContext()
        try:
            # Try to convert to list to support length/index if possible, but keep iterator if huge?
            # Standard behavior: make it a list if not already a list/tuple to allow indexing/length in LoopContext
            if not isinstance(items, (list, tuple)):
                items = list(items)

            length = len(items)
            for i, item in enumerate(items):
                ctx = context.copy()
                ctx[node.name] = item
                loop_ctx['index0'] = i
                loop_ctx['index1'] = i + 1
                loop_ctx['first'] = i == 0
                loop_ctx['last'] = i == length - 1
                loop_ctx['length'] = length
                ctx['loop'] = loop_ctx

                for n in node.body:
                    output_parts.append(_render_node(n, ctx, autoescape))
        except TypeError:
            raise TemplateRenderError(f"cannot iterate over {type(items).__name__}", lineno)

        if not output_parts and node.else_body:
             return "".join(_render_node(n, context, autoescape) for n in node.else_body)

        return "".join(output_parts)

    return ""


def render(template: 'Template', context: Optional[Dict[str, Any]] = None) -> str:
    """Render a template with the given context."""
    if context is None:
        context = {}
    return "".join(_render_node(node, context, template.autoescape) for node in template.nodes)


class DictLoader:
    """Loader that loads templates from a dictionary."""
    def __init__(self, templates: Dict[str, str]):
        self.templates = templates

    def get_source(self, name: str) -> str:
        if name not in self.templates:
            raise TemplateNotFound(name)
        return self.templates[name]


class Template:
    """A compiled template."""
    def __init__(self, source: str, *, loader=None, autoescape: bool = False, name: Optional[str] = None):
        self.source = source
        self.loader = loader
        self.autoescape = autoescape
        self.name = name
        self.nodes = parse(source)

    def render(self, context: Optional[Dict[str, Any]] = None) -> str:
        return render(self, context)


class Environment:
    """Central registry for loading templates."""
    def __init__(self, loader=None, autoescape: bool = False):
        self.loader = loader
        self.autoescape = autoescape

    def get_template(self, name: str) -> Template:
        if self.loader is None:
            raise TemplateNotFound(name)
        source = self.loader.get_source(name)
        try:
            return Template(source, loader=self.loader, autoescape=self.autoescape, name=name)
        except TemplateSyntaxError:
            raise
        except Exception as e:
            raise TemplateSyntaxError(str(e), 1)

    def from_string(self, source: str) -> Template:
        return Template(source, loader=self.loader, autoescape=self.autoescape, name=None)
