import typing
from .lexer import tokenize, Token, TemplateSyntaxError

# --- AST Node Definitions ---

class Node:
    pass

class TextNode(Node):
    def __init__(self, text: str):
        self.text = text

class VarNode(Node):
    def __init__(self, expr: "Expression"):
        self.expr = expr

class IfNode(Node):
    def __init__(self, conditions: list[tuple["Condition", list[Node]]], else_body: list[Node] | None):
        self.conditions = conditions
        self.else_body = else_body

class ForNode(Node):
    def __init__(self, name: str, expr: "Expression", body: list[Node], else_body: list[Node] | None):
        self.name = name
        self.expr = expr
        self.body = body
        self.else_body = else_body

# --- Expression Nodes ---

class Expression:
    pass

class ValueExpr(Expression):
    """Represents an atom with filters."""
    def __init__(self, atom: "Atom", filters: list["Filter"]):
        self.atom = atom
        self.filters = filters

class CondExpr(Expression):
    """Represents a condition tree."""
    pass

class BoolOpExpr(CondExpr):
    def __init__(self, op: str, operands: list[CondExpr]):
        self.op = op
        self.operands = operands

class NotExpr(CondExpr):
    def __init__(self, operand: CondExpr):
        self.operand = operand

class CompareExpr(CondExpr):
    def __init__(self, left: ValueExpr, op: str, right: ValueExpr):
        self.left = left
        self.op = op
        self.right = right

class ValueCond(CondExpr):
    """A bare value expression used as a condition."""
    def __init__(self, expr: ValueExpr):
        self.expr = expr

class Atom:
    def __init__(self, type: str, value):
        self.type = type # 'string', 'int', 'name'
        self.value = value # string content, int value, or list of path segments

    def __repr__(self):
        return f"Atom({self.type}, {self.value})"

class Filter:
    def __init__(self, name: str, arg=None):
        self.name = name
        self.arg = arg

    def __repr__(self):
        return f"Filter({self.name}, {self.arg})"


# --- Helper Functions for Validation ---

RESERVED = {'and', 'or', 'not', 'in'}
COMPARISON_OPS = {'==', '!=', '<', '<=', '>', '>='}
LOGICAL_OPS = {'and', 'or', 'not'}

FILTER_NAMES = {
    'upper', 'lower', 'trim', 'length', 'first', 'last', 'reverse', 'join', 'default', 'truncate', 'items'
}

# Filters that require an argument
FILTERS_WITH_ARG = {'join', 'default', 'truncate'}


def parse(source: str) -> list[Node]:
    tokens = tokenize(source)
    parser = Parser(tokens)
    return parser.parse_template()


class Parser:
    def __init__(self, tokens: list[Token]):
        self.tokens = tokens
        self.pos = 0

    def peek(self) -> Token | None:
        if self.pos < len(self.tokens):
            return self.tokens[self.pos]
        return None

    def consume(self, expected_kind: str | None = None) -> Token:
        tok = self.peek()
        if tok is None:
            # Should not happen if logic is correct, but handle gracefully
            raise TemplateSyntaxError("unexpected end of template", 0)
        if expected_kind and tok.kind != expected_kind:
            raise TemplateSyntaxError(f"expected {expected_kind}, got {tok.kind}", tok.lineno)
        self.pos += 1
        return tok

    def parse_template(self) -> list[Node]:
        return self._parse_body(ending_keywords=set())

    def _parse_body(self, ending_keywords: set[str]) -> list[Node]:
        """Parse a sequence of nodes until an ending keyword is encountered."""
        body: list[Node] = []
        while True:
            tok = self.peek()
            if tok is None:
                # Unexpected end of template
                if ending_keywords:
                     # This case is handled in _parse_block, should not reach here if block is open
                     pass
                break

            if tok.kind == 'block':
                # Check if this block is an ending keyword for current context
                parts = tok.value.split(None, 1)
                if parts and parts[0] in ending_keywords:
                    # Do not consume, let the caller handle it
                    break

            node = self._parse_node()
            body.append(node)
        return body

    def _parse_node(self) -> Node:
        tok = self.peek()
        if tok is None:
            raise TemplateSyntaxError("unexpected end of template", 0)

        if tok.kind == 'text':
            self.consume()
            return TextNode(tok.value)
        elif tok.kind == 'var':
            self.consume()
            expr = self._parse_value_expression(tok.value, tok.lineno)
            return VarNode(expr)
        elif tok.kind == 'block':
            return self._parse_block()
        else:
            raise TemplateSyntaxError(f"unexpected token kind: {tok.kind}", tok.lineno)

    def _parse_block(self) -> Node:
        tok = self.consume('block')
        lineno = tok.lineno
        parts = tok.value.split(None, 1)
        if not parts:
            raise TemplateSyntaxError("empty block", lineno)

        cmd = parts[0]
        rest = parts[1] if len(parts) > 1 else ""

        if cmd == 'if':
            return self._parse_if(lineno, rest)
        elif cmd == 'for':
            return self._parse_for(lineno, rest)
        else:
            raise TemplateSyntaxError(f"unknown statement '{cmd}'", lineno)

    def _parse_if(self, lineno: int, condition_str: str) -> IfNode:
        conditions = []
        else_body = None

        while True:
            cond = self._parse_condition(condition_str, lineno)
            body = self._parse_body({'elif', 'else', 'endif'})
            conditions.append((cond, body))

            next_tok = self.peek()
            if next_tok is None:
                raise TemplateSyntaxError("unclosed if", lineno)

            if next_tok.kind != 'block':
                 # Should have been caught by body parsing ending at block
                 raise TemplateSyntaxError("unexpected token in if", next_tok.lineno)

            next_parts = next_tok.value.split(None, 1)
            cmd = next_parts[0] if next_parts else ""
            rest = next_parts[1] if len(next_parts) > 1 else ""

            if cmd == 'elif':
                self.consume()
                condition_str = rest
                # Continue loop to parse next condition/body
            elif cmd == 'else':
                self.consume()
                # Else takes no arguments
                if rest.strip():
                    raise TemplateSyntaxError("else takes no arguments", next_tok.lineno)

                else_body = self._parse_body({'endif'})

                # After else, we must see endif
                next_tok = self.peek()
                if next_tok is None or next_tok.kind != 'block' or next_tok.value.split(None,1)[0] != 'endif':
                     raise TemplateSyntaxError("expected endif after else", next_tok.lineno if next_tok else lineno)
                self.consume()
                break
            elif cmd == 'endif':
                self.consume()
                if rest.strip():
                    raise TemplateSyntaxError("endif takes no arguments", next_tok.lineno)
                break
            else:
                # Unexpected block tag inside if
                raise TemplateSyntaxError(f"unexpected tag '{cmd}' inside if", next_tok.lineno)

        return IfNode(conditions, else_body)

    def _parse_for(self, lineno: int, args_str: str) -> ForNode:
        # Format: for NAME in EXPR
        parts = args_str.split()
        if len(parts) < 3:
            raise TemplateSyntaxError("malformed for statement", lineno)

        name = parts[0]
        in_kw = parts[1]
        expr_str = " ".join(parts[2:])

        if in_kw != 'in':
            raise TemplateSyntaxError("expected 'in' in for statement", lineno)

        if not name.isidentifier() or name in RESERVED:
            raise TemplateSyntaxError(f"invalid loop variable name '{name}'", lineno)

        expr = self._parse_value_expression(expr_str, lineno)

        body = self._parse_body({'else', 'endfor'})

        else_body = None

        next_tok = self.peek()
        if next_tok is None:
            raise TemplateSyntaxError("unclosed for", lineno)

        if next_tok.kind != 'block':
             raise TemplateSyntaxError("unexpected token in for", next_tok.lineno)

        next_parts = next_tok.value.split(None, 1)
        cmd = next_parts[0] if next_parts else ""
        rest = next_parts[1] if len(next_parts) > 1 else ""

        if cmd == 'else':
            self.consume()
            if rest.strip():
                raise TemplateSyntaxError("else takes no arguments", next_tok.lineno)

            else_body = self._parse_body({'endfor'})

            next_tok = self.peek()
            if next_tok is None or next_tok.kind != 'block' or next_tok.value.split(None,1)[0] != 'endfor':
                raise TemplateSyntaxError("expected endfor after else", next_tok.lineno if next_tok else lineno)
            self.consume()
            if next_tok.value.split(None,1)[1].strip() if len(next_parts) > 1 else "":
                 pass # already checked
        elif cmd == 'endfor':
            self.consume()
            if rest.strip():
                 raise TemplateSyntaxError("endfor takes no arguments", next_tok.lineno)
        else:
            raise TemplateSyntaxError(f"unexpected tag '{cmd}' in for", next_tok.lineno)

        return ForNode(name, expr, body, else_body)


    # --- Expression Parsing ---

    def _tokenize_expr(self, s: str) -> list[str]:
        """Split expression string into tokens, respecting strings."""
        tokens = []
        current = ""
        i = 0
        n = len(s)
        while i < n:
            char = s[i]
            if char in ' \\t':
                if current:
                    tokens.append(current)
                    current = ""
                i += 1
            elif char in '\"':
                if current:
                    tokens.append(current)
                    current = ""
                quote = char
                start = i + 1
                i += 1
                while i < n and s[i] != quote:
                    i += 1
                if i >= n:
                    # Should be caught by lexer or here
                    raise TemplateSyntaxError("unclosed string in expression", 0)
                content = s[start:i]
                tokens.append(f"{quote}{content}{quote}")
                i += 1
            elif char in '|:.':
                if current:
                    tokens.append(current)
                    current = ""
                tokens.append(char)
                i += 1
            elif char in '!=' or char in '<=' or char in '>=' or char in '==':
                # Handle multi-char operators explicitly? 
                # Actually, the split logic above puts them as separate chars if not careful.
                # Let's refine.
                pass
            else:
                current += char
                i += 1
        if current:
            tokens.append(current)
        return tokens

    def _parse_condition(self, s: str, lineno: int) -> CondExpr:
        # We need to parse: or -> and -> not -> comparison -> value
        # Use recursive descent or precedence climbing.
        # Since there are no parentheses, we can parse left-to-right with precedence.

        # 1. Split by top-level 'or'
        or_parts = self._split_toplevel(s, 'or')
        if len(or_parts) > 1:
            operands = [self._parse_and(p.strip(), lineno) for p in or_parts]
            return BoolOpExpr('or', operands)

        return self._parse_and(s, lineno)

    def _parse_and(self, s: str, lineno: int) -> CondExpr:
        and_parts = self._split_toplevel(s, 'and')
        if len(and_parts) > 1:
            operands = [self._parse_not(p.strip(), lineno) for p in and_parts]
            return BoolOpExpr('and', operands)
        return self._parse_not(s, lineno)

    def _parse_not(self, s: str, lineno: int) -> CondExpr:
        s = s.strip()
        if s.startswith('not '):
            rest = s[4:]
            return NotExpr(self._parse_not(rest, lineno))
        return self._parse_comparison(s, lineno)

    def _parse_comparison(self, s: str, lineno: int) -> CondExpr:
        # Find a comparison operator at the top level (not inside strings or filters)
        # This is tricky because filters use ':' and '|'.
        # But filters are part of ValueExpr.
        # So we need to split into LHS and RHS based on comparison op.

        ops = ['==', '!=', '<=', '>=', '<', '>']
        best_idx = -1
        best_op = None

        # We need to scan for these ops. 
        # However, we must ensure we don't split inside a string literal or filter arg.
        # But comparison ops don't appear in filters/args typically unless it's a weird string.
        # Wait, `default:"=="` has == inside quotes. We must respect quotes.

        i = 0
        n = len(s)
        in_str = None

        while i < n:
            c = s[i]
            if in_str:
                if c == in_str:
                    in_str = None
                i += 1
            elif c in '\"':
                in_str = c
                i += 1
            else:
                found = False
                for op in ops:
                    if s.startswith(op, i):
                        # Check if it's a valid operator position (not part of variable path)
                        # Variable paths use ., filters use |, :.
                        # < > = ! are not part of identifiers.
                        # So if we find ==, != etc, it's an operator.
                        if best_idx == -1 or i < best_idx: # Take leftmost?
                            # Wait, `a < b < c` is syntax error.
                            # So if we find one, the rest must not contain another?
                            # Or just take the first one and recurse? 
                            # If we take the first, LHS is valid ValueExpr, RHS might have another.
                            # If RHS has another, it will be parsed as a condition, which might be invalid if it's not wrapped? 
                            # Actually, spec says "at most one comparison". 
                            # So if we see one, we split. 
                            # If the RHS contains another, it will be parsed as a Comparison or BoolOp.
                            # But wait, `a < b == c` ? 
                            # If we split at first `<`, LHS=`a`, RHS=`b == c`. 
                            # RHS parsed as comparison. That's allowed? 
                            # "at most one comparison between two value expressions" implies the tree shape.
                            # If I write `a < b == c`, it's `(a<b) == c`? Or `a < (b==c)`? 
                            # Standard python: chained comparisons. 
                            # But spec says "no parentheses" and "at most one comparison".
                            # Usually this means the grammar is `Value (OP Value)?`.
                            # So `a < b == c` is likely a syntax error or parsed as `(a < b) == c` where `(a<b)` is a Bool value used in ValueExpr? 
                            # ValueExpr atom is string/int/name-path. Bool is not a name-path or literal (true/false literals not defined).
                            # So `a < b` results in a Bool. Can a Bool be an Atom? No.
                            # So `a < b == c` should be a syntax error because LHS `a` is fine, RHS `b == c` is a Condition, not ValueExpr.
                            # So `_parse_value_expression` on RHS `b == c` should fail?
                            # Yes. So we just take the first operator.
                            if best_idx == -1:
                                best_idx = i
                                best_op = op
                                # Don't break, continue to see if there are others? 
                                # If there are others, it's an error? 
                                # "a < b < c is a syntax error". 
                                # If I just split at first, LHS=`a`, RHS=`b < c`. 
                                # RHS parse condition -> Comparison(`b`, `<`, `c`). 
                                # Then we return CompareExpr(`a`, `<`, CompareExpr(...)).
                                # But CompareExpr.right expects ValueExpr.
                                # So if RHS is a Condition, it's invalid.
                                # So effectively, finding more than one operator leads to invalid types.
                                pass
                if best_idx != -1:
                     # We found one. We can stop scanning for better? 
                     # Leftmost is fine.
                     break
                i += 1

        if best_idx != -1:
            left_str = s[:best_idx].strip()
            right_str = s[best_idx+len(best_op):].strip()

            left_val = self._parse_value_expression(left_str, lineno)
            right_val = self._parse_value_expression(right_str, lineno)

            return CompareExpr(left_val, best_op, right_val)

        return self._parse_value_condition(s, lineno)

    def _parse_value_condition(self, s: str, lineno: int) -> CondExpr:
        expr = self._parse_value_expression(s, lineno)
        return ValueCond(expr)

    def _parse_value_expression(self, s: str, lineno: int) -> ValueExpr:
        # Parse Atom followed by Filters
        s = s.strip()
        if not s:
            raise TemplateSyntaxError("empty expression", lineno)

        # Tokenize manually to handle |, :, ., strings
        # Let's use a simple tokenizer for expressions
        toks = self._tokenize_expr_simple(s, lineno)

        if not toks:
             raise TemplateSyntaxError("empty expression", lineno)

        # First token is Atom
        atom_tok = toks.pop(0)
        atom = self._parse_atom(atom_tok, lineno)

        filters = []
        while toks:
            if toks[0] != '|':
                raise TemplateSyntaxError("expected filter '|' or end of expression", lineno)
            toks.pop(0) # remove |
            if not toks:
                raise TemplateSyntaxError("missing filter name", lineno)

            filter_name = toks.pop(0)
            if not filter_name.isalpha() and not filter_name.isidentifier():
                 # Allow underscore? Names are [A-Za-z_][A-Za-z0-9_]*
                 if not (filter_name[0].isalpha() or filter_name[0]=='_'):
                     raise TemplateSyntaxError(f"invalid filter name '{filter_name}'", lineno)

            arg = None
            if toks and toks[0] == ':':
                toks.pop(0)
                if not toks:
                    raise TemplateSyntaxError(f"missing argument for filter '{filter_name}'", lineno)
                arg_tok = toks.pop(0)
                arg = self._parse_filter_arg(arg_tok, lineno)

            self._validate_filter(filter_name, arg, lineno)
            filters.append(Filter(filter_name, arg))

        return ValueExpr(atom, filters)

    def _tokenize_expr_simple(self, s: str, lineno: int) -> list[str]:
        tokens = []
        i = 0
        n = len(s)
        while i < n:
            c = s[i]
            if c in ' \\t':
                i += 1
                continue
            if c in '\"':
                quote = c
                start = i + 1
                i += 1
                while i < n and s[i] != quote:
                    i += 1
                if i >= n:
                    raise TemplateSyntaxError("unclosed string", lineno)
                content = s[start:i]
                tokens.append(f"{quote}{content}{quote}")
                i += 1
            elif c in '|:.':
                tokens.append(c)
                i += 1
            elif c in '0123456789' or (c == '-' and i + 1 < n and s[i+1].isdigit()):
                start = i
                if c == '-':
                    i += 1
                while i < n and s[i].isdigit():
                    i += 1
                tokens.append(s[start:i])
            elif c.isalpha() or c == '_':
                start = i
                while i < n and (s[i].isalnum() or s[i] == '_'):
                    i += 1
                tokens.append(s[start:i])
            else:
                # Handle operators like ==, !=, <, >, <=, >=
                # These are needed for splitting in conditions, but for ValueExpr they shouldn't appear at top level.
                # However, _tokenize_expr_simple is called from _parse_value_expression which expects only Atoms/Filters.
                # So if we see operators here, it's an error.
                # BUT, wait. _parse_comparison uses string slicing, not this tokenizer.
                # So this tokenizer is safe to reject operators.
                raise TemplateSyntaxError(f"unexpected character '{c}' in expression", lineno)
        return tokens

    def _parse_atom(self, tok: str, lineno: int) -> Atom:
        if tok.startswith('"') and tok.endswith('"'):
            return Atom('string', tok[1:-1])
        if tok.startswith("'") and tok.endswith("'"):
            return Atom('string', tok[1:-1])

        if tok.isdigit() or (tok.startswith('-') and tok[1:].isdigit()):
            return Atom('int', int(tok))

        # Variable path
        if not (tok[0].isalpha() or tok[0] == '_'):
            raise TemplateSyntaxError(f"invalid expression token '{tok}'", lineno)

        if tok in RESERVED:
            raise TemplateSyntaxError(f"reserved word '{tok}' cannot be used as name", lineno)

        # Path segments are separated by dots in the string? 
        # Wait, my tokenizer splits `.` as separate token.
        # So `user.name` becomes `['user', '.', 'name']`.
        # But I popped the first token `user` as the Atom.
        # I need to handle the path continuation.
        # Ah, the `_parse_value_expression` pops one token for atom, then expects `|`.
        # It does NOT handle `.` continuation. 
        # I need to modify `_parse_value_expression` to consume `.` segments for the Atom.

        # Let's fix _parse_value_expression to handle paths.
        # Actually, I should probably parse the full path in _parse_value_expression.

        raise TemplateSyntaxError("internal parser error", lineno)

    def _parse_filter_arg(self, tok: str, lineno: int):
        if tok.startswith('"') and tok.endswith('"'):
            return tok[1:-1]
        if tok.startswith("'") and tok.endswith("'"):
            return tok[1:-1]
        if tok.isdigit() or (tok.startswith('-') and tok[1:].isdigit()):
            return int(tok)
        raise TemplateSyntaxError(f"invalid filter argument '{tok}'", lineno)

    def _validate_filter(self, name: str, arg, lineno: int):
        if name not in FILTER_NAMES:
            raise TemplateSyntaxError(f"unknown filter '{name}'", lineno)

        if name in FILTERS_WITH_ARG:
            if arg is None:
                raise TemplateSyntaxError(f"filter '{name}' requires an argument", lineno)
            if name == 'truncate':
                if not isinstance(arg, int) or arg < 0:
                    raise TemplateSyntaxError("truncate requires non-negative integer argument", lineno)
            elif name == 'join':
                if not isinstance(arg, str):
                    raise TemplateSyntaxError("join requires string argument", lineno)
            elif name == 'default':
                if not isinstance(arg, (str, int)):
                    raise TemplateSyntaxError("default requires string or integer argument", lineno)
        else:
            if arg is not None:
                raise TemplateSyntaxError(f"filter '{name}' takes no arguments", lineno)


    def _split_toplevel(self, s: str, keyword: str) -> list[str]:
        """Split string by keyword, but only when not inside strings."""
        parts = []
        current = ""
        i = 0
        n = len(s)
        kw_len = len(keyword)
        in_str = None

        while i < n:
            if in_str:
                current += s[i]
                if s[i] == in_str:
                    in_str = None
                i += 1
            elif s[i] in '\"':
                in_str = s[i]
                current += s[i]
                i += 1
            elif s.startswith(keyword, i):
                # Check word boundary
                is_left_boundary = (i == 0 or not s[i-1].isalnum())
                is_right_boundary = (i + kw_len >= n or not s[i+kw_len].isalnum())

                if is_left_boundary and is_right_boundary:
                    parts.append(current)
                    current = ""
                    i += kw_len
                else:
                    current += s[i]
                    i += 1
            else:
                current += s[i]
                i += 1

        parts.append(current)
        return parts

