import html
from typing import Any, Dict, List, Optional, Union, Sequence, Set, Callable

from .lexer import TemplateError, TemplateRenderError, TemplateSyntaxError, TemplateNotFound
from .parser import (
    Node, TextNode, VarNode, IfNode, ForNode, 
    Expression, ValueExpr, CondExpr, Atom, Filter,
    BoolOpExpr, NotExpr, CompareExpr, ValueCond,
    ExtendsNode, BlockNode
)


class DictLoader:
    """A simple loader that stores templates in a dictionary."""

    def __init__(self, templates: Dict[str, str]):
        self.templates = templates

    def get_source(self, name: str) -> str:
        if name not in self.templates:
            raise TemplateNotFound(name)
        return self.templates[name]


class Environment:
    """Manages the template configuration and loading."""

    def __init__(self, loader=None, autoescape: bool = False):
        self.loader = loader
        self.autoescape = autoescape

    def get_template(self, name: str) -> 'Template':
        if not self.loader:
            raise TemplateNotFound(name)

        try:
            source = self.loader.get_source(name)
        except TemplateNotFound:
            raise

        return Template(source, loader=self.loader, autoescape=self.autoescape, name=name)

    def from_string(self, source: str) -> 'Template':
        return Template(source, loader=self.loader, autoescape=self.autoescape, name=None)


class Template:
    """A compiled template."""

    def __init__(self, source: str, *, loader=None, autoescape: bool = False, name: Optional[str] = None):
        self.source = source
        self.loader = loader
        self.autoescape = autoescape
        self.name = name

        # Parse the source
        # Import parse here to avoid circular imports if necessary, 
        # but parser should be independent.
        from .parser import parse
        self.nodes = parse(source, name=name)

    def render(self, **context: Any) -> str:
        """Render the template with the given context."""
        # 1. Resolve inheritance chain
        # We need to detect circular dependencies and load parents.
        # The spec says: "Parents are loaded through the rendering template's loader..."
        # And "A template's own name counts as loaded from the start"

        chain: List[Template] = []
        visited: Set[Optional[str]] = set()

        # Start with the current template
        current = self

        while True:
            if current.name is not None:
                if current.name in visited:
                    # Find the extends node that caused the loop
                    # This is tricky. We need to know WHICH template's extends caused it.
                    # The error should be at the extends tag of the template that re-loads the parent.
                    # If we are at `current`, and we are trying to go to parent `P`, but `P` is in `visited`.
                    # We need to find the ExtendsNode in `current`.

                    extends_node = None
                    for node in current.nodes:
                        if isinstance(node, TextNode) and not node.text.strip():
                            continue
                        if isinstance(node, ExtendsNode):
                            extends_node = node
                            break
                        break # First non-whitespace tag

                    line = getattr(extends_node, 'lineno', 1) if extends_node else 1
                    raise TemplateRenderError(f"circular inheritance detected: template '{current.name}' extends '{current.nodes[0].name if current.nodes and isinstance(current.nodes[0], ExtendsNode) else 'unknown'}'", line)

                visited.add(current.name)

            chain.append(current)

            # Check if current extends another
            first_tag = None
            for node in current.nodes:
                if isinstance(node, TextNode) and not node.text.strip():
                    continue
                first_tag = node
                break

            if isinstance(first_tag, ExtendsNode):
                parent_name = first_tag.name
                if not current.loader:
                    raise TemplateNotFound(parent_name)
                try:
                    parent_source = current.loader.get_source(parent_name)
                except TemplateNotFound:
                    raise TemplateNotFound(parent_name)
                except TemplateSyntaxError as e:
                    raise e

                # Create parent template object
                parent_template = Template(
                    parent_source, 
                    loader=current.loader, 
                    autoescape=self.autoescape, # Use the calling template's autoescape setting
                    name=parent_name
                )
                current = parent_template
            else:
                break

        # 2. Collect blocks from the chain
        # chain[0] is child, chain[-1] is base
        # We need a mapping: block_name -> list of BlockNodes in order of derivation (most derived first)
        block_defs: Dict[str, List[BlockNode]] = {}

        def find_blocks(nodes: List[Node], template: Template):
            for node in nodes:
                if isinstance(node, BlockNode):
                    if node.name not in block_defs:
                        block_defs[node.name] = []
                    # Append to the list. Order is most-derived (child) to least-derived (base)
                    # Since we iterate chain from child to base, appending gives correct order
                    block_defs[node.name].append(node)
                elif isinstance(node, IfNode):
                    find_blocks(node.body, template)
                    if node.else_body:
                        find_blocks(node.else_body, template)
                elif isinstance(node, ForNode):
                    find_blocks(node.body, template)
                    if node.else_body:
                        find_blocks(node.else_body, template)

        for tmpl in chain:
            find_blocks(tmpl.nodes, tmpl)

        # 3. Render the base template (the last in the chain) using block overrides
        base_template = chain[-1]

        # We need a context object that knows about the inheritance state (blocks and depth)
        # Or we pass it through the render function recursively.

        def render_node_list(nodes: List[Node], ctx: Dict[str, Any], autoescape: bool, chain_stack: List[Tuple[int, Dict[str, List[BlockNode]]]]) -> str:
            parts = []
            for node in nodes:
                parts.append(render_node(node, ctx, autoescape, chain_stack))
            return "".join(parts)

        def render_node(node: Node, ctx: Dict[str, Any], autoescape: bool, chain_stack: List[Tuple[int, Dict[str, List[BlockNode]]]]) -> str:
            if isinstance(node, TextNode):
                return node.text

            if isinstance(node, VarNode):
                lineno = getattr(node, 'lineno', 1)

                # Handle super()
                if node.expr.atom.type == 'name' and len(node.expr.atom.value) == 1 and node.expr.atom.value[0] == 'super':
                    # Check if we are inside a block
                    if not chain_stack:
                         raise TemplateRenderError("super() called outside of block", lineno)

                    # The chain_stack contains (depth, block_defs).
                    # The current block being rendered is determined by who called us.
                    # Actually, `super()` inside a block needs to know the *name* of the current block 
                    # and the *current depth* of the block definition being rendered.
                    # 
                    # This approach is flawed because `render_node` doesn't know it's inside a specific block.
                    # A better approach: When rendering a BlockNode, we inject a `super` callable into the context.
                    # But `super` is a keyword/callable in the template language. 
                    # The parser creates a VarNode for `super`. 
                    # 
                    # Let's check how the parser represents `{{ super() }}`. 
                    # It likely creates a VarNode with Atom name='super'.
                    # 
                    # To handle this cleanly:
                    # 1. When rendering a `BlockNode` at depth `i` for block `name`:
                    #    - Determine the next definition at depth `i+1` (or `i-1` depending on order).
                    #    - Create a callable `super()` that renders the *next* definition in the list.
                    #    - Inject this callable into the context as `super`.
                    #    - Render the block's body nodes with this modified context.
                    #    
                    # However, `chain_stack` isn't quite right for tracking "current block" context.
                    # I'll switch to passing the current block context explicitly in the context dict.

                    # If we have injected 'super' into ctx, we can just call it.
                    if 'super' in ctx and callable(ctx['super']):
                        return ctx['super']()
                    else:
                        raise TemplateRenderError("super() called outside of block", lineno)

                # Evaluate expression
                val = _eval_expr(node.expr, ctx, lineno)

                # Convert to string
                text_val = "" if val is None else str(val)

                # Check filters for safe/escape
                last_filter_safe = False
                if node.expr.filters:
                    last_filter = node.expr.filters[-1]
                    if last_filter.name in ('safe', 'escape'):
                        last_filter_safe = True

                if autoescape and not last_filter_safe:
                    return html.escape(text_val, quote=True)

                return text_val

            if isinstance(node, IfNode):
                lineno = getattr(node, 'lineno', 1)
                if _eval_condition(node.cond, ctx, lineno):
                    return render_node_list(node.body, ctx, autoescape, chain_stack)
                elif node.else_body:
                    return render_node_list(node.else_body, ctx, autoescape, chain_stack)
                return ""

            if isinstance(node, ForNode):
                lineno = getattr(node, 'lineno', 1)
                items = _eval_expr(node.expr, ctx, lineno)
                if items is None:
                    items = []

                output_parts = []
                try:
                    if not isinstance(items, (list, tuple)):
                        items = list(items)

                    length = len(items)
                    for i, item in enumerate(items):
                        loop_ctx = ctx.copy()
                        loop_ctx[node.name] = item
                        loop_ctx['loop'] = {
                            'index0': i,
                            'index1': i + 1,
                            'first': i == 0,
                            'last': i == length - 1,
                            'length': length
                        }

                        for n in node.body:
                            output_parts.append(render_node(n, loop_ctx, autoescape, chain_stack))
                except TypeError:
                    raise TemplateRenderError(f"cannot iterate over {type(items).__name__}", lineno)

                if not output_parts and node.else_body:
                    return render_node_list(node.else_body, ctx, autoescape, chain_stack)

                return "".join(output_parts)

            if isinstance(node, BlockNode):
                # Find the definition for this block in the chain
                # We need to know which template we are currently rendering to determine 
                # where in the block_defs list we should start.

                # But wait: We are rendering the BASE template. 
                # The base template has its own BlockNode. 
                # We need to look up `node.name` in `block_defs`.
                # The list `block_defs[node.name]` is ordered [most_derived, ..., base].
                # We want to start rendering from the MOST DERIVED definition?
                # No. The spec says: "rendering it renders its parent... every block in the parent is replaced by the child's block".
                # So when we are at the Base template's `{% block title %}`, we check if there is a more derived definition.
                # The `block_defs` list has [Child_Def, Base_Def].
                # We should render `Child_Def`'s body. 
                # But `Child_Def` might contain `{% super %}`, which should render `Base_Def`.

                # Problem: `render_node` is called on the Base's AST. 
                # When it hits `BlockNode` (which is the Base's block), we must redirect to the Child's block body?
                # Yes.

                if node.name not in block_defs:
                    # Should not happen if collected correctly, but handle gracefully
                    return ""

                definitions = block_defs[node.name]
                # definitions[0] is the most derived (child).
                # definitions[-1] is the base (which is `node`).

                # We render the most derived definition.
                target_block = definitions[0]
                depth = 0 # Index in definitions list

                return render_block_body(target_block, ctx, autoescape, block_defs, node.name, depth)

            return ""

        def render_block_body(
            block: BlockNode, 
            ctx: Dict[str, Any], 
            autoescape: bool,
            all_defs: Dict[str, List[BlockNode]],
            block_name: str,
            current_depth: int
        ) -> str:
            """
            Render the body of a specific block definition.
            current_depth: Index in the chain of block definitions (0 = most derived).
            """
            # Create the 'super' callable for this level
            defs = all_defs[block_name]

            if current_depth + 1 < len(defs):
                next_depth = current_depth + 1
                next_block = defs[next_depth]

                def super_func():
                    # Render the next level block body
                    # We must not escape the output of super() again if it's used in a VarNode? 
                    # The spec says "output of {{ super() }} ... is never escaped again".
                    # In my VarNode handler, I return ctx['super']() directly, bypassing escape. 
                    # So this is correct.
                    return render_block_body(next_block, ctx, autoescape, all_defs, block_name, next_depth)
            else:
                def super_func():
                    raise TemplateRenderError(f"no less derived definition of block '{block_name}'", getattr(block, 'lineno', 1))

            # Inject super into context
            # We create a new context copy to avoid polluting the original
            block_ctx = ctx.copy()
            block_ctx['super'] = super_func

            # Render the nodes inside this block definition
            return render_node_list(block.nodes, block_ctx, autoescape, []) # chain_stack not needed here

        # Initial context
        render_ctx = context.copy()

        # Start rendering the base template nodes
        # Note: We render the BASE template's AST. 
        # When we hit a BlockNode in the base, we redirect to the most derived block definition.
        return render_node_list(base_template.nodes, render_ctx, self.autoescape, [])


# Helper functions (same as before)

def _resolve_segment(value: Any, segment: str, lineno: int) -> Any:
    """Resolve a single segment against a value."""
    if value is None:
        return None

    if isinstance(value, (dict, object)) and hasattr(value, "__getitem__"):
        try:
            return value[segment]
        except (KeyError, TypeError):
            pass

    if isinstance(value, (list, tuple)):
        if segment.isdigit():
            idx = int(segment)
            if 0 <= idx < len(value):
                return value[idx]
            return None
        return None

    # Attribute lookup
    if not segment.startswith('_'):
        return getattr(value, segment, None)

    return None


def _resolve_atom(atom: Atom, context: Dict[str, Any], lineno: int) -> Any:
    """Resolve an atom (string, int, or variable path) to a value."""
    if atom.type == 'string':
        return atom.value
    if atom.type == 'int':
        return atom.value

    # Variable path
    path = atom.value
    if not path:
        return None

    name = path[0]

    # Special case for super handled in VarNode, but if accessed as var:
    if name == 'super':
         # In standard Jinja-like engines, super is a function. 
         # If we reach here without a specific handler in VarNode, it might be undefined.
         # But VarNode handles it. This path is for non-VarNode contexts? 
         # Atoms appear in conditions too? No, conditions use exprs.
         # So this is likely not reached for 'super' in valid templates, 
         # or context['super'] might be set.
         return context.get('super')

    value = context.get(name)

    for segment in path[1:]:
        value = _resolve_segment(value, segment, lineno)

    return value


def _apply_filter(value: Any, filter: Filter, lineno: int) -> Any:
    """Apply a filter to a value."""
    name = filter.name
    arg = filter.arg

    def to_text(v):
        return "" if v is None else str(v)

    if name == 'upper':
        return to_text(value).upper()
    elif name == 'lower':
        return to_text(value).lower()
    elif name == 'trim':
        return to_text(value).strip()
    elif name == 'length':
        if value is None:
            return 0
        try:
            return len(value)
        except TypeError:
            raise TemplateRenderError(f"length filter cannot be applied to {type(value).__name__}", lineno)
    elif name == 'first':
        if value is None or len(value) == 0:
            return None
        return value[0]
    elif name == 'last':
        if value is None or len(value) == 0:
            return None
        return value[-1]
    elif name == 'reverse':
        if value is None:
            return None
        if isinstance(value, str):
            return value[::-1]
        if isinstance(value, (list, tuple)):
            return list(value[::-1])
        try:
            return list(reversed(value))
        except TypeError:
            raise TemplateRenderError(f"reverse filter cannot be applied to {type(value).__name__}", lineno)
    elif name == 'join':
        if value is None:
            return ""
        if not isinstance(value, (list, tuple)):
             raise TemplateRenderError(f"join filter requires a list or tuple", lineno)
        return arg.join(to_text(item) for item in value)
    elif name == 'default':
        if value is None or value == "":
            return arg
        return value
    elif name == 'truncate':
        text = to_text(value)
        if len(text) > arg:
            return text[:arg] + "..."
        return text
    elif name == 'safe':
        return value
    elif name == 'escape':
        return html.escape(to_text(value), quote=True)
    else:
        raise TemplateRenderError(f"unknown filter '{name}'", lineno)


def _eval_expr(expr: ValueExpr, context: Dict[str, Any], lineno: int) -> Any:
    """Evaluate a value expression (atom + filters)."""
    val = _resolve_atom(expr.atom, context, lineno)
    for f in expr.filters:
        val = _apply_filter(val, f, lineno)
    return val


def _eval_condition(cond: CondExpr, context: Dict[str, Any], lineno: int) -> bool:
    """Evaluate a condition expression."""
    if isinstance(cond, ValueCond):
        val = _eval_expr(cond.expr, context, lineno)
        return bool(val)

    if isinstance(cond, BoolOpExpr):
        if cond.op == 'and':
            for operand in cond.operands:
                if not _eval_condition(operand, context, lineno):
                    return False
            return True
        elif cond.op == 'or':
            for operand in cond.operands:
                if _eval_condition(operand, context, lineno):
                    return True
            return False

    if isinstance(cond, NotExpr):
        return not _eval_condition(cond.operand, context, lineno)

    if isinstance(cond, CompareExpr):
        left = _eval_expr(cond.left, context, lineno)
        right = _eval_expr(cond.right, context, lineno)
        op = cond.op

        try:
            if op == '==': return left == right
            if op == '!=': return left != right
            if op == '<': return left < right
            if op == '<=': return left <= right
            if op == '>': return left > right
            if op == '>=': return left >= right
        except TypeError:
            raise TemplateRenderError(f"cannot compare {type(left).__name__} and {type(right).__name__}", lineno)

    raise TemplateRenderError("invalid condition node", lineno)
