from dataclasses import dataclass
import re


class SQLError(Exception):
    """Base class for SQL-related errors."""
    pass


class SQLSyntaxError(SQLError):
    """Raised for syntax errors in SQL text."""
    def __init__(self, message, pos):
        super().__init__(message)
        self.pos = pos


@dataclass(frozen=True)
class Token:
    kind: str
    value: object
    pos: int


KEYWORDS = {
    "SELECT", "FROM", "WHERE", "AND", "OR", "NOT", "ORDER", "BY",
    "ASC", "DESC", "LIMIT", "IS", "NULL", "TRUE", "FALSE"
}

TOKEN_PATTERNS = [
    ("KEYWORD", re.compile(r"\b(SELECT|FROM|WHERE|AND|OR|NOT|ORDER|BY|ASC|DESC|LIMIT|IS|NULL|TRUE|FALSE)\b", re.IGNORECASE)),
    ("IDENT", re.compile(r"[A-Za-z_][A-Za-z0-9_]*")),
    ("NUMBER", re.compile(r"-?(?:\d+\.\d*|\d+)")),
    ("STRING", re.compile(r"'(?:[^']|'')*")),
    ("OP", re.compile(r"!=|<>|<=|>=|=|<|>")),
    ("STAR", re.compile(r"\*")),
    ("COMMA", re.compile(r",")),
    ("LPAREN", re.compile(r"\(")),
    ("RPAREN", re.compile(r"\)")),
]


def tokenize(sql: str) -> list[Token]:
    tokens = []
    i = 0
    n = len(sql)

    while i < n:
        # Skip whitespace
        if sql[i].isspace():
            i += 1
            continue

        # Try to match tokens
        matched = False
        for kind, pattern in TOKEN_PATTERNS:
            match = pattern.match(sql, i)
            if match:
                start = match.start()
                end = match.end()
                text = match.group(0)

                if kind == "KEYWORD":
                    value = text.upper()
                elif kind == "IDENT":
                    value = text
                elif kind == "NUMBER":
                    if "." in text:
                        value = float(text)
                    else:
                        value = int(text)
                elif kind == "STRING":
                    # Remove surrounding quotes and unescape double quotes
                    inner = text[1:-1]
                    value = inner.replace("''", "'")
                elif kind == "OP":
                    value = "!=" if text == "<>" else text
                else:
                    value = text

                tokens.append(Token(kind, value, start))
                i = end
                matched = True
                break

        if not matched:
            raise SQLSyntaxError(f"Unexpected character: {sql[i]}", i)

    tokens.append(Token("EOF", None, len(sql)))
    return tokens
