# minisql/execute.py

from .tokens import SQLError
from .parser import Select, Column, Literal, Compare, And, Or, Not, IsNull


class SQLExecutionError(SQLError):
    """Raised for errors during query execution."""
    pass


def query(sql: str, tables: dict) -> list[dict]:
    """Parse and execute a SQL query."""
    from .parser import parse
    stmt = parse(sql)
    return execute(stmt, tables)


def execute(stmt: Select, tables: dict) -> list[dict]:
    """Execute a parsed Select statement against in-memory tables."""
    # 1. Table lookup
    if stmt.table not in tables:
        raise SQLExecutionError(f"Unknown table: {stmt.table}")

    rows = tables[stmt.table]

    # 2. Filtering (WHERE)
    filtered_rows = []
    for row in rows:
        if stmt.where is None:
            keep = True
        else:
            keep = eval_condition(stmt.where, row)
            if keep is None or keep is False:
                continue
            # keep is True
        filtered_rows.append(row)

    # 3. Sorting (ORDER BY)
    if stmt.order_by:
        filtered_rows = sort_rows(filtered_rows, stmt.order_by)

    # 4. Limiting (LIMIT)
    if stmt.limit is not None:
        filtered_rows = filtered_rows[:stmt.limit]

    # 5. Projection
    result = []
    for row in filtered_rows:
        if stmt.columns is None:
            # Shallow copy of the row
            result.append(dict(row))
        else:
            # New dict with specific columns
            new_row = {}
            for col in stmt.columns:
                new_row[col] = row.get(col, None)
            result.append(new_row)

    return result


def get_operand_value(operand, row: dict):
    """Evaluate an operand (Column or Literal) to a Python value."""
    if isinstance(operand, Column):
        return row.get(operand.name, None)
    elif isinstance(operand, Literal):
        return operand.value
    else:
        raise SQLExecutionError(f"Invalid operand type: {type(operand)}")


def eval_condition(cond, row: dict):
    """Evaluate a condition returning True, False, or None (Unknown)."""
    if cond is None:
        return None

    if isinstance(cond, Compare):
        return eval_compare(cond, row)
    elif isinstance(cond, And):
        l = eval_condition(cond.left, row)
        r = eval_condition(cond.right, row)
        return and_logic(l, r)
    elif isinstance(cond, Or):
        l = eval_condition(cond.left, row)
        r = eval_condition(cond.right, row)
        return or_logic(l, r)
    elif isinstance(cond, Not):
        v = eval_condition(cond.operand, row)
        return not_logic(v)
    elif isinstance(cond, IsNull):
        v = get_operand_value(cond.operand, row)
        is_null = v is None
        if cond.negated:
            return not is_null
        return is_null
    else:
        raise SQLExecutionError(f"Invalid condition type: {type(cond)}")


def get_kind(value):
    """Determine the value kind: 'number', 'string', 'boolean', or None for NULL."""
    if value is None:
        return None
    if isinstance(value, bool):
        return 'boolean'
    if isinstance(value, (int, float)):
        return 'number'
    if isinstance(value, str):
        return 'string'
    raise SQLExecutionError(f"Unsupported value type: {type(value)}")


def eval_compare(comp: Compare, row: dict):
    """Evaluate a comparison with 3-valued logic."""
    left = get_operand_value(comp.left, row)
    right = get_operand_value(comp.right, row)

    # If either is NULL, result is Unknown
    if left is None or right is None:
        return None

    kind_l = get_kind(left)
    kind_r = get_kind(right)

    # If different kinds
    if kind_l != kind_r:
        if comp.op == '=':
            return False
        elif comp.op == '!=':
            return True
        else:
            raise SQLExecutionError(f"Cannot compare {kind_l} with {kind_r} using {comp.op}")

    # Same kind comparison
    op = comp.op

    # For booleans: False < True is standard Python
    # For numbers: standard
    # For strings: case-sensitive standard

    if op == '=':
        return left == right
    elif op == '!=':
        return left != right
    elif op == '<':
        return left < right
    elif op == '<=':
        return left <= right
    elif op == '>':
        return left > right
    elif op == '>=':
        return left >= right
    else:
        raise SQLExecutionError(f"Unknown operator: {op}")


def and_logic(a, b):
    if a is False or b is False:
        return False
    if a is None or b is None:
        return None
    return True


def or_logic(a, b):
    if a is True or b is True:
        return True
    if a is None or b is None:
        return None
    return False


def not_logic(a):
    if a is None:
        return None
    return not a


class SortValue:
    """Helper class for sorting with NULL handling and DESC option."""
    def __init__(self, value, descending):
        self.value = value
        self.descending = descending
        self.kind = get_kind(value)

    def __lt__(self, other):
        # NULLs first in ASC (so NULL < Val). NULLs last in DESC (so Val < NULL).
        if self.value is None and other.value is None:
            return False
        if self.value is None:
            # ASC: None is smaller (True). DESC: None is larger (False).
            return not self.descending
        if other.value is None:
            # ASC: Val > None, so Val < None is False. DESC: Val < None, so Val < None is True.
            return self.descending

        # Both not None. Kind should be consistent due to validation in sort_rows,
        # but let's be safe.
        if self.kind != other.kind:
             raise SQLExecutionError(f"Inconsistent types in sort: {self.kind} vs {other.kind}")

        if self.descending:
            return self.value > other.value
        else:
            return self.value < other.value

    def __eq__(self, other):
        return (self.value is other.value) or (self.value is not None and other.value is not None and self.value == other.value and self.kind == other.kind)


def validate_sort_types(rows, order_by):
    """Check that non-NULL values in each sort column are of the same kind."""
    for name, _ in order_by:
        kinds = set()
        for row in rows:
            val = row.get(name, None)
            if val is not None:
                kinds.add(get_kind(val))
        if len(kinds) > 1:
            raise SQLExecutionError(f"Mixed types in ORDER BY column '{name}': {kinds}")


def sort_rows(rows, order_by):
    """Sort rows using stable sort with custom keys."""
    if not order_by:
        return rows

    validate_sort_types(rows, order_by)

    # We use a tuple of SortValue objects as the key.
    # Python's sort is stable.

    def sort_key(row):
        return tuple(SortValue(row.get(name, None), descending) for name, descending in order_by)

    return sorted(rows, key=sort_key)
