import dataclasses
from typing import Any, Optional, Union

from .tokens import Token, SQLSyntaxError, tokenize

# --- AST Nodes ---

@dataclasses.dataclass(frozen=True)
class Column:
    name: str

@dataclasses.dataclass(frozen=True)
class Literal:
    value: Any

@dataclasses.dataclass(frozen=True)
class Compare:
    op: str
    left: Any
    right: Any

@dataclasses.dataclass(frozen=True)
class And:
    left: Any
    right: Any

@dataclasses.dataclass(frozen=True)
class Or:
    left: Any
    right: Any

@dataclasses.dataclass(frozen=True)
class Not:
    operand: Any

@dataclasses.dataclass(frozen=True)
class IsNull:
    operand: Any
    negated: bool

@dataclasses.dataclass(frozen=True)
class Select:
    columns: Optional[list[str]]
    table: str
    where: Optional[Any]
    order_by: list[tuple[str, bool]]
    limit: Optional[int]

# --- Parser ---

class Parser:
    def __init__(self, tokens: list[Token]):
        self.tokens = tokens
        self.pos = 0
        self.current = tokens[self.pos] if tokens else None

    def error(self, msg: str, pos: Optional[int] = None):
        if pos is None:
            pos = self.current.pos if self.current else len("...") # Fallback, usually handled by caller logic
            if self.current and self.current.kind == 'EOF':
                pos = self.current.pos
        raise SQLSyntaxError(msg, pos)

    def _advance(self):
        if self.current is not None and self.current.kind != 'EOF':
            self.pos += 1
            if self.pos < len(self.tokens):
                self.current = self.tokens[self.pos]
            else:
                self.current = Token('EOF', None, len("...") + 1) # Should be len(sql) from original, but we don't have sql string here easily. 
                # Better: The tokenizer returns EOF at len(sql). If we run off the end, it means we missed the EOF or input was empty.
                # Actually, tokens list always ends with EOF. So self.pos should never exceed len(tokens)-1 if we check correctly.
                # If current is EOF, we stay at EOF or error out.
                pass
        elif self.current is not None and self.current.kind == 'EOF':
            # Stay at EOF or error out depending on context. 
            # Usually means unexpected end of input if we try to advance past EOF.
            self.error("Unexpected end of statement", self.current.pos)

    def _match(self, kind: str, value: Optional[Any] = None) -> bool:
        if self.current is None:
            return False
        if self.current.kind != kind:
            return False
        if value is not None and self.current.value != value:
            return False
        return True

    def _accept(self, kind: str, value: Optional[Any] = None) -> Optional[Token]:
        if self._match(kind, value):
            tok = self.current
            self._advance()
            return tok
        return None

    def _expect(self, kind: str, value: Optional[Any] = None) -> Token:
        if self._match(kind, value):
            tok = self.current
            self._advance()
            return tok
        expected = f"{kind} '{value}'" if value is not None else kind
        actual = f"{self.current.kind} '{self.current.value}'" if self.current else "EOF"
        pos = self.current.pos if self.current else 0
        self.error(f"Expected {expected}, got {actual}", pos)
        return None # unreachable

    def parse_statement(self) -> Select:
        self._expect('KEYWORD', 'SELECT')
        columns = self.parse_select_list()

        self._expect('KEYWORD', 'FROM')
        table_token = self._expect('IDENT')
        table = table_token.value

        where = None
        if self._match('KEYWORD', 'WHERE'):
            self._advance()
            where = self.parse_condition()

        order_by = []
        if self._match('KEYWORD', 'ORDER'):
            self._advance()
            order_by = self.parse_order_by()

        limit = None
        if self._match('KEYWORD', 'LIMIT'):
            self._advance()
            limit = self.parse_limit()

        if self.current is not None and self.current.kind != 'EOF':
            self.error(f"Unexpected token {self.current.value}", self.current.pos)

        return Select(columns, table, where, order_by, limit)

    def parse_select_list(self) -> Optional[list[str]]:
        if self._match('STAR'):
            self._advance()
            return None # Represents *

        names = []
        seen = set()

        while True:
            name_token = self._expect('IDENT')
            name = name_token.value
            if name in seen:
                self.error(f"Duplicate column name '{name}'", name_token.pos)
            seen.add(name)
            names.append(name)

            if self._accept('COMMA'):
                continue
            else:
                break

        return names

    def parse_condition(self):
        # Condition := Condition OR Condition | Condition AND Condition | ...
        # Precedence: OR < AND < NOT < Atom
        return self.parse_or()

    def parse_or(self):
        left = self.parse_and()
        while self._match('KEYWORD', 'OR'):
            self._advance()
            right = self.parse_and()
            left = Or(left, right)
        return left

    def parse_and(self):
        left = self.parse_not()
        while self._match('KEYWORD', 'AND'):
            self._advance()
            right = self.parse_not()
            left = And(left, right)
        return left

    def parse_not(self):
        if self._match('KEYWORD', 'NOT'):
            self._advance()
            operand = self.parse_not() # Right-associative for NOT? Spec says NOT binds tighter than AND. 
            # "a = 1 OR b = 2 OR c = 3" is Or(Or(...), ...)
            # Standard logic: NOT applies to the next atom or NOT expression. 
            # If we have NOT NOT x, it should work.
            return Not(operand)
        return self.parse_comparison()

    def parse_comparison(self):
        # operand op operand | operand IS [NOT] NULL | ( condition )

        # Check for parenthesized condition
        if self._match('LPAREN'):
            self._advance()
            cond = self.parse_condition()
            self._expect('RPAREN')
            return cond

        # It must be an operand-based comparison
        # Parse first operand
        left = self.parse_operand()

        # Check for IS [NOT] NULL
        if self._match('KEYWORD', 'IS'):
            self._advance()
            negated = False
            if self._accept('KEYWORD', 'NOT'):
                negated = True
            self._expect('KEYWORD', 'NULL')
            return IsNull(left, negated)

        # Check for comparison operator
        if self._match('OP'):
            op_token = self.current
            op = op_token.value
            self._advance()
            right = self.parse_operand()
            return Compare(op, left, right)

        # If we are here, we parsed an operand but no operator followed.
        # A bare operand is not a condition.
        pos = self.current.pos if self.current else 0
        self.error("Expected comparison operator or IS NULL", pos)

    def parse_operand(self):
        # name | number | string | NULL | TRUE | FALSE
        if self._match('KEYWORD', 'NULL'):
            self._advance()
            return Literal(None)
        if self._match('KEYWORD', 'TRUE'):
            self._advance()
            return Literal(True)
        if self._match('KEYWORD', 'FALSE'):
            self._advance()
            return Literal(False)
        if self._match('IDENT'):
            tok = self._advance()
            return Column(tok.value) # type: ignore
        if self._match('NUMBER'):
            tok = self._advance()
            return Literal(tok.value) # type: ignore
        if self._match('STRING'):
            tok = self._advance()
            return Literal(tok.value) # type: ignore

        pos = self.current.pos if self.current else 0
        self.error("Expected operand", pos)

    def parse_order_by(self) -> list[tuple[str, bool]]:
        items = []
        while True:
            name_token = self._expect('IDENT')
            name = name_token.value

            descending = False
            if self._accept('KEYWORD', 'ASC'):
                descending = False
            elif self._accept('KEYWORD', 'DESC'):
                descending = True

            items.append((name, descending))

            if self._accept('COMMA'):
                continue
            else:
                break
        return items

    def parse_limit(self) -> int:
        tok = self._expect('NUMBER')
        val = tok.value
        if not isinstance(val, int) or val < 0:
            self.error("LIMIT expects a non-negative integer", tok.pos)
        return val

def parse(sql: str) -> Select:
    tokens = tokenize(sql)
    parser = Parser(tokens)
    return parser.parse_statement()

