            expr, key, pos = self.parse_select_item()

            # Check 1: Duplicate output key
            if key in seen_keys:
                self.error(f"Duplicate output key '{key}'", pos)

            seen_keys.add(key)
            items.append((expr, key))
            columns.append(key)

            if isinstance(expr, Aggregate):
                has_aggregate = True

            if self._accept('COMMA'):
                continue
            else:
                break

        return items, columns, False, -1, has_aggregate

    def parse_select_item(self) -> tuple[Any, str, int]:
        # item := (ref | aggregate) [AS name]
        start_tok = self.current

        expr = None
        canonical_text = None

        # Check for Aggregate: func ( ... )
        # Keywords: COUNT, SUM, AVG, MIN, MAX
        if self._match('KEYWORD') and self.current.value.upper() in ('COUNT', 'SUM', 'AVG', 'MIN', 'MAX'):
            func_name = self.current.value.upper()
            func_tok = self.current
            self._advance()

            self._expect('LPAREN')

            arg = None
            if func_name == 'COUNT' and self._match('STAR'):
                self._advance()
                arg = None
            else:
                arg_ref = self.parse_ref()
                arg = arg_ref

            self._expect('RPAREN')
            expr = Aggregate(func_name, arg, pos=func_tok.pos)
            canonical_text = expr.canonical_text()
        else:
            # It's a ref
            ref = self.parse_ref()
            expr = ref
            canonical_text = ref.name

        alias = None
        if self._accept('KEYWORD', 'AS'):
            alias_tok = self._expect('IDENT')
            alias = alias_tok.value

        key = alias if alias is not None else canonical_text

        return (expr, key, start_tok.pos)

    def parse_ref(self) -> Column:
        # ref := name | table . name
        if not self._match('IDENT') and not self._match('KEYWORD'):
             self.error("Expected identifier", self.current.pos if self.current else 0)

        # Keywords can't be names now, so expect IDENT
        name_tok = self._expect('IDENT')
        name_val = name_tok.value
        pos = name_tok.pos

        if self._match('DOT'):
            self._advance()
            table_tok = self._expect('IDENT')
            table_name = table_tok.value
            return Column(f"{name_val}.{table_name}", pos=pos)
        else:
            return Column(name_val, pos=pos)

    def parse_join(self) -> Join:
        # JOIN table ON ref = ref
        table_tok = self._expect('IDENT')
        table_name = table_tok.value

        self._expect('KEYWORD', 'ON')

        left_ref = self.parse_ref()
        self._expect('OP', '=')
        right_ref = self.parse_ref()

        return Join(table_name, left_ref, right_ref)

    def parse_condition(self):
        return self.parse_or()

    def parse_or(self):
        left = self.parse_and()
        while self._match('KEYWORD', 'OR'):
            self._advance()
            right = self.parse_and()
            left = Or(left, right)
        return left

    def parse_and(self):
        left = self.parse_not()
        while self._match('KEYWORD', 'AND'):
            self._advance()
            right = self.parse_not()
            left = And(left, right)
        return left

    def parse_not(self):
        if self._match('KEYWORD', 'NOT'):
            self._advance()
            operand = self.parse_not()
            return Not(operand)
        return self.parse_comparison()

    def parse_comparison(self):
        if self._match('LPAREN'):
            self._advance()
            cond = self.parse_condition()
            self._expect('RPAREN')
            return cond

        left = self.parse_operand()

        if self._match('KEYWORD', 'IS'):
            self._advance()
            negated = False
            if self._accept('KEYWORD', 'NOT'):
                negated = True
            self._expect('KEYWORD', 'NULL')
            return IsNull(left, negated)

        if self._match('OP'):
            op_token = self.current
            op = op_token.value
            self._advance()
            right = self.parse_operand()
            return Compare(op, left, right)

        pos = self.current.pos if self.current else 0
        self.error("Expected comparison operator or IS NULL", pos)

    def parse_operand(self):
        if self._match('KEYWORD', 'NULL'):
            self._advance()
            return Literal(None)
        if self._match('KEYWORD', 'TRUE'):
            self._advance()
            return Literal(True)
        if self._match('KEYWORD', 'FALSE'):
            self._advance()
            return Literal(False)

        if self._match('IDENT') or self._match('KEYWORD'):
            # Refs only. Aggregates not allowed here.
            # If it's a keyword like COUNT, parse_ref will fail or we handle error.
            # Spec: "Aggregates are not allowed in a condition."
            # If it's a keyword that is NOT a ref (like COUNT), we should error.
            # parse_ref expects IDENT. 
            if self._match('IDENT'):
                 return self.parse_ref()
            else:
                 # It's a KEYWORD. If it's not a valid operator/condition keyword, it's likely an error.
                 # But we are in parse_operand which expects value.
                 # If we see COUNT, we should error.
                 self.error("Aggregates are not allowed in conditions", self.current.pos)

        if self._match('NUMBER'):
            tok = self._advance()
            return Literal(tok.value)
        if self._match('STRING'):
            tok = self._advance()
            return Literal(tok.value)

        pos = self.current.pos if self.current else 0
        self.error("Expected operand", pos)

    def parse_group_by(self) -> list[str]:
        group_by = []
        while True:
            ref = self.parse_ref()
            group_by.append(ref.name)
            if self._accept('COMMA'):
                continue
            else:
                break
        return group_by

    def parse_order_by_details(self) -> list[tuple[str, bool, bool, int]]:
        """
        Returns list of (canonical_text, is_desc, is_aggregate, position)
        """
        items = []
        while True:
            start_tok = self.current
            is_aggregate = False
            expr_text = None

            if self._match('KEYWORD') and self.current.value.upper() in ('COUNT', 'SUM', 'AVG', 'MIN', 'MAX'):
                # Aggregate in ORDER BY
                func_name = self.current.value.upper()
                is_aggregate = True
                self._advance()
                self._expect('LPAREN')

                arg = None
                if func_name == 'COUNT' and self._match('STAR'):
                    self._advance()
                    expr_text = f"{func_name}(*)"
                else:
                    arg_ref = self.parse_ref()
                    expr_text = f"{func_name}({arg_ref.name})"

                self._expect('RPAREN')
                pos = start_tok.pos
            else:
                # Ref
                ref = self.parse_ref()
                expr_text = ref.name
                pos = start_tok.pos

            desc = False
            if self._accept('KEYWORD', 'ASC'):
                desc = False
            elif self._accept('KEYWORD', 'DESC'):
                desc = True

            items.append((expr_text, desc, is_aggregate, pos))

            if self._accept('COMMA'):
                continue
            else:
                break
        return items

    def parse_limit(self) -> int:
        tok = self._expect('NUMBER')
        val = tok.value
        if not isinstance(val, int) or val < 0:
            self.error("LIMIT expects a non-negative integer", tok.pos)
        return val

def parse(sql: str) -> Select:
    tokens = tokenize(sql)
    parser = Parser(tokens)
    return parser.parse_statement()
