from .tokens import SQLError
from .parser import (
    Select, Column, Aggregate, Join, Literal, 
    Compare, And, Or, Not, IsNull
)


class SQLExecutionError(SQLError):
    """Raised for errors during query execution."""
    pass


def query(sql: str, tables: dict) -> list[dict]:
    from .parser import parse
    stmt = parse(sql)
    return execute(stmt, tables)


def execute(stmt: Select, tables: dict) -> list[dict]:
    # 1. Validate Tables
    if stmt.table not in tables:
        raise SQLExecutionError(f"Unknown table: {stmt.table}")

    table_a = stmt.table
    table_b = stmt.join.table if stmt.join else None

    if stmt.join:
        if table_b not in tables:
            raise SQLExecutionError(f"Unknown table: {table_b}")
        if table_a == table_b:
            raise SQLExecutionError("JOIN tables must be different")

    # 2. Resolve Rows (Join or Filter)
    rows_a = tables[table_a]

    if stmt.join:
        rows_b = tables[table_b]
        join_rows = []

        # Determine join keys
        # left, right from stmt.join. One must be table_a.col, other table_b.col
        l_ref = stmt.join.left
        r_ref = stmt.join.right

        # Check qualification
        def get_col_parts(ref):
            if '.' not in ref.name:
                raise SQLExecutionError(f"Unqualified ref in join: {ref.name}")
            return ref.name.split('.', 1)

        l_t, l_c = get_col_parts(l_ref)
        r_t, r_c = get_col_parts(r_ref)

        if l_t == r_t:
            raise SQLExecutionError("Join condition must be between different tables")

        # Assign to A/B
        if l_t == table_a:
            a_col, b_col = l_c, r_c
            # Check r_t is table_b
            if r_t != table_b: raise SQLExecutionError(f"Unknown table {r_t}")
        elif l_t == table_b:
            a_col, b_col = r_c, l_c # Swap if reversed
            if l_t != table_b: raise SQLExecutionError(f"Unknown table {l_t}")
        else:
            raise SQLExecutionError(f"Unknown table {l_t}")

        # Perform Join
        for ra in rows_a:
            for rb in rows_b:
                va = ra.get(a_col)
                vb = rb.get(b_col)
                if values_equal(va, vb):
                    new_row = {}
                    for k, v in ra.items():
                        new_row[f"{table_a}.{k}"] = v
                    for k, v in rb.items():
                        new_row[f"{table_b}.{k}"] = v
                    join_rows.append(new_row)
        rows = join_rows
    else:
        # No join. Copy rows.
        # Keys are simple 'col'.
        rows = rows_a

    # 3. Helper to get value from row
    def get_val(ref, row):
        # ref is Column
        # In join context: key is 'table.col' in row dict, ref.name is 'table.col'
        # In non-join: key is 'col', ref.name is 'col' or 'table.col'
        if stmt.join:
            if '.' not in ref.name:
                raise SQLExecutionError(f"Unqualified ref in join context: {ref.name}")
            return row.get(ref.name)
        else:
            if '.' in ref.name:
                t, c = ref.name.split('.', 1)
                if t != table_a:
                    raise SQLExecutionError(f"Unknown table {t}")
                return row.get(c)
            else:
                return row.get(ref.name)

    # 4. WHERE Filter
    filtered = []
    for row in rows:
        if stmt.where is None:
            filtered.append(row)
        else:
            val = eval_cond(stmt.where, row, get_val)
            if val:
                filtered.append(row)

    # 5. Grouping
    has_agg = any(isinstance(e, Aggregate) for e, _ in stmt.items)
    is_grouped = bool(stmt.group_by) or has_agg

    groups = []

    if not is_grouped:
        # Standard behavior: each row is its own group/unit
        for row in filtered:
            groups.append([row])
    else:
        # Aggregation/GroupBy behavior
        if not stmt.group_by:
            # All rows in one group
            groups = [filtered]
        else:
            # Split by group by cols
            seen_groups = [] # Maintain order
            group_dict = {} # key tuple -> list of rows

            for row in filtered:
                key_vals = []
                for ref_text in stmt.group_by:
                    # Construct dummy Column to look up
                    col = Column(ref_text)
                    v = get_val(col, row)
                    key_vals.append(v)

                # Create hashable key (NULL handling)
                # Two NULLs match. Different types don't match (but same ref should be same type)
                # We can use a special object for None to ensure equality in tuple
                def safe_val(v):
                    return ('NULL',) if v is None else ('VAL', v)

                key_tuple = tuple(safe_val(v) for v in key_vals)

                if key_tuple not in group_dict:
                    group_dict[key_tuple] = []
                    seen_groups.append(key_tuple)

                group_dict[key_tuple].append(row)

            for k in seen_groups:
                groups.append(group_dict[k])

    # 6. Projection (Select Items)
    # Sort Units: list of (output_dict, source_rows)
    sort_units = []

    for group in groups:
        out_row = {}

        for expr, key in stmt.items:
            if isinstance(expr, Aggregate):
                val = calc_agg(expr, group, get_val)
            else:
                # Column
                if not group:
                    val = None
                else:
                    # In grouped mode, column must be in GROUP BY, so constant. Use first row.
                    # In non-grouped, group is single row list.
                    val = get_val(expr, group[0])
            out_row[key] = val

        sort_units.append((out_row, group))

    # 7. Order By
    if stmt.order_by:
        sort_units = do_sort(sort_units, stmt.order_by, stmt, get_val, is_grouped)

    # 8. Limit
    if stmt.limit is not None:
        sort_units = sort_units[:stmt.limit]

    # 9. Final Results
    results = []
    for out_row, group in sort_units:
        if stmt.columns is None:
            # SELECT *
            if not group:
                results.append({})
            else:
                # Return copy of source row (joined or original)
                # If non-grouped, group[0] is the row.
                # If grouped, * is not allowed (syntax error), so this branch only hit if non-grouped or empty?
                # Syntax error prevents * in grouped. So we are safe.
                results.append(dict(group[0]))
        else:
            results.append(out_row)

    return results


def calc_agg(agg, group, get_val):
    if agg.arg is None:
        return len(group)

    vals = []
    for row in group:
        v = get_val(agg.arg, row)
        if v is not None:
            vals.append(v)

    func = agg.func

    if func == 'COUNT':
        return len(vals)

    if not vals:
        return None

    if func == 'SUM':
        s = 0
        is_int = True
        for v in vals:
            if isinstance(v, bool) or not isinstance(v, (int, float)):
                 raise SQLExecutionError(f"SUM cannot handle {type(v)}")
            s += v
            if isinstance(v, float):
                is_int = False
        return int(s) if is_int else float(s)

    if func == 'AVG':
        s = 0
        for v in vals:
            if isinstance(v, bool) or not isinstance(v, (int, float)):
                raise SQLExecutionError(f"AVG cannot handle {type(v)}")
            s += v
        return s / len(vals)

    if func == 'MIN':
        return get_extreme(vals, True)

    if func == 'MAX':
        return get_extreme(vals, False)

    raise SQLExecutionError(f"Unknown agg {func}")


def get_extreme(vals, is_min):
    # Type check
    kinds = set()
    for v in vals:
        if v is None: continue
        if isinstance(v, bool): k = 'bool'
        elif isinstance(v, (int, float)): k = 'num'
        elif isinstance(v, str): k = 'str'
        else: raise SQLExecutionError("Unsupported type")
        kinds.add(k)

    if len(kinds) > 1:
        raise SQLExecutionError("Mixed types in MIN/MAX")

    return min(vals) if is_min else max(vals)


def do_sort(units, order_by, stmt, get_val, is_grouped):
    if not order_by:
        return units

    # Create sort keys
    # We need stable sort. Python sort is stable.
    # We need to handle NULLs (always last? Spec says "NULL placement ... as before")
    # Usually NULLs last. Let's assume last.

    def sort_key(unit):
        out_row, src_rows = unit
        keys = []
        for text, desc in order_by:
            val = None

            # Rule 6:
            # Grouped: text must match alias or canonical of select item.
            # Not Grouped: text matching alias -> out_row. Else ref -> src_row.

            # Check if text is a key in out_row (alias or canonical text of item)
            if text in out_row:
                val = out_row[text]
            else:
                if is_grouped:
                    raise SQLExecutionError(f"Order by {text} not in select list")
                else:
                    # Assume src_rows has 1 element for non-grouped
                    if not src_rows:
                        val = None
                    else:
                        # Try to get as column from first row
                        try:
                            val = get_val(Column(text), src_rows[0])
                        except Exception:
                            val = None

            # Handle NULL sorting (put last)
            # and Type mixing

            # We will use a custom key object to handle None and types
            keys.append(SortKey(val, desc))

        return keys

    return sorted(units, key=sort_key)

class SortKey:
    def __init__(self, val, reverse):
        self.val = val
        self.reverse = reverse

    def __lt__(self, other):
        # None is last
        if self.val is None and other.val is None: return False
        if self.val is None: return not self.reverse # If self is None, it should be larger (False for <) if normal, but if reverse...
        # Let's simplify: None is always greater than any value.
        # Normal Asc: 1 < 2 < None. 
        # If self.val is None, it is 'large'. So self < other is False (unless other is also None).
        # If other.val is None, self < other is True.

        # Wait, if reverse (DESC): None should be last? Spec says "NULL placement ... as before".
        # In standard SQL DESC, NULLs are last. 
        # So None is always "largest" in terms of sort order position (last).

        if self.val is None: return False # Never strictly less than another
        if other.val is None: return True # Anything < None

        # Type check
        t1 = type(self.val)
        t2 = type(other.val)

        # Normalize bool/int/float to 'num' or 'bool'?
        # Spec: "mixed-kind error". 
        # So bool vs int raises?

        k1 = get_kind(self.val)
        k2 = get_kind(other.val)

        if k1 != k2:
            # Should we raise? Usually sort allows mixed but errors? 
            # "The mixed-kind error ... as before". 
            # It likely raised in execution before. We will raise here.
            raise SQLExecutionError("Cannot sort mixed types")

        if self.val == other.val:
            return False

        # Values are comparable
        res = self.val < other.val
        return not res if self.reverse else res


def get_kind(v):
    if v is None: return 'null'
    if isinstance(v, bool): return 'bool'
    if isinstance(v, (int, float)): return 'num'
    if isinstance(v, str): return 'str'
    return 'unknown'


def eval_cond(node, row, get_val):
    if isinstance(node, And):
        return eval_cond(node.left, row, get_val) and eval_cond(node.right, row, get_val)
    if isinstance(node, Or):
        return eval_cond(node.left, row, get_val) or eval_cond(node.right, row, get_val)
    if isinstance(node, Not):
        return not eval_cond(node.operand, row, get_val)
    if isinstance(node, IsNull):
        v = get_val(node.operand, row) if isinstance(node.operand, Column) else node.operand.value
        res = v is None
        return not res if node.negated else res
    if isinstance(node, Compare):
        l_val = get_val(node.left, row) if isinstance(node.left, Column) else node.left.value
        r_val = get_val(node.right, row) if isinstance(node.right, Column) else node.right.value

        # Equality with type check
        if node.op == '=':
            return values_equal(l_val, r_val)
        if node.op == '!=':
            return not values_equal(l_val, r_val)

        # Ordering comparisons
        # NULLs make result NULL (False in WHERE)
        if l_val is None or r_val is None:
            return False

        # Type check
        k1 = get_kind(l_val)
        k2 = get_kind(r_val)
        if k1 != k2:
            # Raise? Or False? "mixed-kind error ... as before".
            # Usually raises.
            raise SQLExecutionError("Cannot compare mixed types")

        if node.op == '<': return l_val < r_val
        if node.op == '>': return l_val > r_val
        if node.op == '<=': return l_val <= r_val
        if node.op == '>=': return l_val >= r_val

    return False


def values_equal(a, b):
    if a is None or b is None: return False
    if get_kind(a) != get_kind(b): return False
    return a == b

