            normalized = self.name.replace(" ", "")
            object.__setattr__(self, 'name', normalized)

@dataclasses.dataclass(frozen=True)
class Aggregate:
    func: str
    arg: Optional[Column]  # None for COUNT(*)
    pos: int = 0

    def canonical_text(self):
        if self.arg is None:
            return f"{self.func}(*)"
        return f"{self.func}({self.arg.name})"

@dataclasses.dataclass(frozen=True)
class Join:
    table: str
    left: Column
    right: Column

@dataclasses.dataclass(frozen=True)
class Literal:
    value: Any

@dataclasses.dataclass(frozen=True)
class Compare:
    op: str
    left: Any
    right: Any

@dataclasses.dataclass(frozen=True)
