    left: Any
    right: Any

@dataclasses.dataclass(frozen=True)
class Or:
    left: Any
    right: Any

@dataclasses.dataclass(frozen=True)
class Not:
    operand: Any

@dataclasses.dataclass(frozen=True)
class IsNull:
    operand: Any
    negated: bool

@dataclasses.dataclass(frozen=True)
class Select:
    columns: Optional[list[str]]
    table: str
    where: Optional[Any]
    order_by: list[tuple[str, bool]]
    limit: Optional[int]
    items: list[tuple[Union[Column, Aggregate], str]] = []
    join: Optional[Join] = None
    group_by: list[str] = []

# --- Parser ---

class Parser:
    def __init__(self, tokens: list[Token]):
        self.tokens = tokens
        self.pos = 0
        self.current = tokens[self.pos] if tokens else None

    def error(self, msg: str, pos: Optional[int] = None):
        if pos is None:
            pos = self.current.pos if self.current else len("...")
            if self.current and self.current.kind == 'EOF':
                pos = self.current.pos
        raise SQLSyntaxError(msg, pos)

    def _advance(self):
        if self.current is not None and self.current.kind != 'EOF':
            self.pos += 1
            if self.pos < len(self.tokens):
                self.current = self.tokens[self.pos]
            else:
                self.current = Token('EOF', None, len("...") + 1)
        elif self.current is not None and self.current.kind == 'EOF':
            self.error("Unexpected end of statement", self.current.pos)

    def _match(self, kind: str, value: Optional[Any] = None) -> bool:
        if self.current is None:
            return False
        if self.current.kind != kind:
            return False
        if value is not None and self.current.value != value:
            return False
        return True

    def _accept(self, kind: str, value: Optional[Any] = None) -> Optional[Token]:
        if self._match(kind, value):
            tok = self.current
            self._advance()
            return tok
        return None

    def _expect(self, kind: str, value: Optional[Any] = None) -> Token:
        if self._match(kind, value):
            tok = self.current
            self._advance()
            return tok
        expected = f"{kind} '{value}'" if value is not None else kind
        actual = f"{self.current.kind} '{self.current.value}'" if self.current else "EOF"
        pos = self.current.pos if self.current else 0
        self.error(f"Expected {expected}, got {actual}", pos)
        return None # unreachable

    def parse_statement(self) -> Select:
        # 1. Parse SELECT list
        self._expect('KEYWORD', 'SELECT')
        items, columns, has_star, star_pos, has_aggregate = self.parse_select_list()

        # 2. Parse FROM
        self._expect('KEYWORD', 'FROM')
        table_token = self._expect('IDENT')
        table = table_token.value

        # 3. Parse JOIN
        join = None
        if self._match('KEYWORD', 'JOIN'):
            self._advance()
            join = self.parse_join()

        # 4. Parse WHERE
        where = None
        if self._match('KEYWORD', 'WHERE'):
            self._advance()
            where = self.parse_condition()

        # 5. Parse GROUP BY
        group_by = []
        has_group_by = False
        if self._match('KEYWORD', 'GROUP'):
            self._advance()
            self._expect('KEYWORD', 'BY')
            group_by = self.parse_group_by()
            has_group_by = True

        # Determine if query is "grouped"
        is_grouped = has_group_by or has_aggregate

        # Check 2: * in a grouped query
        if is_grouped and has_star:
            self.error("Cannot use * in a grouped query", star_pos)

        # Check 3: In grouped query, plain refs in SELECT must be in GROUP BY
        if is_grouped:
            group_set = set(group_by)
            for expr, key in items:
                if isinstance(expr, Column):
                    if expr.name not in group_set:
                        self.error(f"Column '{expr.name}' must appear in GROUP BY or be used in an aggregate function", expr.pos)

        # 6. Parse ORDER BY
        order_by = []
        if self._match('KEYWORD', 'ORDER'):
            self._advance()
            # order_by will store (canonical_text, is_descending, is_aggregate)
            order_by_details = self.parse_order_by_details()

            # Check 4: Aggregate in ORDER BY of non-grouped query
            if not is_grouped:
                for item_text, desc, is_agg in order_by_details:
                    if is_agg:
                        # Need position of aggregate. We stored pos in details? 
                        # Let's assume parse_order_by_details returns (text, desc, is_agg, pos)
                        pass

            # Format order_by for Select: list of (text, bool)
            order_by = [(text, desc) for text, desc, is_agg, pos in order_by_details]
            # Wait, I need to check Check 4 properly. I'll handle it in parse_order_by_details return or here.

        # Re-do Check 4 properly with position from parse_order_by_details
        if not is_grouped:
            # Re-parse or use stored info. 
            # I'll make parse_order_by_details return the info needed.
            # If I already called it, I have order_by_details.
            for item_text, desc, is_agg, pos in order_by_details:
                 if is_agg:
                     self.error("Aggregate functions are not allowed in ORDER BY of a non-grouped query", pos)

        # 7. Parse LIMIT
        limit = None
        if self._match('KEYWORD', 'LIMIT'):
            self._advance()
            limit = self.parse_limit()

        if self.current is not None and self.current.kind != 'EOF':
            self.error(f"Unexpected token {self.current.value}", self.current.pos)

        return Select(
            columns=columns,
            table=table,
            where=where,
            order_by=order_by,
            limit=limit,
            items=items,
            join=join,
            group_by=group_by
        )

    def parse_select_list(self) -> tuple[list[tuple[Any, str]], Optional[list[str]], bool, int, bool]:
        """
        Returns: (items, columns, has_star, star_pos, has_aggregate)
        """
        if self._match('STAR'):
            star_tok = self.current
            self._advance()
            # Check for duplicate keys? Only one item, so no dupes with itself.
            # But * is the only item. columns=None.
            return [], None, True, star_tok.pos, False

        items: list[tuple[Any, str]] = []
        columns: list[str] = []
        seen_keys = set()
        has_aggregate = False

        while True:
            expr, key, pos = self.parse_select_item()

            # Check 1: Duplicate output key
            if key in seen_keys:
                self.error(f"Duplicate output key '{key}'", pos)

            seen_keys.add(key)
            items.append((expr, key))
            columns.append(key)

            if isinstance(expr, Aggregate):
                has_aggregate = True

            if self._accept('COMMA'):
                continue
            else:
                break

        return items, columns, False, -1, has_aggregate

    def parse_select_item(self) -> tuple[Any, str, int]:
        # item := (ref | aggregate) [AS name]
        start_tok = self.current

        expr = None
        canonical_text = None

        # Check for Aggregate: func ( ... )
        # Keywords: COUNT, SUM, AVG, MIN, MAX
        if self._match('KEYWORD') and self.current.value.upper() in ('COUNT', 'SUM', 'AVG', 'MIN', 'MAX'):
            func_name = self.current.value.upper()
            func_tok = self.current
            self._advance()

            self._expect('LPAREN')

            arg = None
            if func_name == 'COUNT' and self._match('STAR'):
                self._advance()
                arg = None
            else:
                arg_ref = self.parse_ref()
                arg = arg_ref

            self._expect('RPAREN')
            expr = Aggregate(func_name, arg, pos=func_tok.pos)
            canonical_text = expr.canonical_text()
        else:
            # It's a ref
            ref = self.parse_ref()
            expr = ref
            canonical_text = ref.name

        alias = None
        if self._accept('KEYWORD', 'AS'):
            alias_tok = self._expect('IDENT')
            alias = alias_tok.value

        key = alias if alias is not None else canonical_text

        return (expr, key, start_tok.pos)

    def parse_ref(self) -> Column:
        # ref := name | table . name
        if not self._match('IDENT') and not self._match('KEYWORD'):
             self.error("Expected identifier", self.current.pos if self.current else 0)

        # Keywords can't be names now, so expect IDENT
        name_tok = self._expect('IDENT')
        name_val = name_tok.value
        pos = name_tok.pos

        if self._match('DOT'):
            self._advance()
            table_tok = self._expect('IDENT')
            table_name = table_tok.value
            return Column(f"{name_val}.{table_name}", pos=pos)
        else:
            return Column(name_val, pos=pos)

    def parse_join(self) -> Join:
        # JOIN table ON ref = ref
        table_tok = self._expect('IDENT')
        table_name = table_tok.value

        self._expect('KEYWORD', 'ON')

        left_ref = self.parse_ref()
        self._expect('OP', '=')
        right_ref = self.parse_ref()

        return Join(table_name, left_ref, right_ref)

    def parse_condition(self):
        return self.parse_or()

    def parse_or(self):
        left = self.parse_and()
        while self._match('KEYWORD', 'OR'):
            self._advance()
            right = self.parse_and()
            left = Or(left, right)
        return left

    def parse_and(self):
        left = self.parse_not()
        while self._match('KEYWORD', 'AND'):
            self._advance()
            right = self.parse_not()
            left = And(left, right)
        return left

    def parse_not(self):
        if self._match('KEYWORD', 'NOT'):
            self._advance()
            operand = self.parse_not()
            return Not(operand)
        return self.parse_comparison()

    def parse_comparison(self):
        if self._match('LPAREN'):
            self._advance()
            cond = self.parse_condition()
            self._expect('RPAREN')
            return cond

        left = self.parse_operand()

        if self._match('KEYWORD', 'IS'):
            self._advance()
            negated = False
            if self._accept('KEYWORD', 'NOT'):
                negated = True
            self._expect('KEYWORD', 'NULL')
            return IsNull(left, negated)

        if self._match('OP'):
            op_token = self.current
            op = op_token.value
            self._advance()
            right = self.parse_operand()
            return Compare(op, left, right)

        pos = self.current.pos if self.current else 0
        self.error("Expected comparison operator or IS NULL", pos)

    def parse_operand(self):
        if self._match('KEYWORD', 'NULL'):
            self._advance()
            return Literal(None)
        if self._match('KEYWORD', 'TRUE'):
            self._advance()
            return Literal(True)
        if self._match('KEYWORD', 'FALSE'):
            self._advance()
            return Literal(False)

        if self._match('IDENT') or self._match('KEYWORD'):
            # Refs only. Aggregates not allowed here.
            # If it's a keyword like COUNT, parse_ref will fail or we handle error.
            # Spec: "Aggregates are not allowed in a condition."
            # If it's a keyword that is NOT a ref (like COUNT), we should error.
            # parse_ref expects IDENT. 
            if self._match('IDENT'):
                 return self.parse_ref()
            else:
                 # It's a KEYWORD. If it's not a valid operator/condition keyword, it's likely an error.
                 # But we are in parse_operand which expects value.
                 # If we see COUNT, we should error.
                 self.error("Aggregates are not allowed in conditions", self.current.pos)

        if self._match('NUMBER'):
            tok = self._advance()
            return Literal(tok.value)
        if self._match('STRING'):
            tok = self._advance()
            return Literal(tok.value)

        pos = self.current.pos if self.current else 0
        self.error("Expected operand", pos)

    def parse_group_by(self) -> list[str]:
        group_by = []
        while True:
            ref = self.parse_ref()
            group_by.append(ref.name)
            if self._accept('COMMA'):
                continue
            else:
                break
        return group_by

    def parse_order_by_details(self) -> list[tuple[str, bool, bool, int]]:
        """
        Returns list of (canonical_text, is_desc, is_aggregate, position)
        """
        items = []
        while True:
            start_tok = self.current
            is_aggregate = False
            expr_text = None

            if self._match('KEYWORD') and self.current.value.upper() in ('COUNT', 'SUM', 'AVG', 'MIN', 'MAX'):
                # Aggregate in ORDER BY
                func_name = self.current.value.upper()
                is_aggregate = True
                self._advance()
                self._expect('LPAREN')

                arg = None
                if func_name == 'COUNT' and self._match('STAR'):
                    self._advance()
                    expr_text = f"{func_name}(*)"
                else:
                    arg_ref = self.parse_ref()
                    expr_text = f"{func_name}({arg_ref.name})"

                self._expect('RPAREN')
                pos = start_tok.pos
            else:
                # Ref
                ref = self.parse_ref()
                expr_text = ref.name
                pos = start_tok.pos

            desc = False
            if self._accept('KEYWORD', 'ASC'):
                desc = False
            elif self._accept('KEYWORD', 'DESC'):
                desc = True

            items.append((expr_text, desc, is_aggregate, pos))

            if self._accept('COMMA'):
                continue
            else:
                break
        return items

    def parse_limit(self) -> int:
        tok = self._expect('NUMBER')
        val = tok.value
        if not isinstance(val, int) or val < 0:
            self.error("LIMIT expects a non-negative integer", tok.pos)
        return val

def parse(sql: str) -> Select:
    tokens = tokenize(sql)
    parser = Parser(tokens)
    return parser.parse_statement()

