            lines.append("<tr>")
            for i, cell_text in enumerate(row):
                align = aligns[i] if i < len(aligns) else None
                if align:
                    lines.append(f'<td align="{align}">{render_inline(cell_text)}</td>')
                else:
                    lines.append(f"<td>{render_inline(cell_text)}</td>")
            lines.append("</tr>")
        lines.append("</tbody>")

    lines.append("</table>")
    return "\n".join(lines)


def render_block(block: tuple) -> str:
    kind = block[0]
    if kind == "heading":
        level = block[1]
        text = block[2]
        return f"<h{level}>{render_inline(text)}</h{level}>"
    elif kind == "paragraph":
        text = block[1]
        return f"<p>{render_inline(text)}</p>"
    elif kind == "code":
        lang = block[1]
        code = block[2]
        escaped_code = escape_html(code)
        if lang:
            escaped_lang = escape_html(lang)
            return f'<pre><code class="language-{escaped_lang}">{escaped_code}</code></pre>'
        else:
            return f'<pre><code>{escaped_code}</code></pre>'
    elif kind == "blockquote":
        children = block[1]
        inner = render_blocks(children)
        if inner:
            return f"<blockquote>\n{inner}\n</blockquote>"
        else:
            return "<blockquote>\n</blockquote>"
    elif kind == "list":
        ordered = block[1]
        start = block[2]
        items = block[3]

        if ordered:
            end_tag = "</ol>"
            if start != 1:
                start_tag = f'<ol start="{start}">'
            else:
                start_tag = "<ol>"
        else:
            start_tag = "<ul>"
            end_tag = "</ul>"

        rendered_items = []
        for item_data in items:
            # Handle new tuple format (text, children) or fallback to string
            if isinstance(item_data, tuple):
                text, children = item_data
            else:
                text, children = item_data, []

            if children:
                inner_blocks = render_blocks(children)
                item_str = f"<li>{render_inline(text)}\n{inner_blocks}\n</li>"
            else:
                item_str = f"<li>{render_inline(text)}</li>"
            rendered_items.append(item_str)

        joined_items = "\n".join(rendered_items)

        return f"{start_tag}\n{joined_items}\n{end_tag}"

    elif kind == "table":
        aligns = block[1]
        header = block[2]
        rows = block[3]
        return render_table(aligns, header, rows)

    elif kind == "hr":
        return "<hr />"
    else:
        # Should not happen if parser is correct
        return ""


def render_blocks(blocks: list) -> str:
    if not blocks:
        return ""
    rendered = [render_block(block) for block in blocks]
    return "\n".join(rendered)


def to_html(text: str) -> str:
    blocks = parse_blocks(text)
    if not blocks:
        return ""
    result = render_blocks(blocks)
    return result + "\n"

