from dataclasses import dataclass
from enum import Enum
from typing import Optional


class AccountType(Enum):
    ASSET = "asset"
    LIABILITY = "liability"
    EQUITY = "equity"
    INCOME = "income"
    EXPENSE = "expense"

    @property
    def is_debit_normal(self) -> bool:
        return self in (AccountType.ASSET, AccountType.EXPENSE)

    @property
    def is_credit_normal(self) -> bool:
        return self in (AccountType.LIABILITY, AccountType.EQUITY, AccountType.INCOME)


@dataclass(frozen=True)
class Account:
    code: str
    name: str
    type: AccountType
    parent: Optional[str] = None


class Chart:
    def __init__(self):
        self._accounts: dict[str, Account] = {}

    def _validate_code(self, code: str) -> None:
        if not code or not code.isdigit():
            raise ValueError("Code must be a non-empty string of digits")
        if code in self._accounts:
            raise ValueError(f"Code {code} already exists")

    def _validate_parent(self, parent: Optional[str]) -> None:
        if parent is not None and parent not in self._accounts:
            raise ValueError(f"Parent {parent} does not exist")

    def _validate_type(self, type_val: AccountType | str) -> AccountType:
        if isinstance(type_val, AccountType):
            return type_val
        if isinstance(type_val, str):
            try:
                return AccountType(type_val.lower())
            except ValueError:
                raise ValueError(f"Unknown account type: {type_val}")
        raise ValueError(f"Unknown account type: {type_val}")

    def _validate_parent_type_consistency(self, child_type: AccountType, parent_type: AccountType) -> None:
        if child_type != parent_type:
            raise ValueError(f"Parent type {parent_type.value} does not match child type {child_type.value}")

    def add(
        self,
        code: str,
        name: str,
        type: AccountType | str,
        parent: Optional[str] = None,
    ) -> Account:
        self._validate_code(code)
        self._validate_parent(parent)
        account_type = self._validate_type(type)

        if parent is not None:
            parent_account = self._accounts[parent]
            self._validate_parent_type_consistency(account_type, parent_account.type)

        account = Account(code=code, name=name, type=account_type, parent=parent)
        self._accounts[code] = account
        return account

    def get(self, code: str) -> Account:
        if code not in self._accounts:
            raise KeyError(code)
        return self._accounts[code]

    def children(self, code: str) -> list[Account]:
        if code not in self._accounts:
            raise KeyError(code)
        children = [acct for acct in self._accounts.values() if acct.parent == code]
        children.sort(key=lambda a: a.code)
        return children

    def roots(self) -> list[Account]:
        roots = [acct for acct in self._accounts.values() if acct.parent is None]
        roots.sort(key=lambda a: a.code)
        return roots

    def is_leaf(self, code: str) -> bool:
        if code not in self._accounts:
            raise KeyError(code)
        return not any(acct.parent == code for acct in self._accounts.values())

    def walk(self) -> list[tuple[Account, int]]:
        result = []

        def dfs(code: str, depth: int):
            account = self._accounts[code]
            result.append((account, depth))
            children = self.children(code)
            for child in children:
                dfs(child.code, depth + 1)

        for root in self.roots():
            dfs(root.code, 0)

        return result

    def descendants(self, code: str) -> list[str]:
        """Helper to get all descendant codes including self."""
        if code not in self._accounts:
            raise KeyError(code)
        codes = [code]
        children = self.children(code)
        for child in children:
            codes.extend(self.descendants(child.code))
        return codes

