import datetime
from dataclasses import dataclass
from decimal import Decimal, InvalidOperation
from typing import Any, NamedTuple

from .accounts import Account, AccountType, Chart


class UnbalancedEntryError(ValueError):
    pass


@dataclass(frozen=True)
class Line:
    account: str
    debit: Decimal
    credit: Decimal


@dataclass(frozen=True)
class Entry:
    number: int
    day: datetime.date
    memo: str
    lines: tuple[Line, ...]


class LedgerRow(NamedTuple):
    number: int
    day: datetime.date
    memo: str
    debit: Decimal
    credit: Decimal
    balance: Decimal


def _to_decimal(amount: Any) -> Decimal:
    if isinstance(amount, float):
        raise TypeError("Float not allowed; use Decimal, int, or str")

    try:
        val = Decimal(amount)
    except (InvalidOperation, TypeError, ValueError):
        raise ValueError(f"Invalid amount: {amount}")

    if val < 0:
        raise ValueError("Amount cannot be negative")

    if val.as_tuple().exponent < -2:
        raise ValueError("Amount cannot have more than two decimal places")

    return val


class Journal:
    def __init__(self, chart: Chart):
        self.chart = chart
        self._entries: list[Entry] = []

    def post(self, day: datetime.date, memo: str, lines: list[tuple]) -> Entry:
        if len(lines) < 2:
            raise ValueError("Entry must have at least two lines")

        processed_lines = []
        total_debit = Decimal(0)
        total_credit = Decimal(0)

        for line in lines:
            acc_code = line[0]
            debit_val = line[1] if len(line) > 1 else Decimal(0)
            credit_val = line[2] if len(line) > 2 else Decimal(0)

            # Check account exists and is leaf
            try:
                self.chart.get(acc_code)
            except KeyError:
                raise KeyError(f"Account {acc_code} not found")

            if not self.chart.is_leaf(acc_code):
                raise ValueError(f"Account {acc_code} is not a leaf")

            # Validate amounts
            debit_dec = _to_decimal(debit_val)
            credit_dec = _to_decimal(credit_val)

            # Exactly one of debit and credit is non-zero
            if debit_dec == 0 and credit_dec == 0:
                raise ValueError("Exactly one of debit or credit must be non-zero")
            if debit_dec > 0 and credit_dec > 0:
                raise ValueError("Exactly one of debit or credit must be non-zero")

            # If one is zero, the other must be non-zero (already checked both not zero)
            # And they can't both be positive

            line_obj = Line(account=acc_code, debit=debit_dec, credit=credit_dec)
            processed_lines.append(line_obj)

            total_debit += debit_dec
            total_credit += credit_dec

        if total_debit != total_credit:
            raise UnbalancedEntryError(f"Entry is unbalanced: debits={total_debit}, credits={total_credit}")

        number = len(self._entries) + 1
        entry = Entry(
            number=number,
            day=day,
            memo=memo,
            lines=tuple(processed_lines)
        )

        self._entries.append(entry)
        return entry

    def entries(self) -> list[Entry]:
        return list(self._entries)

    def balance(self, code: str, start: datetime.date | None = None, end: datetime.date | None = None) -> Decimal:
        # Determine account type
        try:
            account = self.chart.get(code)
        except KeyError:
            raise KeyError(f"Account {code} not found")

        is_debit_normal = account.type.is_debit_normal

        # Get all account codes in subtree
        relevant_accounts = set(self.chart.descendants(code))

        total_debit = Decimal(0)
        total_credit = Decimal(0)

        for entry in self._entries:
            if start is not None and entry.day < start:
                continue
            if end is not None and entry.day > end:
                continue

            for line in entry.lines:
                if line.account in relevant_accounts:
                    total_debit += line.debit
                    total_credit += line.credit

        if is_debit_normal:
            return total_debit - total_credit
        else:
            return total_credit - total_debit

    def ledger(self, code: str) -> list[LedgerRow]:
        try:
            account = self.chart.get(code)
        except KeyError:
            raise KeyError(f"Account {code} not found")

        is_debit_normal = account.type.is_debit_normal
        relevant_accounts = set(self.chart.descendants(code))

        rows = []
        running_balance = Decimal(0)

        for entry in self._entries:
            for line in entry.lines:
                if line.account in relevant_accounts:
                    # Determine effect on balance
                    if is_debit_normal:
                        delta = line.debit - line.credit
                    else:
                        delta = line.credit - line.debit

                    running_balance += delta

                    row = LedgerRow(
                        number=entry.number,
                        day=entry.day,
                        memo=entry.memo,
                        debit=line.debit,
                        credit=line.credit,
                        balance=running_balance
                    )
                    rows.append(row)

        return rows
