        except KeyError:
            raise KeyError(f"Account {code} not found")

        is_debit_normal = account.type.is_debit_normal

        # Get all account codes in subtree
        relevant_accounts = set(self.chart.descendants(code))

        total_debit = Decimal(0)
        total_credit = Decimal(0)

        for entry in self._entries:
            if start is not None and entry.day < start:
                continue
            if end is not None and entry.day > end:
                continue

            for line in entry.lines:
                if line.account in relevant_accounts:
                    total_debit += line.debit
                    total_credit += line.credit

        if is_debit_normal:
            return total_debit - total_credit
        else:
            return total_credit - total_debit

    def ledger(self, code: str) -> list[LedgerRow]:
        try:
            account = self.chart.get(code)
        except KeyError:
            raise KeyError(f"Account {code} not found")

        is_debit_normal = account.type.is_debit_normal
        relevant_accounts = set(self.chart.descendants(code))

        rows = []
        running_balance = Decimal(0)

        for entry in self._entries:
            for line in entry.lines:
                if line.account in relevant_accounts:
                    # Determine effect on balance
                    if is_debit_normal:
                        delta = line.debit - line.credit
                    else:
                        delta = line.credit - line.debit

                    running_balance += delta

                    row = LedgerRow(
                        number=entry.number,
                        day=entry.day,
                        memo=entry.memo,
                        debit=line.debit,
                        credit=line.credit,
                        balance=running_balance
                    )
                    rows.append(row)

        return rows
