        if path == "":
             path = "/"

        raw_segments = path.split("/")
        # Remove the first empty string if path starts with /
        if raw_segments and raw_segments[0] == "":
            raw_segments = raw_segments[1:]

        # Decode segments
        decoded_segments = []
        for seg in raw_segments:
            decoded_segments.append(_percent_decode_segment(seg))

        matching_handlers = []
        matched_any_path = False

        for pattern_str, route_method, pattern_segs, handler in self.routes:
            params = self._match_pattern(decoded_segments, pattern_segs)
            if params is not None:
                matched_any_path = True
                if route_method == method:
                    return handler, params
                matching_handlers.append(route_method)

        if not matched_any_path:
            raise NotFound(f"Path {path} not found")

        # Check for HEAD fallback
        if method == "HEAD":
            for pattern_str, route_method, pattern_segs, handler in self.routes:
                if route_method == "GET":
                    params = self._match_pattern(decoded_segments, pattern_segs)
                    if params is not None:
                         # Found a GET handler that matches path
                         return handler, params

        allowed_methods = sorted(set(matching_handlers))
        raise MethodNotAllowed(allowed_methods, f"Method {method} not allowed for path {path}")

    def dispatch(self, request: Request) -> Response:
        method = request.method
        path = request.path

        # If path is empty, treat as root? Request.path should be '/' or similar.
        # Spec says target starts with /. path is part before ?. So path starts with /.

        handler, params = self.resolve(method, path)

        # Populate params
        request.params.update(params)

        is_head_fallback = False
        # If we resolved via HEAD fallback to GET, we need to know that to strip body
        # resolve() doesn't tell us directly. 
        # We can re-check: if method was HEAD and handler found via GET logic.
        # Actually, in resolve, if method is HEAD and no HEAD route matches, but GET does,
        # it returns the GET handler.
        # How do we distinguish a real HEAD handler from a GET handler used for HEAD?
        # In dispatch, we don't know which route matched unless we track it.

        # Let's refine resolve to return the matched method too?
