        # and the handler is actually for GET, we strip body.
        # But we don't know if it's GET or HEAD from the return value of resolve.

        # Modification: resolve can return (handler, params, matched_method)
        # Let's adjust resolve to return matched_method.

        handler, params, matched_method = self._resolve_with_method(method, path)
        request.params.update(params)

        response = handler(request)

        if request.method == "HEAD" and matched_method == "GET":
            response.body = b""

        return response

    def _resolve_with_method(self, method: str, path: str) -> tuple[any, dict, str]:
        if path == "":
             path = "/"

        raw_segments = path.split("/")
        if raw_segments and raw_segments[0] == "":
            raw_segments = raw_segments[1:]

        decoded_segments = []
        for seg in raw_segments:
            decoded_segments.append(_percent_decode_segment(seg))

        matching_handlers = []
        matched_any_path = False

        for pattern_str, route_method, pattern_segs, handler in self.routes:
            params = self._match_pattern(decoded_segments, pattern_segs)
            if params is not None:
                matched_any_path = True
                if route_method == method:
                    return handler, params, route_method
                matching_handlers.append(route_method)

        if not matched_any_path:
            raise NotFound(f"Path {path} not found")

        if method == "HEAD":
            for pattern_str, route_method, pattern_segs, handler in self.routes:
                if route_method == "GET":
                    params = self._match_pattern(decoded_segments, pattern_segs)
                    if params is not None:
                         return handler, params, "GET"

        allowed_methods = sorted(set(matching_handlers))
        raise MethodNotAllowed(allowed_methods, f"Method {method} not allowed for path {path}")
