from dataclasses import dataclass, field
from typing import Any, Optional


REASON_PHRASES = {
    200: "OK",
    201: "Created",
    204: "No Content",
    400: "Bad Request",
    401: "Unauthorized",
    404: "Not Found",
    405: "Method Not Allowed",
    500: "Internal Server Error",
}


def get_reason(status: int) -> str:
    return REASON_PHRASES.get(status, "Unknown")


class HTTPError(Exception):
    def __init__(self, status: int = 500, reason: Optional[str] = None, message: str = ""):
        self.status = status
        self.reason = reason if reason is not None else get_reason(status)
        self.message = message
        super().__init__(message or f"{status} {self.reason}")


class BadRequest(HTTPError):
    def __init__(self, message: str = ""):
        super().__init__(status=400, message=message)


class Headers:
    def __init__(self, pairs=None):
        if pairs is None:
            pairs = []
        # Internal storage: list of tuples (original_name, value)
        self._items = []
        for name, value in pairs:
            self.add(name, value)

    def _normalize_name(self, name: str) -> str:
        return name.lower()

    def add(self, name: str, value: str):
        self._items.append((name, value))

    def set(self, name: str, value: str):
        normalized = self._normalize_name(name)
        found_index = -1
        new_items = []
        for i, (n, v) in enumerate(self._items):
            if self._normalize_name(n) == normalized:
                if found_index == -1:
                    found_index = i
                    new_items.append((name, value))
            else:
                new_items.append((n, v))

        if found_index == -1:
            self._items.append((name, value))
        else:
            self._items = new_items

    def get(self, name: str, default: Optional[str] = None) -> Optional[str]:
        normalized = self._normalize_name(name)
        for n, v in self._items:
            if self._normalize_name(n) == normalized:
                return v
        return default

    def get_all(self, name: str) -> list[str]:
        normalized = self._normalize_name(name)
        return [v for n, v in self._items if self._normalize_name(n) == normalized]

    def __getitem__(self, name: str) -> str:
        val = self.get(name)
        if val is None:
            raise KeyError(name)
        return val

    def __contains__(self, name: str) -> bool:
        return self.get(name) is not None

    def __len__(self) -> int:
        return len(self._items)

    def items(self) -> list[tuple[str, str]]:
        return list(self._items)


# Percent decoding helper matching query string rules
def percent_decode(s: str, plus_as_space: bool = True) -> str:
    # Process byte-by-byte essentially, but since we are dealing with strings here from headers/query
    # which are already decoded from bytes in the specific context of splitting?
    # No, the spec says: "In names and values, + means a space and %XX is a percent-escape; 
    # the decoded bytes are read as UTF-8."

    # Let's convert the string to bytes using latin-1 to preserve byte values for %XX processing?
    # Or better, process the string character by character.

    parts = s.split('%')
    decoded_bytes = bytearray()

    # The first part is literal
    current_part = parts[0]
    if plus_as_space:
        current_part = current_part.replace('+', ' ')
    try:
        decoded_bytes.extend(current_part.encode('latin-1'))
    except Exception:
        raise BadRequest("Invalid percent encoding")

    for part in parts[1:]:
        # Need at least two hex digits
        if len(part) < 2:
            raise BadRequest("Invalid percent encoding")
        hex_chars = part[:2]
        if not (hex_chars[0] in '0123456789abcdefABCDEF' and hex_chars[1] in '0123456789abcdefABCDEF'):
             # Check if they are valid hex digits strictly? The spec says "%XX".
             # Usually implies valid hex. If not, BadRequest.
             try:
                 int(hex_chars, 16)
             except ValueError:
                 raise BadRequest("Invalid percent encoding")

        byte_val = int(hex_chars, 16)
        decoded_bytes.append(byte_val)

        # Remaining part is literal again
        remainder = part[2:]
        if plus_as_space:
            remainder = remainder.replace('+', ' ')
        try:
            decoded_bytes.extend(remainder.encode('latin-1'))
        except Exception:
            raise BadRequest("Invalid percent encoding")

    try:
        return decoded_bytes.decode('utf-8')
    except UnicodeDecodeError:
        raise BadRequest("Invalid UTF-8 encoding in percent-decoded string")


@dataclass
class Request:
    method: str
    target: str
    path: str
    query_string: str
    version: str
    headers: Headers
    body: bytes
    params: dict[str, Any] = field(default_factory=dict)
    state: dict[str, Any] = field(default_factory=dict)

    @property
    def query(self) -> dict[str, list[str]]:
        result: dict[str, list[str]] = {}
        if not self.query_string:
            return result

        # Split on &
        pieces = self.query_string.split('&')

        for piece in pieces:
            if not piece:
                continue

            # Split at first =
            if '=' in piece:
                name_encoded, value_encoded = piece.split('=', 1)
            else:
                name_encoded = piece
                value_encoded = ''

            # Decode name and value
            # Note: The spec says "+" means a space. 
            name = percent_decode(name_encoded, plus_as_space=True)
            value = percent_decode(value_encoded, plus_as_space=True)

            if name in result:
                result[name].append(value)
            else:
