                        # If we are at the very end and expected an empty line?
                        # If pos == len(data), maybe okay?
                        # But spec says "followed by ... an empty line".
                        # If the data just ends, is it malformed? 
                        # Usually HTTP requires the final CRLF.
                        if pos < len(remaining_body_data):
                             raise BadRequest("Incomplete trailer section")
                        else:
                            break

                    next_line = remaining_body_data[pos:next_line_end]
                    pos = next_line_end + 2

                    if next_line == b'':
                        # Empty line marks end of trailers
                        break
                    # else: ignore trailer line

                # Now check for left over bytes
                if pos < len(remaining_body_data):
                    raise BadRequest("Bytes left over after body")

                # Break out of chunk loop
                break

            # Read chunk data
            if pos + chunk_size > len(remaining_body_data):
                raise BadRequest("Incomplete chunk data")

            chunk_data = remaining_body_data[pos : pos + chunk_size]
            body += chunk_data
            pos += chunk_size

            # Check for CRLF after chunk
            if pos + 2 > len(remaining_body_data) or remaining_body_data[pos:pos+2] != b'\r\n':
                raise BadRequest("Invalid chunk terminator")
            pos += 2

            # Loop continues to next chunk header

    elif cl is not None:
        # Multiple Content-Lengths check
        # "several Content-Length fields must all hold the same value"
        for val in cl_list:
            if val != cl:
                raise BadRequest("Inconsistent Content-Length headers")

        if not cl.isdigit():
            raise BadRequest("Invalid Content-Length")

        length = int(cl)

        if len(remaining_body_data) < length:
            raise BadRequest("Content-Length mismatch: too few bytes")

        body = remaining_body_data[:length]

        if len(remaining_body_data) > length:
            raise BadRequest("Bytes left over after body")

    else:
        # Neither header
        if len(remaining_body_data) > 0:
            # "With neither header the body is empty."
            # "Bytes left over after the body are an error."
            # If there is data, but no headers indicating body, is it an error?
            # Spec: "With neither header the body is empty." -> Body = b''.
            # Then: "Bytes left over after the body are an error." -> If remaining_body_data is not empty, it's left over. 
            raise BadRequest("Bytes left over after body")
        body = b''

    # Extract path and query_string
    if '?' in target:
        path, query_string = target.split('?', 1)
    else:
        path = target
        query_string = ''

    return Request(
        method=method,
        target=target,
        path=path,
        query_string=query_string,
        version=version,
        headers=headers,
        body=body
    )

from .request import HTTPError, BadRequest, Request, Response


class NotFound(HTTPError):
    def __init__(self, message: str = ""):
        super().__init__(status=404, message=message)


class MethodNotAllowed(HTTPError):
    def __init__(self, allowed: list[str], message: str = ""):
        super().__init__(status=405, message=message)
        self.allowed = sorted(allowed)


def _percent_decode_segment(s: str) -> str:
    """Percent-decode a path segment. '+' is literal '+'. Raises BadRequest on bad escapes."""
    parts = s.split('%')
    decoded_bytes = bytearray()

    # First part is literal
    decoded_bytes.extend(parts[0].encode('latin-1'))

    for part in parts[1:]:
        if len(part) < 2:
            raise BadRequest("Invalid percent encoding in path segment")
        hex_chars = part[:2]
        try:
            # Validate hex digits strictly
            if not (hex_chars[0] in '0123456789abcdefABCDEF' and hex_chars[1] in '0123456789abcdefABCDEF'):
                raise ValueError
            byte_val = int(hex_chars, 16)
        except ValueError:
            raise BadRequest("Invalid percent encoding in path segment")

        decoded_bytes.append(byte_val)
        remainder = part[2:]
        decoded_bytes.extend(remainder.encode('latin-1'))

    try:
        return decoded_bytes.decode('utf-8')
    except UnicodeDecodeError:
        raise BadRequest("Invalid UTF-8 encoding in percent-decoded path segment")


class Router:
    def __init__(self):
        # List of (pattern_string, method, segments, handler)
        # segments is list of (type, name, converter) or (type, literal)
        self.routes: list[tuple[str, str, list[tuple], any]] = []

    def _parse_pattern(self, pattern: str) -> list[tuple]:
        if not pattern.startswith("/"):
            raise ValueError("Pattern must start with /")

        raw_segments = pattern.split("/")[1:]  # Remove leading empty string

        parsed = []
        param_names = set()

        for i, seg in enumerate(raw_segments):
            is_last = (i == len(raw_segments) - 1)

            if not seg:
                raise ValueError("Empty segment in pattern")

            if seg.startswith("{") and seg.endswith("}"):
                inner = seg[1:-1]
                # Check for converter
                if ":" in inner:
                    name, converter = inner.split(":", 1)
                else:
                    name, converter = inner, None

                if not name:
                    raise ValueError("Parameter name cannot be empty")

                if name in param_names:
                    raise ValueError(f"Duplicate parameter name: {name}")
                param_names.add(name)

                if converter is not None:
                    if converter == "int":
                        parsed.append(("param", name, "int"))
                    elif converter == "path":
                        if not is_last:
                            raise ValueError("'path' converter must be the last segment")
                        parsed.append(("path_param", name))
                    else:
                        raise ValueError(f"Unknown converter: {converter}")
                else:
                    parsed.append(("param", name, None))
            else:
                # Literal segment
                # Note: In pattern, literals are usually not percent-encoded in the source code,
                # but they are matched against decoded segments.
                # So we store the literal as is.
                parsed.append(("literal", seg))

        return parsed

    def add(self, method: str, pattern: str, handler):
        parsed_segments = self._parse_pattern(pattern)

        # Check for duplicate method+pattern
        for p_str, m, _, _ in self.routes:
            if m == method and p_str == pattern:
                raise ValueError(f"Route already registered: {method} {pattern}")

        self.routes.append((pattern, method.upper(), parsed_segments, handler))

    def route(self, pattern: str, methods: tuple[str, ...] = ("GET",)):
        def decorator(func):
            for m in methods:
                self.add(m, pattern, func)
            return func
        return decorator

    def _match_pattern(self, path_segments: list[str], pattern_segments: list[tuple]) -> dict | None:
        """
        Try to match path_segments against pattern_segments.
        path_segments are already decoded.
        Returns dict of params if match, None otherwise.
        """
        params = {}
        p_idx = 0

        for i, p_seg in enumerate(pattern_segments):
            if p_seg[0] == "path_param":
                # path_param must be last in pattern
                # consumes all remaining path segments
                if i != len(pattern_segments) - 1:
                    return None # Should not happen if validation passed

                # Must consume at least one segment
                remaining = path_segments[p_idx:]
                if not remaining:
                    return None

                # Join remaining segments with /
                params[p_seg[1]] = "/".join(remaining)
                p_idx = len(path_segments)
                break

            if p_idx >= len(path_segments):
                return None

            path_val = path_segments[p_idx]

            if p_seg[0] == "literal":
                if path_val != p_seg[1]:
                    return None
                p_idx += 1
            elif p_seg[0] == "param":
                # Must not be empty
                if not path_val:
                    return None

                name, converter = p_seg[1], p_seg[2]
                if converter == "int":
                    if not path_val.isdigit():
                        return None
                    # ASCII digits only check
                    if not all('0' <= c <= '9' for c in path_val):
                        return None
                    params[name] = int(path_val)
                else:
                    params[name] = path_val
                p_idx += 1

        if p_idx != len(path_segments):
            return None

        return params

    def resolve(self, method: str, path: str) -> tuple[any, dict]:
        # Split path by '/', remove leading empty string from leading '/'
        # Note: path comes from Request.path which is already stripped of query string.
        # Request.path does not have a leading '/' according to spec? 
        # Spec: "path is the part before the first ?". Example: /users?id=1 -> /users.
        # So path starts with '/'.
        if path == "":
             path = "/"

        raw_segments = path.split("/")
        # Remove the first empty string if path starts with /
        if raw_segments and raw_segments[0] == "":
            raw_segments = raw_segments[1:]

        # Decode segments
        decoded_segments = []
        for seg in raw_segments:
            decoded_segments.append(_percent_decode_segment(seg))

        matching_handlers = []
        matched_any_path = False

        for pattern_str, route_method, pattern_segs, handler in self.routes:
            params = self._match_pattern(decoded_segments, pattern_segs)
            if params is not None:
                matched_any_path = True
                if route_method == method:
                    return handler, params
                matching_handlers.append(route_method)

        if not matched_any_path:
            raise NotFound(f"Path {path} not found")

        # Check for HEAD fallback
        if method == "HEAD":
            for pattern_str, route_method, pattern_segs, handler in self.routes:
                if route_method == "GET":
                    params = self._match_pattern(decoded_segments, pattern_segs)
                    if params is not None:
                         # Found a GET handler that matches path
                         return handler, params

        allowed_methods = sorted(set(matching_handlers))
        raise MethodNotAllowed(allowed_methods, f"Method {method} not allowed for path {path}")

    def dispatch(self, request: Request) -> Response:
        method = request.method
        path = request.path

        # If path is empty, treat as root? Request.path should be '/' or similar.
        # Spec says target starts with /. path is part before ?. So path starts with /.

        handler, params = self.resolve(method, path)

        # Populate params
        request.params.update(params)

        is_head_fallback = False
        # If we resolved via HEAD fallback to GET, we need to know that to strip body
        # resolve() doesn't tell us directly. 
        # We can re-check: if method was HEAD and handler found via GET logic.
        # Actually, in resolve, if method is HEAD and no HEAD route matches, but GET does,
        # it returns the GET handler.
        # How do we distinguish a real HEAD handler from a GET handler used for HEAD?
        # In dispatch, we don't know which route matched unless we track it.

        # Let's refine resolve to return the matched method too?
        # Or, simpler: In dispatch, if method is HEAD, and we call handler(request),
        # and the handler is actually for GET, we strip body.
        # But we don't know if it's GET or HEAD from the return value of resolve.

        # Modification: resolve can return (handler, params, matched_method)
        # Let's adjust resolve to return matched_method.

        handler, params, matched_method = self._resolve_with_method(method, path)
        request.params.update(params)

        response = handler(request)

        if request.method == "HEAD" and matched_method == "GET":
            response.body = b""

        return response

    def _resolve_with_method(self, method: str, path: str) -> tuple[any, dict, str]:
        if path == "":
             path = "/"

        raw_segments = path.split("/")
        if raw_segments and raw_segments[0] == "":
            raw_segments = raw_segments[1:]

        decoded_segments = []
        for seg in raw_segments:
            decoded_segments.append(_percent_decode_segment(seg))

        matching_handlers = []
        matched_any_path = False

        for pattern_str, route_method, pattern_segs, handler in self.routes:
            params = self._match_pattern(decoded_segments, pattern_segs)
            if params is not None:
                matched_any_path = True
                if route_method == method:
                    return handler, params, route_method
                matching_handlers.append(route_method)

        if not matched_any_path:
            raise NotFound(f"Path {path} not found")

        if method == "HEAD":
            for pattern_str, route_method, pattern_segs, handler in self.routes:
                if route_method == "GET":
                    params = self._match_pattern(decoded_segments, pattern_segs)
                    if params is not None:
                         return handler, params, "GET"

        allowed_methods = sorted(set(matching_handlers))
        raise MethodNotAllowed(allowed_methods, f"Method {method} not allowed for path {path}")

