import base64
from typing import Callable, List, Dict, Any

from .request import Request, Response, HTTPError, BadRequest, parse_request
from .router import Router, MethodNotAllowed


Middleware = Callable[[Request, Callable[[Request], Response]], Response]


class App:
    def __init__(self, router: Router, middleware: List[Middleware] = None):
        self.router = router
        if middleware is None:
            self.middleware = []
        else:
            self.middleware = list(middleware)

    def use(self, mw: Middleware):
        self.middleware.append(mw)

    def _make_error_response(self, error: HTTPError) -> Response:
        """Creates a Response from an HTTPError."""
        body_str = f"{error.status} {error.reason}"
        resp = Response.text(body_str, status=error.status)
        if isinstance(error, MethodNotAllowed):
            allow_header = ", ".join(error.allowed)
            resp.headers.set("Allow", allow_header)
        return resp

    def handle(self, request: Request) -> Response:
        # Innermost handler: router dispatch with error handling
        def core(req: Request) -> Response:
            try:
                return self.router.dispatch(req)
            except HTTPError as e:
                return self._make_error_response(e)
            except Exception as e:
                # Convert unexpected exceptions to 500 Internal Server Error
                return self._make_error_response(HTTPError(500))

        # Build the middleware chain
        # We wrap 'core' with middleware in reverse order so the first middleware
        # in self.middleware becomes the outermost layer.
        handler = core
        for mw in reversed(self.middleware):
            handler = self._wrap_middleware(mw, handler)

        return handler(request)

    def _wrap_middleware(self, mw: Middleware, next_handler: Callable[[Request], Response]) -> Callable[[Request], Response]:
        """Wraps a middleware function around the next handler."""
        def call(request: Request) -> Response:
            return mw(request, next_handler)
        return call

    def handle_bytes(self, data: bytes) -> bytes:
        try:
            request = parse_request(data)
        except BadRequest as e:
            # Return 400 error without running middleware
            error = HTTPError(status=400, reason="Bad Request")
            resp = self._make_error_response(error)
            return resp.to_bytes()

        response = self.handle(request)
        return response.to_bytes()


def logger(lines: List[str]) -> Middleware:
    """Factory for logging middleware."""
    def mw(request: Request, call_next: Callable[[Request], Response]) -> Response:
        response = call_next(request)
        log_entry = f"{request.method} {request.path} {response.status}"
        lines.append(log_entry)
        return response
    return mw


def cookies() -> Middleware:
    """Factory for cookie parsing middleware."""
    def mw(request: Request, call_next: Callable[[Request], Response]) -> Response:
        cookie_header = request.headers.get("Cookie")
        cookies_dict: Dict[str, str] = {}

        if cookie_header:
            # Split on semicolons
            parts = cookie_header.split(";")
            for part in parts:
                part = part.strip()
                if not part:
                    continue

                # Look for '='
                if "=" not in part:
                    continue

                name, value = part.split("=", 1)
                name = name.strip()
                value = value.strip()

                # Remove surrounding double quotes if present (one pair)
                if len(value) >= 2 and value.startswith('"') and value.endswith('"'):
                    value = value[1:-1]

                # First occurrence wins
                if name not in cookies_dict:
                    cookies_dict[name] = value

        request.state["cookies"] = cookies_dict
        return call_next(request)

    return mw


def basic_auth(users: Dict[str, str], realm: str = "app") -> Middleware:
    """Factory for basic authentication middleware."""
    def mw(request: Request, call_next: Callable[[Request], Response]) -> Response:
        auth_header = request.headers.get("Authorization")

        if not auth_header or not auth_header.startswith("Basic "):
            return _unauthorized(realm)

        try:
            encoded = auth_header[6:] # Skip "Basic "
            decoded_bytes = base64.b64decode(encoded)
            decoded_str = decoded_bytes.decode("utf-8")

            # Split at first colon
            if ":" not in decoded_str:
                return _unauthorized(realm)

            user, password = decoded_str.split(":", 1)

            if user in users and users[user] == password:
                request.state["user"] = user
                return call_next(request)
            else:
                return _unauthorized(realm)
        except Exception:
            # Handle decoding errors etc.
            return _unauthorized(realm)

    def _unauthorized(realm: str) -> Response:
        resp = Response.text("401 Unauthorized", status=401)
        resp.headers.set("WWW-Authenticate", f"Basic realm=\"{realm}\"")
        return resp

    return mw
