import re
from typing import Dict, Optional, Any
from .formula import (
    parse_formula, 
    references, 
    evaluate, 
    ErrorValue, 
    CYCLE,
    FormulaError
)
from .graph import DependencyGraph

# Valid cell name pattern: Single letter A-Z, then 1-999 (no leading zeros)
NAME_RE = re.compile(r'^[A-Z][1-9]\d*$')

def _validate_cell_name(name: str):
    if not isinstance(name, str):
        raise ValueError("Cell name must be a string")
    if not NAME_RE.match(name):
        raise ValueError(f"Invalid cell name: {name}")

class Sheet:
    def __init__(self):
        self.cells: Dict[str, Any] = {}
        self.formulas: Dict[str, str] = {}
        self.graph = DependencyGraph()
        self.evaluations = 0
        self._in_evaluation = set()

    def set_cell(self, name: str, value: str) -> None:
        """Set the content of a cell. 

        Args:
            name: Cell name (e.g., "A1").
            value: The string content (e.g., "10" or "=A1+1").
        """
        _validate_cell_name(name)

        if not isinstance(value, str):
            raise ValueError("Cell value must be a string")

        if value.startswith("="):
            formula_str = value[1:]
            try:
                tree = parse_formula(formula_str)
            except FormulaError:
                raise

            self.formulas[name] = value
            self.cells[name] = None # Temporarily clear until eval

            # Update graph
            refs = references(tree)
            self.graph.set_dependencies(name, refs)

        else:
            # Remove formula if exists
            if name in self.formulas:
                del self.formulas[name]
                self.graph.set_dependencies(name, set())

            self.cells[name] = value

    def get_cell(self, name: str) -> Optional[Any]:
        """Get the evaluated value of a cell.

        Args:
            name: Cell name.

        Returns:
            The evaluated value (int, float, str, or ErrorValue).
        """
        _validate_cell_name(name)

        # If it's a raw value (not a formula)
        if name not in self.formulas:
            return self.cells.get(name)

        # It is a formula
        # Check for cycles using a simple stack tracking during evaluation
        if name in self._in_evaluation:
            return CYCLE

        self._in_evaluation.add(name)
        self.evaluations += 1

        formula_str = self.formulas[name]
        try:
            tree = parse_formula(formula_str[1:])
            result = evaluate(tree, self._lookup)
        except FormulaError:
            # Should not happen if parse succeeded earlier, but just in case
            result = ErrorValue("#VALUE!")
        except Exception:
            result = ErrorValue("#VALUE!")
        finally:
            self._in_evaluation.remove(name)

        return result

    def _lookup(self, name: str) -> Any:
        """Internal lookup function for evaluate."""
        # We must ensure the name is valid before calling get_cell
        if not _is_valid_cell_name(name):
            return ErrorValue("#REF!")

        return self.get_cell(name)

    def row(self, row_num: int):
        """Return the values in a row."""
        # Not strictly required by prompt but part of "returned lists"?
        # Prompt says: "Everything else ... the returned lists ... works exactly as before."
        # Assuming standard sheet interface.
        pass

    def column(self, col_name: str):
        pass

    def range(self, start: str, end: str):
        """Return the values in a range."""
        # This might be used to get list of values
        # But the prompt focuses on formula evaluation.
        pass

    def clear(self):
        self.cells.clear()
        self.formulas.clear()
        self.graph.clear()
        self.evaluations = 0

