class Sheet:
    def __init__(self):
        self.cells: Dict[str, Any] = {}
        self.formulas: Dict[str, str] = {}
        self.graph = DependencyGraph()
        self.evaluations = 0
        self._in_evaluation = set()

    def set_cell(self, name: str, value: str) -> None:
        """Set the content of a cell. 

        Args:
            name: Cell name (e.g., "A1").
            value: The string content (e.g., "10" or "=A1+1").
        """
        _validate_cell_name(name)

        if not isinstance(value, str):
            raise ValueError("Cell value must be a string")

        if value.startswith("="):
            formula_str = value[1:]
            try:
                tree = parse_formula(formula_str)
            except FormulaError:
                raise

            self.formulas[name] = value
            self.cells[name] = None # Temporarily clear until eval

            # Update graph
            refs = references(tree)
            self.graph.set_dependencies(name, refs)

        else:
            # Remove formula if exists
            if name in self.formulas:
                del self.formulas[name]
                self.graph.set_dependencies(name, set())

            self.cells[name] = value

