import re
from typing import Callable, Any, Set, Union, List, Optional, Tuple


class FormulaError(ValueError):
    """Raised when a formula cannot be parsed or evaluated due to syntax errors."""
    pass


class ErrorValue(str):
    """Represents an error result in a cell.
    Subclasses str so it can be used in contexts expecting strings but carries
    error semantics.
    """
    pass


# Singleton error instances
DIV_ZERO = ErrorValue("#DIV/0!")
VALUE_ERROR = ErrorValue("#VALUE!")
REF_ERROR = ErrorValue("#REF!")
CYCLE = ErrorValue("#CYCLE!")


# AST Node Classes

class Number:
    def __init__(self, value: Union[int, float]):
        self.value = value

    def __repr__(self):
        return f"Number({self.value})"


class Ref:
    def __init__(self, name: str):
        # name is stored uppercase
        self.name = name

    def __repr__(self):
        return f"Ref({self.name})"


class Range:
    def __init__(self, start: str, end: str):
        self.start = start
        self.end = end

    def __repr__(self):
        return f"Range({self.start}, {self.end})"


class Call:
    def __init__(self, fname: str, args: List[Any]):
        self.fname = fname
        self.args = args

    def __repr__(self):
        return f"Call({self.fname}, {self.args})"


class UnaryOp:
    def __init__(self, op: str, operand: Any):
        self.op = op
        self.operand = operand

    def __repr__(self):
        return f"UnaryOp({self.op}, {self.operand})"


class BinOp:
    def __init__(self, op: str, left: Any, right: Any):
        self.op = op
        self.left = left
        self.right = right

    def __repr__(self):
        return f"BinOp({self.op}, {self.left}, {self.right})"


# Tokenizer

TOKEN_SPEC = [
    ('NUMBER',   r'\d+(?:\.\d+)?'),
    ('REF',      r'[A-Za-z]+\d+'),
    ('NAME',     r'[A-Za-z]+'),
    ('OP',       r'[+\-*/]'),
    ('LPAREN',   r'\('),
    ('RPAREN',   r'\)'),
    ('COMMA',    r','),
    ('COLON',    r':' ),
    ('WS',       r'\s+'),
]

TOKEN_RE = re.compile('|'.join(f'(?P<{name}>{pattern})' for name, pattern in TOKEN_SPEC))

FUNCTIONS = {'SUM', 'AVG', 'MIN', 'MAX'}


def _tokenize_strict(text: str):
    tokens = []
    pos = 0
    n = len(text)
    while pos < n:
        if text[pos].isspace():
            pos += 1
            continue

        match = TOKEN_RE.match(text, pos)
        if not match:
            raise FormulaError(f"Invalid character '{text[pos]}' at position {pos}")

        kind = match.lastgroup
        value = match.group()

        if kind == 'REF':
            name = value.upper()
            tokens.append(('REF', name))
            pos += len(value)

        elif kind == 'NUMBER':
            tokens.append(('NUMBER', value))
            pos += len(value)

        elif kind == 'NAME':
            name = value.upper()
            tokens.append(('NAME', name))
            pos += len(value)

        elif kind == 'OP':
            tokens.append(('OP', value))
            pos += len(value)

        elif kind == 'LPAREN':
            tokens.append(('LPAREN', value))
            pos += len(value)

        elif kind == 'RPAREN':
            tokens.append(('RPAREN', value))
            pos += len(value)

        elif kind == 'COMMA':
            tokens.append(('COMMA', value))
            pos += len(value)

        elif kind == 'COLON':
            tokens.append(('COLON', value))
            pos += len(value)

        else:
            raise FormulaError(f"Unexpected token {value}")

    return tokens


# Recursive Descent Parser

class Parser:
    def __init__(self, tokens):
        self.tokens = tokens
        self.pos = 0

    def peek(self, offset=0):
        if self.pos + offset < len(self.tokens):
            return self.tokens[self.pos + offset]
        return None

    def consume(self):
        token = self.peek()
        self.pos += 1
        return token

    def expect(self, kind):
        token = self.peek()
        if not token or token[0] != kind:
            raise FormulaError(f"Expected {kind}, got {token}")
        return self.consume()

    def parse_expr(self):
        node = self.parse_term()
        while self.peek() and self.peek()[0] == 'OP' and self.peek()[1] in ('+', '-'):
            op_token = self.consume()
            right = self.parse_term()
            node = BinOp(op_token[1], node, right)
        return node

    def parse_term(self):
        node = self.parse_unary()
        while self.peek() and self.peek()[0] == 'OP' and self.peek()[1] in ('*', '/'):
            op_token = self.consume()
            right = self.parse_unary()
            node = BinOp(op_token[1], node, right)
        return node

    def parse_unary(self):
        token = self.peek()
        if token and token[0] == 'OP' and token[1] in ('+', '-'):
            op_token = self.consume()
            operand = self.parse_unary()
            return UnaryOp(op_token[1], operand)

        if token and token[0] == 'NUMBER':
            self.consume()
            val_str = token[1]
            if '.' in val_str:
                return Number(float(val_str))
            else:
                return Number(int(val_str))

        if token and token[0] == 'REF':
            self.consume()
            return Ref(token[1])

        if token and token[0] == 'NAME':
            fname = token[1]
            next_token = self.peek(1)
            if next_token and next_token[0] == 'LPAREN':
                if fname not in FUNCTIONS:
                    raise FormulaError(f"Unknown function: {fname}")
                return self.parse_call()
            else:
                if fname in FUNCTIONS:
                    raise FormulaError(f"Function {fname} requires parentheses")
                else:
                    raise FormulaError(f"Unexpected identifier: {fname}")

        if token and token[0] == 'LPAREN':
            self.consume()
            node = self.parse_expr()
            if not self.peek() or self.peek()[0] != 'RPAREN':
                raise FormulaError("Unbalanced parentheses")
            self.consume()
            return node

        if token is None:
             raise FormulaError("Unexpected end of input")

        raise FormulaError(f"Unexpected token: {token}")

    def parse_call(self):
        fname_token = self.consume()
        fname = fname_token[1]
        self.expect('LPAREN')

        args = []

        # Check for empty arg list
        if self.peek() and self.peek()[0] == 'RPAREN':
            raise FormulaError(f"Function {fname} requires at least one argument")

        while True:
            arg = self.parse_arg()
            args.append(arg)

            if self.peek() and self.peek()[0] == 'COMMA':
                self.consume()
                continue
            else:
                break

        self.expect('RPAREN')
        return Call(fname, args)

    def parse_arg(self):
        # arg := ref : ref | expr
        t1 = self.peek(0)
        t2 = self.peek(1)

        # Check for Range syntax: REF COLON REF
        if t1 and t1[0] == 'REF' and t2 and t2[0] == 'COLON':
            ref1 = self.consume()[1]
            self.consume() # COLON
            ref2_token = self.peek()
            if not ref2_token or ref2_token[0] != 'REF':
                raise FormulaError("Expected reference after ':'")
            ref2 = self.consume()[1]
            return Range(ref1, ref2)

        return self.parse_expr()

    def parse(self):
        if not self.tokens:
            raise FormulaError("Empty formula")
        node = self.parse_expr()
        if self.pos < len(self.tokens):
            raise FormulaError(f"Unexpected token after expression: {self.peek()}")
        return node


def parse_formula(source: str):
    """Parses a formula string (excluding the leading '=') into an AST."""
    if not isinstance(source, str):
        raise FormulaError("Formula must be a string")

    if source.strip() == "":
         raise FormulaError("Empty formula")

    try:
        tokens = _tokenize_strict(source)
    except FormulaError:
        raise
    except Exception:
        raise FormulaError("Invalid characters in formula")

    parser = Parser(tokens)
    return parser.parse()


# Helper to check if a reference is inside the valid sheet bounds
# Valid: Single letter A-Z, followed by 1-999 (no leading zeros)
_CELL_RE = re.compile(r'^([A-Z])([1-9]\d*)$')

def _is_valid_cell(name: str) -> bool:
    if not name:
        return False
    m = _CELL_RE.match(name.upper())
    if not m:
        return False
    row_str = m.group(2)
    try:
        row = int(row_str)
        return 1 <= row <= 999
    except ValueError:
        return False


def _parse_cell_name(name: str) -> Optional[Tuple[int, int]]:
    """Parses 'A1' into (col, row) where col is 0-indexed int, row is 0-indexed int.
    Returns None if invalid."""
    if not name:
        return None
    m = _CELL_RE.match(name.upper())
    if not m:
        return None
    col_char = m.group(1)
    row_str = m.group(2)
    try:
        row = int(row_str)
        if not (1 <= row <= 999):
            return None
        col = ord(col_char) - ord('A')
        return (col, row - 1)
    except ValueError:
        return None


def _cell_sort_key(name: str) -> Tuple[int, int]:
    """Return a tuple (row, col) for row-major sorting.
    Assumes name is a valid cell name like 'B12'.
    """
    parsed = _parse_cell_name(name)
    if parsed is None:
        return (0, 0)
    col, row = parsed
    return (row, col)


def _expand_range_cells(start_name: str, end_name: str) -> Optional[List[str]]:
    """
    Expands a range defined by two corner names into a list of cell names in row-major order.
    Returns None if either corner is out of bounds.
    """
    start_parsed = _parse_cell_name(start_name)
    end_parsed = _parse_cell_name(end_name)

    if start_parsed is None or end_parsed is None:
        return None

    sc, sr = start_parsed
    ec, er = end_parsed

    min_c = min(sc, ec)
    max_c = max(sc, ec)
    min_r = min(sr, er)
    max_r = max(sr, er)

    cells = []
    for r in range(min_r, max_r + 1):
        for c in range(min_c, max_c + 1):
            if c > 25:
                continue
            col_char = chr(ord('A') + c)
            cell_name = f"{col_char}{r + 1}"
            cells.append(cell_name)

    return cells

def references(tree) -> Set[str]:
    """Extracts all cell references from an AST node, filtering for cells inside the sheet."""
    all_refs = set()
    _collect_refs(tree, all_refs)
    return {r for r in all_refs if _is_valid_cell(r)}

def _collect_refs(tree, ref_set):
    if isinstance(tree, Number):
        return
    elif isinstance(tree, Ref):
        ref_set.add(tree.name)
    elif isinstance(tree, Range):
        cells = _expand_range_cells(tree.start, tree.end)
        if cells is not None:
            ref_set.update(cells)
    elif isinstance(tree, UnaryOp):
        _collect_refs(tree.operand, ref_set)
    elif isinstance(tree, BinOp):
        _collect_refs(tree.left, ref_set)
        _collect_refs(tree.right, ref_set)
    elif isinstance(tree, Call):
        for arg in tree.args:
            _collect_refs(arg, ref_set)


def _is_number(value: Any) -> bool:
    return isinstance(value, (int, float)) and not isinstance(value, bool)

def _is_text(value: Any) -> bool:
    return isinstance(value, str) and not isinstance(value, ErrorValue)

def _is_empty(value: Any) -> bool:
    return value is None or value == ""


def _collect_numbers_from_arg(arg, lookup) -> Union[List[Union[int, float]], ErrorValue]:
    """
    Evaluates an argument of a function call and returns a list of numbers found.
    Returns an ErrorValue if an error is encountered during evaluation/lookup.
    """
    numbers = []

    if isinstance(arg, Range):
        cells = _expand_range_cells(arg.start, arg.end)
        if cells is None:
            return REF_ERROR

        for cell_name in cells:
            val = lookup(cell_name)
            if isinstance(val, ErrorValue):
                return val
            if _is_number(val):
                numbers.append(val)
            # Skip text and empty

    elif isinstance(arg, Ref):
        # Single reference treated as one-cell range
        val = lookup(arg.name)
        if isinstance(val, ErrorValue):
            return val
        if _is_number(val):
            numbers.append(val)
        # Skip text and empty

    else:
        # Expression: evaluate as normal
        try:
            val = evaluate(arg, lookup)
        except Exception:
            return VALUE_ERROR

        if isinstance(val, ErrorValue):
            return val
        if _is_number(val):
            numbers.append(val)
        else:
            # Text or other non-number result
            return VALUE_ERROR

    return numbers


def evaluate(tree, lookup: Callable[[str], Any]) -> Any:
    """Evaluates an AST node using the provided lookup function.

    Args:
        tree: The AST node to evaluate.
        lookup: A function that takes a cell name and returns its value.

    Returns:
        The result of the evaluation (int, float, or ErrorValue).
    """
    if isinstance(tree, Number):
        return tree.value

    if isinstance(tree, Ref):
        # Check if reference is valid (inside sheet)
        if not _is_valid_cell(tree.name):
            return REF_ERROR

        val = lookup(tree.name)
        # Propagate errors from lookup (e.g. cycles detected in sheet)
        if isinstance(val, ErrorValue):
            return val
        return val

    if isinstance(tree, UnaryOp):
        operand = evaluate(tree.operand, lookup)

        # Propagate errors
        if isinstance(operand, ErrorValue):
            return operand

        # Check for text operand
        if _is_text(operand):
            return VALUE_ERROR

        if not _is_number(operand):
            return VALUE_ERROR

        if tree.op == '-':
            return -operand
        return operand

    if isinstance(tree, BinOp):
        left = evaluate(tree.left, lookup)

        # Left-to-right error propagation: if left is error, return it immediately
        if isinstance(left, ErrorValue):
            return left

        right = evaluate(tree.right, lookup)

        # If right is error, return it (unless left was error, which we already returned)
        # Wait: "if any is an error value the result is the leftmost error, ahead of any #VALUE! for text."
        # This implies we evaluate left. If left is error, return left.
        # Then evaluate right. If right is error, return right? 
        # No, "leftmost error". If left is text, and right is error, which comes first?
        # The spec says: "operands ... evaluated left to right, and if any is an error value the result is the leftmost error"
        # If left is text, it's not an error value *yet* (until we process the op).
        # If left is #DIV/0!, we return #DIV/0! immediately.
        # If left is "text", we evaluate right.
        # If right is #DIV/0!, we return #DIV/0!.
        # If both are text, we return #VALUE!.

        if isinstance(right, ErrorValue):
            return right

        # Now check for #VALUE! conditions
        # If either is text, result is #VALUE!
        if _is_text(left) or _is_text(right):
            return VALUE_ERROR

        if not _is_number(left) or not _is_number(right):
            return VALUE_ERROR

        # Arithmetic operations
        if tree.op == '+':
            return left + right
        if tree.op == '-':
            return left - right
        if tree.op == '*':
            return left * right
        if tree.op == '/':
            if right == 0:
                return DIV_ZERO
            return left / right

    if isinstance(tree, Call):
        fname = tree.fname.upper()

        collected_numbers = []

        for arg in tree.args:
            # Collect numbers or error
            result = _collect_numbers_from_arg(arg, lookup)

            if isinstance(result, ErrorValue):
                # Return the first error encountered
                return result

            collected_numbers.extend(result)

        if fname == 'SUM':
            if not collected_numbers:
                return 0
            # Sum logic: if all ints, return int, else float
            if all(isinstance(n, int) for n in collected_numbers):
                return sum(collected_numbers)
            else:
                return float(sum(collected_numbers))

        elif fname == 'AVG':
            if not collected_numbers:
                return DIV_ZERO
            return float(sum(collected_numbers)) / len(collected_numbers)

        elif fname == 'MIN':
            if not collected_numbers:
                return 0
            return min(collected_numbers)

        elif fname == 'MAX':
            if not collected_numbers:
                return 0
            return max(collected_numbers)

        else:
            # Should not happen if parse checks functions
            return VALUE_ERROR

    raise FormulaError(f"Unknown node type: {type(tree)}")
