from collections import deque

class DependencyGraph:
    """
    Tracks dependencies between cells.
    """
    def __init__(self):
        # cell -> set of cells that depend on it (dependents)
        self.dependents = {}
        # cell -> set of cells it depends on (precedents)
        self.precedents = {}

    def get_dependencies(self, cell: str):
        """Return list of cells that depend on `cell`."""
        return list(self.dependents.get(cell, set()))

    def set_dependencies(self, cell: str, new_deps: set):
        """Update the dependencies of `cell`."""
        old_deps = self.precedents.get(cell, set())

        # Remove old reverse links
        for old_dep in old_deps:
            if cell in self.dependents.get(old_dep, set()):
                self.dependents[old_dep].remove(cell)
                if not self.dependents[old_dep]:
                    del self.dependents[old_dep]

        # Add new reverse links
        for new_dep in new_deps:
            if new_dep not in self.dependents:
                self.dependents[new_dep] = set()
            self.dependents[new_dep].add(cell)

        # Update precedents
        if new_deps:
            self.precedents[cell] = new_deps
        else:
            if cell in self.precedents:
                del self.precedents[cell]

    def get_dependents(self, cell: str):
        """Return list of cells that `cell` depends on."""
        return list(self.precedents.get(cell, set()))

    def has_cycle(self, start: str):
        """Check if there is a cycle involving `start`.

        Uses DFS to detect cycles.
        """
        visited = set()
        path = set()

        def dfs(cell):
            if cell in path:
                return True
            if cell in visited:
                return False

            visited.add(cell)
            path.add(cell)

            for dep in self.precedents.get(cell, set()):
                if dfs(dep):
                    return True

            path.remove(cell)
            return False

        return dfs(start)

    def topological_sort(self, initial_cells=None):
        """Not used directly by Sheet in this implementation, 
        but provided for completeness."""
        pass

    def clear(self):
        self.dependents.clear()
        self.precedents.clear()
