if TYPE_CHECKING:
    from .recurrence import Recurring


@dataclass(frozen=True)
class Event:
    title: str
    start: datetime
    end: datetime
    attendees: frozenset[str] = field(default_factory=frozenset)

    def __post_init__(self) -> None:
        # Normalize attendees to frozenset if passed a different iterable
        if not isinstance(self.attendees, frozenset):
            object.__setattr__(self, "attendees", frozenset(self.attendees))

        if self.end <= self.start:
            raise ValueError("end must be after start")


class Calendar:
    def __init__(self) -> None:
        self._events: list[Event] = []
        self._recurring: list[Recurring] = []

    def add(self, item: Event | Recurring) -> None:
        # Local import to avoid circular dependency
        from .recurrence import Recurring

        if isinstance(item, Recurring):
            self._recurring.append(item)
        elif isinstance(item, Event):
            self._events.append(item)
        else:
            raise TypeError("Only Event or Recurring instances can be added")

    def events_between(self, start: datetime, end: datetime) -> list[Event]:
        result: list[Event] = []

        # One-off events
        for event in self._events:
            # Overlap rule: [start, end) vs [event.start, event.end)
            # Overlap if event.start < end and start < event.end
            if event.start < end and start < event.end:
                result.append(event)

        # Recurring series
        for rec in self._recurring:
            occurrences = rec.occurrences(start, end)
            result.extend(occurrences)

        # Sort by (start, end, title)
        result.sort(key=lambda e: (e.start, e.end, e.title))
        return result

    def events_for(self, person: str, start: datetime, end: datetime) -> list[Event]:
        return [
            event
            for event in self.events_between(start, end)
            if person in event.attendees
        ]
