from typing import List
from .scanner import Token, JSONError, tokenize

def loads(text: str) -> object:
    """Parse a JSON document from a string."""
    tokens = tokenize(text)
    idx = 0

    def peek() -> Token:
        return tokens[idx]

    def consume() -> Token:
        nonlocal idx
        t = tokens[idx]
        idx += 1
        return t

    def parse_value():
        tok = peek()
        if tok.kind == '{':
            return parse_object()
        elif tok.kind == '[':
            return parse_array()
        elif tok.kind in ('STRING', 'NUMBER', 'TRUE', 'FALSE', 'NULL'):
            consume()
            return tok.value
        else:
            raise JSONError("Unexpected token", tok.line, tok.column)

    def parse_object() -> dict:
        consume()  # Consume '{'
        obj = {}

        # Empty object
        if peek().kind == '}':
            consume()
            return obj

        while True:
            key_tok = peek()
            if key_tok.kind != 'STRING':
                raise JSONError(
                    "Object keys must be strings",
                    key_tok.line,
                    key_tok.column
                )
            key = consume().value

            colon = peek()
            if colon.kind != ':':
                raise JSONError(
                    "Expected ':'",
                    colon.line,
                    colon.column
                )
            consume()

            val = parse_value()
            obj[key] = val

            sep = peek()
            if sep.kind == '}':
                consume()
                break
            elif sep.kind == ',':
                consume()
                # Loop continues to parse next key-value pair
                # If trailing comma, the next iteration will fail because
                # it expects a STRING key but sees '}' or EOF.
            else:
                raise JSONError(
                    "Expected ',' or '}'",
                    sep.line,
                    sep.column
                )

        return obj

    def parse_array() -> list:
        consume()  # Consume '['
        arr = []

        # Empty array
        if peek().kind == ']':
            consume()
            return arr

        while True:
            val = parse_value()
            arr.append(val)

            sep = peek()
            if sep.kind == ']':
                consume()
                break
            elif sep.kind == ',':
                consume()
                # Loop continues to parse next value
                # If trailing comma, parse_value will see ']' and raise
                # "Unexpected token" at ']'.
            else:
                raise JSONError(
                    "Expected ',' or ']'",
                    sep.line,
                    sep.column
                )

        return arr

    result = parse_value()

    # Check for trailing garbage
    eof = peek()
    if eof.kind != 'EOF':
        raise JSONError(
            "Unexpected trailing content",
            eof.line,
            eof.column
        )

    return result
