        elif c == '\\':
            buf.append('\\\\')
        elif c == '\b':
            buf.append('\\b')
        elif c == '\f':
            buf.append('\\f')
        elif c == '\n':
            buf.append('\\n')
        elif c == '\r':
            buf.append('\\r')
        elif c == '\t':
            buf.append('\\t')
        elif ord(c) < 0x20:
            # Control character
            buf.append(f"\\u{ord(c):04x}")
        elif ensure_ascii and ord(c) > 0x7f:
            # Non-ASCII, escape
            if ord(c) > 0xFFFF:
                # Need surrogate pair
                # c is > 0xFFFF, so it's outside BMP
                # Encode as UTF-16 surrogates
                # Python handles this automatically if we iterate? 
                # We need to manually generate the pair for characters > 0xFFFF
                # Code point
                cp = ord(c)
                # Subtract 0x10000, 20 bits remain
                cp -= 0x10000
                high = 0xD800 + (cp >> 10)
                low = 0xDC00 + (cp & 0x3FF)
                buf.append(f"\\u{high:04x}")
                buf.append(f"\\u{low:04x}")
            else:
                buf.append(f"\\u{ord(c):04x}")
        else:
            buf.append(c)

    buf.append('"')
    return "".join(buf)
