from typing import NamedTuple, List, Any

class JSONError(ValueError):
    def __init__(self, msg: str, line: int, column: int):
        self.msg = msg
        self.line = line
        self.column = column
        super().__init__(f"{msg} at line {line} column {column}")

class Token(NamedTuple):
    kind: str
    value: Any
    line: int
    column: int

def tokenize(text: str, *, allow_nan: bool = False) -> List[Token]:
    """
    Tokenize a JSON string.

    Args:
        text: The input string to tokenize.
        allow_nan: If True, allows 'NaN', 'Infinity', and '-Infinity' as NUMBER tokens.
                   Defaults to False.
    """
    tokens = []
    i = 0
    line = 1
    col = 1
    n = len(text)

    def advance():
        nonlocal i, line, col
        ch = text[i]
        i += 1
        if ch == '\n':
            line += 1
            col = 1
        else:
            col += 1
        return ch

    while i < n:
        ch = text[i]

        # Whitespace
        if ch in ' \t\r\n':
            advance()
            continue

        # Structural characters
        if ch in '{}[]:,':
            tokens.append(Token(ch, None, line, col))
            advance()
            continue

        # Literals (true, false, null, NaN, Infinity)
        if ch.isalpha():
            start_line, start_col = line, col
            start_i = i
            while i < n and text[i].isalpha():
                advance()
            word = text[start_i:i]
            if word == 'true':
                tokens.append(Token('TRUE', True, start_line, start_col))
            elif word == 'false':
                tokens.append(Token('FALSE', False, start_line, start_col))
            elif word == 'null':
                tokens.append(Token('NULL', None, start_line, start_col))
            elif allow_nan and word == 'NaN':
                tokens.append(Token('NUMBER', float('nan'), start_line, start_col))
            elif allow_nan and word == 'Infinity':
                tokens.append(Token('NUMBER', float('inf'), start_line, start_col))
            else:
                raise JSONError('invalid literal', start_line, start_col)
            continue

        # Numbers
        if ch == '-' or ch.isdigit():
            start_line, start_col = line, col
            start_i = i

            # Check for -Infinity
            if ch == '-' and allow_nan:
                # Peek ahead to see if it's -Infinity
                # Infinity has length 8, so -Infinity has length 9
                if i + 9 <= n and text[i:i+9] == '-Infinity':
                    # Consume all characters
                    for _ in range(9):
                        advance()
                    tokens.append(Token('NUMBER', float('-inf'), start_line, start_col))
                    continue

            while i < n and text[i] in '0123456789+-.eE':
                advance()
            num_str = text[start_i:i]

            # Validate JSON number
            try:
                is_valid = False
                # Must start with - or digit
                if num_str[0] == '-':
                    if len(num_str) == 1:
                        raise ValueError
                    body = num_str[1:]
                    if not body[0].isdigit():
                        raise ValueError
                else:
                    body = num_str
                    if not body[0].isdigit():
                        raise ValueError

                # Integer part
                if body[0] == '0':
                    if len(body) > 1 and body[1].isdigit():
                        raise ValueError # Leading zero
                    j = 1
                else:
                    j = 0
                    while j < len(body) and body[j].isdigit():
                        j += 1
                        if j == len(body): break

                valid = True
                pos = 0
                s = num_str

                if pos < len(s) and s[pos] == '-':
                    pos += 1
                    if pos >= len(s): valid = False

                if pos < len(s):
                    if s[pos] == '0':
                        pos += 1
                        if pos < len(s) and s[pos].isdigit():
                            valid = False
                    elif s[pos].isdigit():
                        pos += 1
                        while pos < len(s) and s[pos].isdigit():
                            pos += 1
                    else:
                        valid = False
                else:
                    valid = False

                if not valid:
                    raise ValueError

                is_float = False

                # Fraction
                if pos < len(s) and s[pos] == '.':
                    pos += 1
                    if pos >= len(s) or not s[pos].isdigit():
                        valid = False
                    else:
                        is_float = True
                        while pos < len(s) and s[pos].isdigit():
                            pos += 1

                if not valid:
                    raise ValueError

                # Exponent
                if pos < len(s) and s[pos] in 'eE':
                    pos += 1
                    if pos < len(s) and s[pos] in '+-':
                        pos += 1
                    if pos >= len(s) or not s[pos].isdigit():
                        valid = False
                    else:
                        is_float = True
                        while pos < len(s) and s[pos].isdigit():
                            pos += 1

                if not valid or pos != len(s):
                    raise ValueError

                if is_float:
                    value = float(num_str)
                    tokens.append(Token('NUMBER', value, start_line, start_col))
                else:
                    # It's an int
                    # -0 is int 0
                    if num_str == '-0':
                        value = 0
                    else:
                        value = int(num_str)
                    tokens.append(Token('NUMBER', value, start_line, start_col))

            except Exception:
                raise JSONError('invalid number', start_line, start_col)
            continue

        # Strings
        if ch == '"':
            start_line, start_col = line, col
            advance() # consume opening quote
            chars = []
            while True:
                if i >= n:
                    raise JSONError('unterminated string', start_line, start_col)
                c = text[i]
                if c == '"':
                    advance() # consume closing quote
                    break
                if c == '\\':
                    esc_line, esc_col = line, col
                    advance() # consume backslash
                    if i >= n:
                        raise JSONError('unterminated string', start_line, start_col)
                    e = text[i]
                    advance() # consume escape char
                    if e == '"':
                        chars.append('"')
                    elif e == '\\':
                        chars.append('\\')
                    elif e == '/':
                        chars.append('/')
                    elif e == 'b':
                        chars.append('\b')
                    elif e == 'f':
                        chars.append('\f')
                    elif e == 'n':
                        chars.append('\n')
                    elif e == 'r':
                        chars.append('\r')
                    elif e == 't':
                        chars.append('\t')
                    elif e == 'u':
                        # Read 4 hex digits
                        if i + 4 > n:
                            raise JSONError('bad escape', esc_line, esc_col)
                        hex_digits = text[i:i+4]
                        if not all(h in '0123456789abcdefABCDEF' for h in hex_digits):
                            raise JSONError('bad escape', esc_line, esc_col)

                        # Advance 4 times manually to keep line/col correct if newlines were inside? 
                        # Hex digits are ASCII, no newlines.
                        for _ in range(4):
                            advance()

                        cp = int(hex_digits, 16)

                        # Surrogate handling
                        if 0xD800 <= cp <= 0xDBFF:
                            # High surrogate, expect low surrogate
                            if i + 6 > n or text[i] != '\\' or text[i+1] != 'u':
                                raise JSONError('bad surrogate', esc_line, esc_col)

                            # Check if next is valid low surrogate
                            low_hex = text[i+2:i+6]
                            if len(low_hex) != 4 or not all(h in '0123456789abcdefABCDEF' for h in low_hex):
                                raise JSONError('bad surrogate', esc_line, esc_col)

                            low_cp = int(low_hex, 16)
                            if not (0xDC00 <= low_cp <= 0xDFFF):
                                raise JSONError('bad surrogate', esc_line, esc_col)

                            # Combine surrogates
                            # code point = 0x10000 + (high - 0xD800) * 0x400 + (low - 0xDC00)
                            combined = 0x10000 + (cp - 0xD800) * 0x400 + (low_cp - 0xDC00)
                            chars.append(chr(combined))

                            # Advance past \uXXXX
                            # We are currently at i (pointing to the \ of the second \u)
                            # We need to consume 6 chars: \ u h h h h
                            for _ in range(6):
                                advance()

                        elif 0xDC00 <= cp <= 0xDFFF:
                            # Lone low surrogate
                            raise JSONError('bad surrogate', esc_line, esc_col)
                        else:
                            chars.append(chr(cp))
                    else:
                        raise JSONError('bad escape', esc_line, esc_col)
                elif ord(c) < 0x20:
                    # Raw control character
                    raise JSONError('raw control character', line, col)
                else:
                    chars.append(c)
                    advance()

            tokens.append(Token('STRING', ''.join(chars), start_line, start_col))
            continue

        # Unexpected character
        raise JSONError('unexpected character', line, col)

    # EOF Token
    tokens.append(Token('EOF', None, line, col))
    return tokens
