                    if pos >= len(s) or not s[pos].isdigit():
                        valid = False
                    else:
                        is_float = True
                        while pos < len(s) and s[pos].isdigit():
                            pos += 1

                if not valid or pos != len(s):
                    raise ValueError

                if is_float:
                    value = float(num_str)
                    tokens.append(Token('NUMBER', value, start_line, start_col))
                else:
                    # It's an int
                    # -0 is int 0
                    if num_str == '-0':
                        value = 0
                    else:
                        value = int(num_str)
                    tokens.append(Token('NUMBER', value, start_line, start_col))

            except Exception:
                raise JSONError('invalid number', start_line, start_col)
            continue

        # Strings
        if ch == '"':
            start_line, start_col = line, col
            advance() # consume opening quote
            chars = []
            while True:
                if i >= n:
                    raise JSONError('unterminated string', start_line, start_col)
                c = text[i]
                if c == '"':
                    advance() # consume closing quote
                    break
                if c == '\\':
                    esc_line, esc_col = line, col
                    advance() # consume backslash
                    if i >= n:
                        raise JSONError('unterminated string', start_line, start_col)
                    e = text[i]
                    advance() # consume escape char
                    if e == '"':
                        chars.append('"')
                    elif e == '\\':
                        chars.append('\\')
                    elif e == '/':
                        chars.append('/')
                    elif e == 'b':
                        chars.append('\b')
                    elif e == 'f':
                        chars.append('\f')
                    elif e == 'n':
                        chars.append('\n')
                    elif e == 'r':
                        chars.append('\r')
                    elif e == 't':
                        chars.append('\t')
                    elif e == 'u':
                        # Read 4 hex digits
                        if i + 4 > n:
                            raise JSONError('bad escape', esc_line, esc_col)
                        hex_digits = text[i:i+4]
                        if not all(h in '0123456789abcdefABCDEF' for h in hex_digits):
                            raise JSONError('bad escape', esc_line, esc_col)

                        # Advance 4 times manually to keep line/col correct if newlines were inside? 
                        # Hex digits are ASCII, no newlines.
                        for _ in range(4):
                            advance()

                        cp = int(hex_digits, 16)

                        # Surrogate handling
                        if 0xD800 <= cp <= 0xDBFF:
                            # High surrogate, expect low surrogate
                            if i + 6 > n or text[i] != '\\' or text[i+1] != 'u':
                                raise JSONError('bad surrogate', esc_line, esc_col)

                            # Check if next is valid low surrogate
                            low_hex = text[i+2:i+6]
                            if len(low_hex) != 4 or not all(h in '0123456789abcdefABCDEF' for h in low_hex):
                                raise JSONError('bad surrogate', esc_line, esc_col)

                            low_cp = int(low_hex, 16)
                            if not (0xDC00 <= low_cp <= 0xDFFF):
                                raise JSONError('bad surrogate', esc_line, esc_col)

                            # Combine surrogates
                            # code point = 0x10000 + (high - 0xD800) * 0x400 + (low - 0xDC00)
                            combined = 0x10000 + (cp - 0xD800) * 0x400 + (low_cp - 0xDC00)
                            chars.append(chr(combined))

                            # Advance past \uXXXX
                            # We are currently at i (pointing to the \ of the second \u)
                            # We need to consume 6 chars: \ u h h h h
                            for _ in range(6):
                                advance()

                        elif 0xDC00 <= cp <= 0xDFFF:
                            # Lone low surrogate
                            raise JSONError('bad surrogate', esc_line, esc_col)
                        else:
                            chars.append(chr(cp))
                    else:
                        raise JSONError('bad escape', esc_line, esc_col)
                elif ord(c) < 0x20:
                    # Raw control character
                    raise JSONError('raw control character', line, col)
                else:
                    chars.append(c)
                    advance()

            tokens.append(Token('STRING', ''.join(chars), start_line, start_col))
            continue

        # Unexpected character
        raise JSONError('unexpected character', line, col)

    # EOF Token
    tokens.append(Token('EOF', None, line, col))
    return tokens
