"""
JSON serializer for Python objects.
"""

import math


def dumps(obj, *, indent=None, sort_keys=False, ensure_ascii=False, allow_nan=False):
    """
    Serialize an object to a JSON string.

    Args:
        obj: The Python object to serialize.
        indent: If not None, the number of spaces to use for indentation.
                Must be a non-negative integer.
        sort_keys: If True, object keys are sorted alphabetically.
        ensure_ascii: If True, non-ASCII characters are escaped as \uXXXX.
        allow_nan: If True, nan, inf, and -inf are serialized as literals.
                   If False, they raise ValueError.

    Returns:
        A JSON string.

    Raises:
        ValueError: If indent is negative, or if cycles are detected,
                    or if nan/inf floats are encountered and allow_nan is False.
        TypeError: If a dict key is not a string, or if an unsupported
                   type is encountered.
    """
    if indent is not None:
        if not isinstance(indent, int) or indent < 0:
            raise ValueError("indent must be a non-negative integer")

    # Track containers to detect cycles
    seen = set()

    return _dump_value(obj, indent, sort_keys, ensure_ascii, allow_nan, seen, 0)


def _dump_value(obj, indent, sort_keys, ensure_ascii, allow_nan, seen, level):
    """
    Recursively serialize a value.
    """
    if obj is None:
        return "null"
    if obj is True:
        return "true"
    if obj is False:
        return "false"

    if isinstance(obj, str):
        return _encode_string(obj, ensure_ascii)

    # Check for int before bool because bool is a subclass of int
    if isinstance(obj, int) and not isinstance(obj, bool):
        return str(obj)

    if isinstance(obj, float):
        if math.isnan(obj):
            if allow_nan:
                return "NaN"
            raise ValueError("nan not allowed in JSON")
        if math.isinf(obj):
            if allow_nan:
                return "Infinity" if obj > 0 else "-Infinity"
            raise ValueError("inf not allowed in JSON")
        return repr(obj)

    if isinstance(obj, (list, tuple)):
        return _dump_array(obj, indent, sort_keys, ensure_ascii, allow_nan, seen, level)

    if isinstance(obj, dict):
        return _dump_object(obj, indent, sort_keys, ensure_ascii, allow_nan, seen, level)

    raise TypeError(f"Object of type {type(obj).__name__} is not JSON serializable")


def _dump_array(arr, indent, sort_keys, ensure_ascii, allow_nan, seen, level):
    obj_id = id(arr)
    if obj_id in seen:
        raise ValueError("Circular reference detected")

    seen.add(obj_id)
    try:
        if not arr:
            return "[]"

        if indent is None:
            parts = [_dump_value(item, indent, sort_keys, ensure_ascii, allow_nan, seen, level) for item in arr]
            return "[" + ",".join(parts) + "]"
        else:
            parts = []
            new_level = level + 1
            for item in arr:
                parts.append(_dump_value(item, indent, sort_keys, ensure_ascii, allow_nan, seen, new_level))

            inner_indent = " " * (new_level * indent)
            items_str = ",\n".join(inner_indent + part for part in parts)
            outer_indent = " " * (level * indent)
            return "[\n" + items_str + "\n" + outer_indent + "]"
    finally:
        seen.discard(obj_id)


def _dump_object(obj, indent, sort_keys, ensure_ascii, allow_nan, seen, level):
    obj_id = id(obj)
    if obj_id in seen:
        raise ValueError("Circular reference detected")

    seen.add(obj_id)
    try:
        if not obj:
            return "{}"

        keys = obj.keys()
        if sort_keys:
            try:
                keys = sorted(keys)
            except TypeError:
                raise TypeError("sort_keys=True requires comparable keys")

        items = []
        for k in keys:
            if not isinstance(k, str):
                raise TypeError("dict keys must be strings")
            key_str = _encode_string(k, ensure_ascii)
            val_str = _dump_value(obj[k], indent, sort_keys, ensure_ascii, allow_nan, seen, level + 1)

            if indent is None:
                items.append(f"{key_str}:{val_str}")
            else:
                items.append(f"{key_str}: {val_str}")

        if indent is None:
            return "{" + ",".join(items) + "}"
        else:
            inner_indent = " " * ((level + 1) * indent)
            outer_indent = " " * (level * indent)
            items_str = ",\n".join(inner_indent + item for item in items)
            return "{\n" + items_str + "\n" + outer_indent + "}"

    finally:
        seen.discard(obj_id)




def _encode_string(s, ensure_ascii):
    """
    Encode a string to a JSON-escaped string literal.
    """
    buf = ['"']
    for c in s:
        if c == '"':
            buf.append('\\"')
        elif c == '\\':
            buf.append('\\\\')
        elif c == '\b':
            buf.append('\\b')
        elif c == '\f':
            buf.append('\\f')
        elif c == '\n':
            buf.append('\\n')
        elif c == '\r':
            buf.append('\\r')
        elif c == '\t':
            buf.append('\\t')
        elif ord(c) < 0x20:
            # Control character
            buf.append(f"\\u{ord(c):04x}")
        elif ensure_ascii and ord(c) > 0x7f:
            # Non-ASCII, escape
            if ord(c) > 0xFFFF:
                # Need surrogate pair
                cp = ord(c)
                cp -= 0x10000
                high = 0xD800 + (cp >> 10)
                low = 0xDC00 + (cp & 0x3FF)
                buf.append(f"\\u{high:04x}")
                buf.append(f"\\u{low:04x}")
            else:
                buf.append(f"\\u{ord(c):04x}")
        else:
            buf.append(c)

    buf.append('"')
    return "".join(buf)
