            advance() # consume opening quote
            chars = []
            while True:
                if i >= n:
                    raise JSONError('unterminated string', start_line, start_col)
                c = text[i]
                if c == '"':
                    advance() # consume closing quote
                    break
                if c == '\\':
                    esc_line, esc_col = line, col
                    advance() # consume backslash
                    if i >= n:
                        raise JSONError('unterminated string', start_line, start_col)
                    e = text[i]
                    advance() # consume escape char
                    if e == '"':
