from typing import NamedTuple, List, Any

class JSONError(ValueError):
    def __init__(self, msg: str, line: int, column: int):
        self.msg = msg
        self.line = line
        self.column = column
        super().__init__(f"{msg} at line {line} column {column}")

class Token(NamedTuple):
    kind: str
    value: Any
    line: int
    column: int

def tokenize(text: str, *, allow_nan: bool = False) -> List[Token]:
    """
    Tokenize a JSON string.

    Args:
        text: The input string to tokenize.
        allow_nan: If True, allows 'NaN', 'Infinity', and '-Infinity' as NUMBER tokens.
                   Defaults to False.
    """
    tokens = []
    i = 0
    line = 1
    col = 1
    n = len(text)

    def advance():
        nonlocal i, line, col
        ch = text[i]
        i += 1
        if ch == '\n':
            line += 1
            col = 1
        else:
            col += 1
        return ch

    while i < n:
        ch = text[i]

        # Whitespace
        if ch in ' \t\r\n':
            advance()
            continue

        # Structural characters
        if ch in '{}[]:,':
            tokens.append(Token(ch, None, line, col))
            advance()
            continue

        # Literals (true, false, null, NaN, Infinity)
        if ch.isalpha():
            start_line, start_col = line, col
            start_i = i
            while i < n and text[i].isalpha():
                advance()
            word = text[start_i:i]
            if word == 'true':
                tokens.append(Token('TRUE', True, start_line, start_col))
            elif word == 'false':
                tokens.append(Token('FALSE', False, start_line, start_col))
            elif word == 'null':
                tokens.append(Token('NULL', None, start_line, start_col))
            elif allow_nan and word == 'NaN':
                tokens.append(Token('NUMBER', float('nan'), start_line, start_col))
            elif allow_nan and word == 'Infinity':
                tokens.append(Token('NUMBER', float('inf'), start_line, start_col))
            else:
                raise JSONError('invalid literal', start_line, start_col)
            continue

        # Numbers
        if ch == '-' or ch.isdigit():
            start_line, start_col = line, col
            start_i = i

            # Check for -Infinity
            if ch == '-' and allow_nan:
                # Peek ahead to see if it's -Infinity
                # Infinity has length 8, so -Infinity has length 9
                if i + 9 <= n and text[i:i+9] == '-Infinity':
                    # Consume all characters
                    for _ in range(9):
                        advance()
                    tokens.append(Token('NUMBER', float('-inf'), start_line, start_col))
                    continue

            while i < n and text[i] in '0123456789+-.eE':
                advance()
            num_str = text[start_i:i]

            # Validate JSON number
            try:
                is_valid = False
                # Must start with - or digit
                if num_str[0] == '-':
                    if len(num_str) == 1:
                        raise ValueError
                    body = num_str[1:]
                    if not body[0].isdigit():
                        raise ValueError
                else:
                    body = num_str
                    if not body[0].isdigit():
                        raise ValueError

                # Integer part
                if body[0] == '0':
                    if len(body) > 1 and body[1].isdigit():
                        raise ValueError # Leading zero
                    j = 1
                else:
                    j = 0
                    while j < len(body) and body[j].isdigit():
                        j += 1
                        if j == len(body): break

                valid = True
                pos = 0
                s = num_str

                if pos < len(s) and s[pos] == '-':
                    pos += 1
                    if pos >= len(s): valid = False

                if pos < len(s):
                    if s[pos] == '0':
                        pos += 1
                        if pos < len(s) and s[pos].isdigit():
                            valid = False
                    elif s[pos].isdigit():
                        pos += 1
                        while pos < len(s) and s[pos].isdigit():
                            pos += 1
                    else:
                        valid = False
                else:
                    valid = False

                if not valid:
                    raise ValueError

                is_float = False

                # Fraction
                if pos < len(s) and s[pos] == '.':
                    pos += 1
                    if pos >= len(s) or not s[pos].isdigit():
                        valid = False
                    else:
                        is_float = True
                        while pos < len(s) and s[pos].isdigit():
                            pos += 1

                if not valid:
                    raise ValueError

                # Exponent
                if pos < len(s) and s[pos] in 'eE':
                    pos += 1
                    if pos < len(s) and s[pos] in '+-':
                        pos += 1
                    if pos >= len(s) or not s[pos].isdigit():
                        valid = False
                    else:
                        is_float = True
                        while pos < len(s) and s[pos].isdigit():
                            pos += 1

                if not valid or pos != len(s):
                    raise ValueError

                if is_float:
                    value = float(num_str)
                    tokens.append(Token('NUMBER', value, start_line, start_col))
                else:
                    # It's an int
                    # -0 is int 0
                    if num_str == '-0':
                        value = 0
                    else:
                        value = int(num_str)
                    tokens.append(Token('NUMBER', value, start_line, start_col))

            except Exception:
                raise JSONError('invalid number', start_line, start_col)
            continue

