                    advance() # consume backslash
                    if i >= n:
                        raise JSONError('unterminated string', start_line, start_col)
                    e = text[i]
                    advance() # consume escape char
                    if e == '"':
                        chars.append('"')
                    elif e == '\\':
                        chars.append('\\')
                    elif e == '/':
                        chars.append('/')
                    elif e == 'b':
                        chars.append('\b')
                    elif e == 'f':
                        chars.append('\f')
                    elif e == 'n':
                        chars.append('\n')
                    elif e == 'r':
                        chars.append('\r')
                    elif e == 't':
                        chars.append('\t')
                    elif e == 'u':
                        # Read 4 hex digits
                        if i + 4 > n:
                            raise JSONError('bad escape', esc_line, esc_col)
                        hex_digits = text[i:i+4]
                        if not all(h in '0123456789abcdefABCDEF' for h in hex_digits):
                            raise JSONError('bad escape', esc_line, esc_col)

                        # Advance 4 times manually to keep line/col correct if newlines were inside? 
                        # Hex digits are ASCII, no newlines.
                        for _ in range(4):
                            advance()

                        cp = int(hex_digits, 16)

                        # Surrogate handling
                        if 0xD800 <= cp <= 0xDBFF:
                            # High surrogate, expect low surrogate
                            if i + 6 > n or text[i] != '\\' or text[i+1] != 'u':
                                raise JSONError('bad surrogate', esc_line, esc_col)

                            # Check if next is valid low surrogate
                            low_hex = text[i+2:i+6]
                            if len(low_hex) != 4 or not all(h in '0123456789abcdefABCDEF' for h in low_hex):
                                raise JSONError('bad surrogate', esc_line, esc_col)

                            low_cp = int(low_hex, 16)
                            if not (0xDC00 <= low_cp <= 0xDFFF):
                                raise JSONError('bad surrogate', esc_line, esc_col)

                            # Combine surrogates
                            # code point = 0x10000 + (high - 0xD800) * 0x400 + (low - 0xDC00)
                            combined = 0x10000 + (cp - 0xD800) * 0x400 + (low_cp - 0xDC00)
                            chars.append(chr(combined))

