        elif c == '\\':
            buf.append('\\\\')
        elif c == '\b':
            buf.append('\\b')
        elif c == '\f':
            buf.append('\\f')
        elif c == '\n':
            buf.append('\\n')
        elif c == '\r':
            buf.append('\\r')
        elif c == '\t':
