                high = 0xD800 + (cp >> 10)
                low = 0xDC00 + (cp & 0x3FF)
                buf.append(f"\\u{high:04x}")
                buf.append(f"\\u{low:04x}")
            else:
                buf.append(f"\\u{ord(c):04x}")
        else:
            buf.append(c)

