from typing import List
from .scanner import Token, JSONError, tokenize

def loads(text: str, *, duplicate_keys: str = 'last', max_depth: int = None, allow_nan: bool = False) -> object:
    """Parse a JSON document from a string."""
    # Validation (performed before reading the text)
    if duplicate_keys not in ('last', 'first', 'error'):
        raise ValueError(f"duplicate_keys must be 'last', 'first', or 'error', got {duplicate_keys!r}")
    if max_depth is not None and (not isinstance(max_depth, int) or max_depth < 1):
        raise ValueError("max_depth must be None or an integer >= 1")

    tokens = tokenize(text, allow_nan=allow_nan)
    idx = 0
    current_depth = 0

    def peek() -> Token:
        return tokens[idx]

    def consume() -> Token:
        nonlocal idx
        t = tokens[idx]
        idx += 1
        return t

    def check_depth():
        # Called when an opening '{' or '[' is seen (token not yet consumed),
        # so the error position points at the opening bracket.
        nonlocal current_depth
        current_depth += 1
        if max_depth is not None and current_depth > max_depth:
            tok = peek()
            raise JSONError("max depth exceeded", tok.line, tok.column)

    def dec_depth():
        nonlocal current_depth
        current_depth -= 1

    def parse_value():
        tok = peek()
        if tok.kind == '{':
            check_depth()
            try:
                return parse_object()
            finally:
                dec_depth()
        elif tok.kind == '[':
            check_depth()
            try:
                return parse_array()
            finally:
                dec_depth()
        elif tok.kind in ('STRING', 'NUMBER', 'TRUE', 'FALSE', 'NULL'):
            consume()
            return tok.value
        else:
            raise JSONError("Unexpected token", tok.line, tok.column)

    def parse_object() -> dict:
        consume()  # Consume '{' (already depth-checked in parse_value)
        obj = {}
        seen_keys = set()

        # Empty object
        if peek().kind == '}':
            consume()
            return obj

        while True:
            key_tok = peek()
            if key_tok.kind != 'STRING':
                raise JSONError(
                    "Object keys must be strings",
                    key_tok.line,
                    key_tok.column
                )
            key = consume().value

            is_duplicate = key in seen_keys

            # 'error' policy: checked as soon as the key is read, before its value.
            if is_duplicate and duplicate_keys == 'error':
                raise JSONError(
                    f"Duplicate key: {key!r}",
                    key_tok.line,
                    key_tok.column
                )

            colon = peek()
            if colon.kind != ':':
                raise JSONError(
                    "Expected ':'",
                    colon.line,
                    colon.column
                )
            consume()

            if is_duplicate and duplicate_keys == 'first':
                # Keep the first value; parse and discard the later value.
                parse_value()
            else:
                val = parse_value()
                obj[key] = val
                seen_keys.add(key)

            sep = peek()
            if sep.kind == '}':
                consume()
                break
            elif sep.kind == ',':
                consume()
            else:
                raise JSONError(
                    "Expected ',' or '}'",
                    sep.line,
                    sep.column
                )

        return obj

    def parse_array() -> list:
        consume()  # Consume '[' (already depth-checked in parse_value)
        arr = []

        # Empty array
        if peek().kind == ']':
            consume()
            return arr

        while True:
            val = parse_value()
            arr.append(val)

            sep = peek()
            if sep.kind == ']':
                consume()
                break
            elif sep.kind == ',':
                consume()
            else:
                raise JSONError(
                    "Expected ',' or ']'",
                    sep.line,
                    sep.column
                )

        return arr

    result = parse_value()

    # Check for trailing garbage
    eof = peek()
    if eof.kind != 'EOF':
        raise JSONError(
            "Unexpected trailing content",
            eof.line,
            eof.column
        )

    return result
