import csv
import datetime
import re
from dataclasses import dataclass
from decimal import Decimal
from typing import List, NamedTuple, Tuple


class Sale(NamedTuple):
    # Using dataclass for Sale as per requirements, but NamedTuple is also a tuple.
    # The prompt says "Sale is a frozen dataclass".
    pass

@dataclass(frozen=True)
class Sale:
    date: datetime.date
    region: str
    product: str
    units: int
    unit_price: Decimal

    @property
    def revenue(self) -> Decimal:
        return Decimal(self.units) * self.unit_price


class RowError(NamedTuple):
    line: int
    message: str


class IngestError(ValueError):
    pass


# Required columns in order for checking missing header
REQUIRED_COLUMNS = ['date', 'region', 'product', 'units', 'unit_price']


def _validate_date(value: str) -> datetime.date:
    try:
        # Strictly YYYY-MM-DD format
        if not re.fullmatch(r'\d{4}-\d{2}-\d{2}', value):
            raise ValueError("format error")
        return datetime.datetime.strptime(value, "%Y-%m-%d").date()
    except ValueError:
        raise ValueError("must be a valid date in YYYY-MM-DD format")


def _validate_units(value: str) -> int:
    if not re.fullmatch(r'\d+', value):
        raise ValueError("must be a whole number")
    val = int(value)
    if val < 1:
        raise ValueError("must be a whole number of at least 1")
    return val


def _validate_price(value: str) -> Decimal:
    # Digits, optionally followed by . and one or two digits
    if not re.fullmatch(r'\d+(\.\d{1,2})?', value):
        raise ValueError("invalid decimal format")
    return Decimal(value)


def parse_sales(text: str) -> Tuple[List[Sale], List[RowError]]:
    """
    Parse CSV text into sales and errors.
    Returns (sales, errors) where both lists are in input order.
    """
    sales: List[Sale] = []
    errors: List[RowError] = []

    # Use csv.reader on the text. We need to handle line numbers manually
    # because csv.reader doesn't give us absolute line numbers easily 
    # if we split by lines first, or we can use the reader directly.
    # Note: csv.reader handles newlines. We need to track line numbers.

    # Strategy: Split by lines to preserve line numbers accurately for error reporting,
    # but use csv.reader on individual lines? No, CSV fields can contain newlines if quoted.
    # However, the problem description implies simple rows.
    # "Lines that are completely empty are skipped silently."

    # Let's use csv.reader on the whole text, but we need line numbers.
    # The `csv` module's reader object has a `line_num` attribute which is 
    # useful, but it reflects the physical line number in the source. 
    # It increments by 1 for each line read, including empty lines.

    reader = csv.reader(text.splitlines())

    try:
        header = next(reader)
        line_num = 1
    except StopIteration:
        raise IngestError("no header row")

    # Normalize header
    normalized_header = [h.strip().lower() for h in header]

    # Check for missing required columns
    # Must contain date, region, product, units, unit_price in any order
    for col in REQUIRED_COLUMNS:
        if col not in normalized_header:
            raise IngestError(f"missing required column: {col}")

    # Map column names to indices
    # We need to know which index corresponds to which required field
    col_indices = {}
    for i, col in enumerate(normalized_header):
        if col in REQUIRED_COLUMNS:
            col_indices[col] = i

    # Iterate through the rest of the rows
    # csv.reader yields lists. 
    for row in reader:
        line_num += 1 # reader.line_num is 1-based for the current line, 
                      # but if we skip empty lines via the loop, does it increment?
                      # csv.reader skips nothing by default if we pass splitlines(). 
                      # Actually, csv.reader will return an empty list for blank lines.
                      # Let's rely on the index of the row in splitlines + 1 for the header offset?
                      # No, let's just use a counter. The first row was line 1 (header).
                      # The next yielded row is the next non-empty line? 
                      # Wait, csv.reader yields [] for empty lines.
                      # So we must handle empty lines manually or count them.

        # If the row is empty (length 0), it means the line was blank.
        if not row:
            continue

        # If row has different number of fields than header
        if len(row) != len(header):
            errors.append(RowError(line_num, f"row: expected {len(header)} fields, got {len(row)}"))
            continue

        # Extract raw values based on indices
        raw_vals = {}
        for field in REQUIRED_COLUMNS:
            idx = col_indices[field]
            raw_vals[field] = row[idx].strip()

        # Validate fields in order: date, region, product, units, unit_price
        error_msg = None
        sale_kwargs = {}

        # 1. Date
        try:
            sale_kwargs['date'] = _validate_date(raw_vals['date'])
        except ValueError as e:
            error_msg = f"date: {e}"

        if not error_msg:
            # 2. Region
            if not raw_vals['region']:
                error_msg = "region: cannot be empty"

        if not error_msg:
            # 3. Product
            if not raw_vals['product']:
                error_msg = "product: cannot be empty"

        if not error_msg:
            # 4. Units
            try:
                sale_kwargs['units'] = _validate_units(raw_vals['units'])
            except ValueError as e:
                error_msg = f"units: {e}"

        if not error_msg:
            # 5. Unit Price
            try:
                sale_kwargs['unit_price'] = _validate_price(raw_vals['unit_price'])
            except ValueError as e:
                error_msg = f"unit_price: {e}"

        if error_msg:
            errors.append(RowError(line_num, error_msg))
        else:
            # Create Sale
            # We need region and product strings from raw_vals
            sale_kwargs['region'] = raw_vals['region']
            sale_kwargs['product'] = raw_vals['product']

            # Create the Sale object
            # Note: Sale is a dataclass, so we pass all fields
            sales.append(Sale(
                date=sale_kwargs['date'],
                region=sale_kwargs['region'],
                product=sale_kwargs['product'],
                units=sale_kwargs['units'],
                unit_price=sale_kwargs['unit_price']
            ))

    return sales, errors


def read_sales(path: str) -> Tuple[List[Sale], List[RowError]]:
    """
    Read CSV file at path as UTF-8, ignoring BOM, and parse sales.
    """
    with open(path, 'r', encoding='utf-8-sig') as f:
        text = f.read()
        return parse_sales(text)

# sales/aggregate.py

from __future__ import annotations

import datetime
import decimal
from dataclasses import dataclass
from typing import List, Tuple, Optional, Dict, Any

from sales.ingest import Sale

FIELDS = ('month', 'region', 'product')


def parse_month(text: str) -> str:
    """
    Check that text is YYYY-MM with a month from 01 to 12.
    Returns it unchanged if valid, otherwise raises ValueError.
    """
    if not isinstance(text, str):
        raise ValueError("month must be a string")

    try:
        # Try to parse as YYYY-MM to validate format and calendar validity
        dt = datetime.datetime.strptime(text, "%Y-%m")
        # Ensure the format is exactly YYYY-MM (e.g. 2023-01 vs 2023-1)
        # strptime is somewhat lenient, but we want strict 4-2 digits for year-month
        if len(text) != 7 or text[4] != '-':
             raise ValueError
        # Reconstruct to ensure it matches the input exactly (no leading zeros issues if they were different, though %Y handles 4 digits usually)
        if text != dt.strftime("%Y-%m"):
             raise ValueError
    except ValueError:
        raise ValueError(f"Invalid month format: {text}")

    return text


def filter_months(
    sales: List[Sale], 
    start: Optional[str] = None, 
    end: Optional[str] = None
) -> List[Sale]:
    """
    Keep the sales whose month is between start and end (YYYY-MM strings, inclusive).
    None means unbounded.
    """
    if start is not None:
        start = parse_month(start)
    if end is not None:
        end = parse_month(end)

    filtered = []
    for sale in sales:
        month_str = sale.date.strftime("%Y-%m")

        if start is not None and month_str < start:
            continue
        if end is not None and month_str > end:
            continue

        filtered.append(sale)

    return filtered


@dataclass(frozen=True)
class Group:
    key: Tuple[str, ...]
    units: int
    orders: int
    revenue: decimal.Decimal


@dataclass(frozen=True)
class Report:
    by: Tuple[str, ...]
    groups: List[Group]
    total: Group


def _get_sale_field(sale: Sale, field: str) -> str:
    if field == 'month':
        return sale.date.strftime("%Y-%m")
    elif field == 'region':
        return sale.region
    elif field == 'product':
        return sale.product
    else:
        raise ValueError(f"Unknown field: {field}")


def aggregate(
    sales: List[Sale], 
    by: Tuple[str, ...]
) -> List[Group]:
    """
    Groups the sales by the fields named in `by`.
    Returns a list of Groups sorted by key.
    """
    # Validation
    if not by:
        raise ValueError("'by' must contain at least one field")
    if len(set(by)) != len(by):
        raise ValueError("'by' must not contain repeated fields")
    for f in by:
        if f not in FIELDS:
            raise ValueError(f"Unknown field in 'by': {f}")

    groups_dict: Dict[Tuple[str, ...], Dict[str, Any]] = {}

    for sale in sales:
        key = tuple(_get_sale_field(sale, field) for field in by)

        if key not in groups_dict:
            groups_dict[key] = {
                'units': 0,
                'orders': 0,
                'revenue': decimal.Decimal(0)
            }

        groups_dict[key]['units'] += sale.units
        groups_dict[key]['orders'] += 1
        groups_dict[key]['revenue'] += sale.revenue

    result_groups = []
    for key, stats in groups_dict.items():
        result_groups.append(Group(
            key=key,
            units=stats['units'],
            orders=stats['orders'],
            revenue=stats['revenue']
        ))

    result_groups.sort(key=lambda g: g.key)
    return result_groups


def build_report(
    sales: List[Sale], 
    by: Tuple[str, ...]
) -> Report:
    """
    Returns the Report object including the total group.
    """
    # Validation
    if not by:
        raise ValueError("'by' must contain at least one field")
    if len(set(by)) != len(by):
        raise ValueError("'by' must not contain repeated fields")
    for f in by:
        if f not in FIELDS:
            raise ValueError(f"Unknown field in 'by': {f}")

    groups = aggregate(sales, by)

    total_units = 0
    total_orders = 0
    total_revenue = decimal.Decimal(0)

    for group in groups:
        total_units += group.units
        total_orders += group.orders
        total_revenue += group.revenue

    total_group = Group(
        key=(),
        units=total_units,
        orders=total_orders,
        revenue=total_revenue
    )

    return Report(
        by=by,
        groups=groups,
        total=total_group
    )

