        if start_room_id not in raw_rooms:
            raise WorldError(f"Start room {start_room_id!r} does not exist")

        # Parse Items first to validate references later
        parsed_items: Dict[str, Item] = {}
        for item_id, item_data in raw_items.items():
            if not item_data.get("name"):
                raise WorldError(f"Item {item_id!r} missing name")
            if not item_data.get("description"):
                raise WorldError(f"Item {item_id!r} missing description")

            portable = item_data.get("portable", True)
            parsed_items[item_id] = Item(
                id=item_id,
                name=item_data["name"],
                description=item_data["description"],
                portable=portable
            )

        # Parse Rooms and track item usage
        parsed_rooms: Dict[str, Room] = {}
        used_items: Dict[str, str] = {} # item_id -> room_id where it was found (for error reporting if needed, though spec says just 'listed more than once')

        # First pass: basic room validation and structure
        for room_id, room_data in raw_rooms.items():
            if not room_data.get("name"):
                raise WorldError(f"Room {room_id!r} missing name")
            if not room_data.get("description"):
                raise WorldError(f"Room {room_id!r} missing description")

            exits_raw = room_data.get("exits", {})
            items_raw = room_data.get("items", [])

            parsed_exits = {}
            for direction, dest_room_id in exits_raw.items():
                if direction not in DIRECTIONS:
                    raise WorldError(f"Invalid direction {direction!r} in room {room_id!r}")
                if dest_room_id not in raw_rooms:
                    raise WorldError(f"Room {room_id!r} exit {direction!r} leads to unknown room {dest_room_id!r}")
                parsed_exits[direction] = dest_room_id

            parsed_item_ids = []
            for item_id in items_raw:
                if item_id not in parsed_items:
                    raise WorldError(f"Room {room_id!r} lists unknown item {item_id!r}")

                if item_id in used_items:
                    raise WorldError(f"Item {item_id!r} is listed more than once")

                parsed_item_ids.append(item_id)
                used_items[item_id] = room_id

            parsed_rooms[room_id] = Room(
                id=room_id,
                name=room_data["name"],
                description=room_data["description"],
                exits=parsed_exits,
                items=tuple(parsed_item_ids)
            )

        return cls(
            start=start_room_id,
            rooms=parsed_rooms,
