from typing import List, Dict, Optional, Set

from .world import World, Room, Item, DIRECTIONS
from .parser import parse, Command, ParseError


class SaveError(ValueError):
    """Raised when a save file is invalid."""
    pass


class Game:
    """Manages the mutable state of a game session."""

    def __init__(self, world: World):
        self.world = world
        self._current_room = world.start
        self._inventory: List[str] = []
        self._moves: int = 0

        # New state tracking
        self._unlocked_exits: Set[tuple] = set()  # (room_id, direction)
        self._visited_rooms: Set[str] = {world.start}
        self._scored_items: Set[str] = set()
        self._score: int = 0

        # Initialize item locations: room_id -> list of item_ids
        self._room_items: Dict[str, List[str]] = {
            room_id: list(room.items) for room_id, room in world.rooms.items()
        }

    @property
    def room(self) -> str:
        """The current room id."""
        return self._current_room

    @property
    def inventory(self) -> List[str]:
        """A list of item ids in the inventory, in order."""
        return list(self._inventory)

    @property
    def moves(self) -> int:
        """The number of successful moves."""
        return self._moves

    @property
    def score(self) -> int:
        """The current score."""
        return self._score

    def items_in(self, room_id: str) -> List[str]:
        """Return a list of item ids currently in the given room."""
        return list(self._room_items.get(room_id, []))

    def _find_item(self, search_arg: str) -> Optional[Item]:
        """Find an item matching the argument, searching current room then inventory."""
        # Search room first
        for item_id in self._room_items.get(self._current_room, []):
            item = self.world.items[item_id]
            if item_id == search_arg or item.name.lower() == search_arg:
                return item

        # Search inventory
        for item_id in self._inventory:
            item = self.world.items[item_id]
            if item_id == search_arg or item.name.lower() == search_arg:
                return item

        return None

    def _find_item_in_room(self, search_arg: str) -> Optional[str]:
        """Return item id if found in current room, else None."""
        for item_id in self._room_items.get(self._current_room, []):
            item = self.world.items[item_id]
            if item_id == search_arg or item.name.lower() == search_arg:
                return item_id
        return None

    def _find_item_in_inv(self, search_arg: str) -> Optional[str]:
        """Return item id if found in inventory, else None."""
        for item_id in self._inventory:
            item = self.world.items[item_id]
            if item_id == search_arg or item.name.lower() == search_arg:
                return item_id
        return None

    def _is_locked(self, room_id: str, direction: str) -> bool:
        """Check if an exit is currently locked."""
        room = self.world.rooms[room_id]
        if direction not in room.locks:
            return False
        if (room_id, direction) in self._unlocked_exits:
            return False
        return True

    def _look_room(self, room_id: str) -> str:
        """Generate the description text for a room."""
        room = self.world.rooms[room_id]
        lines = []
        lines.append(room.name)
        lines.append(room.description)

        # Exits
        exits = room.exits
        valid_exits = []
        for d in DIRECTIONS:
            if d in exits:
                if self._is_locked(room_id, d):
                    valid_exits.append(f"{d} (locked)")
                else:
                    valid_exits.append(d)

        if valid_exits:
            lines.append("Exits: " + ", ".join(valid_exits) + ".")
        else:
            lines.append("Exits: none.")

        # Items in room
        item_ids = self._room_items.get(room_id, [])
        if item_ids:
            names = [self.world.items[i].name for i in item_ids]
            lines.append("You see: " + ", ".join(names) + ".")

        return "\n".join(lines)

    def _handle_look(self, arg: Optional[str]) -> str:
        """Handle 'look' command (room or item)."""
        if arg is None:
            return self._look_room(self._current_room)

        item = self._find_item(arg)
        if item:
            return item.description

        return f"You see no {arg} here."

    def _handle_go(self, arg: Optional[str]) -> str:
        """Handle 'go' command."""
        if arg is None:
            return "Go where?"

        room = self.world.rooms[self._current_room]
        if arg in room.exits:
            # Check lock
            if self._is_locked(self._current_room, arg):
                return f"The way {arg} is locked."

            self._current_room = room.exits[arg]
            self._moves += 1

            # Score room visit
            if self._current_room not in self._visited_rooms:
                self._visited_rooms.add(self._current_room)
                self._score += 10

            return self._look_room(self._current_room)

        return "You can't go that way."

    def _handle_take(self, arg: Optional[str]) -> str:
        """Handle 'take' command."""
        if arg is None:
            return "Take what?"

        item_id = self._find_item_in_room(arg)
        if item_id:
            item = self.world.items[item_id]
            if not item.portable:
                return f"You can't take the {item.name}."

            # Move item to inventory
            self._room_items[self._current_room].remove(item_id)
            self._inventory.append(item_id)

            # Score treasure
            if item_id not in self._scored_items:
                self._scored_items.add(item_id)
                if item.treasure > 0:
                    self._score += item.treasure

            return f"Taken: {item.name}."

        # Check if already in inventory
        item_id_inv = self._find_item_in_inv(arg)
        if item_id_inv:
            item = self.world.items[item_id_inv]
            return f"You already have the {item.name}."

        return f"You see no {arg} here."

    def _handle_drop(self, arg: Optional[str]) -> str:
        """Handle 'drop' command."""
        if arg is None:
            return "Drop what?"

        item_id = self._find_item_in_inv(arg)
        if item_id:
            item = self.world.items[item_id]
            # Move item to room
            self._inventory.remove(item_id)
            if self._current_room not in self._room_items:
                self._room_items[self._current_room] = []
            self._room_items[self._current_room].append(item_id)
            return f"Dropped: {item.name}."

        return "You aren't carrying that."

    def _handle_inventory(self) -> str:
        """Handle 'inventory' command."""
        if not self._inventory:
            return "You are carrying nothing."

        names = [self.world.items[i].name for i in self._inventory]
        return "You are carrying: " + ", ".join(names) + "."

    def _handle_use(self, arg: Optional[str]) -> str:
        """Handle 'use' command."""
        if arg is None:
            return "Use what?"

        item_id = self._find_item_in_inv(arg)
        if not item_id:
            return "You aren't carrying that."

        room = self.world.rooms[self._current_room]
        unlocked_dirs = []

        for direction, key_id in room.locks.items():
            if key_id == item_id:
                if self._is_locked(self._current_room, direction):
                    unlocked_dirs.append(direction)

        if not unlocked_dirs:
            item = self.world.items[item_id]
            return f"Nothing here to use the {item.name} on."

        # Unlock them
        for d in unlocked_dirs:
            self._unlocked_exits.add((self._current_room, d))

        # Sort by canonical order
        sorted_dirs = [d for d in DIRECTIONS if d in unlocked_dirs]

        return "Unlocked: " + ", ".join(sorted_dirs) + "."

    def _handle_score(self) -> str:
        """Handle 'score' command."""
        return f"Your score is {self._score}."

    def do(self, line: str) -> str:
        """Execute a command string and return the response."""
        try:
            cmd = parse(line)
        except ParseError as e:
            return str(e)

        if cmd.verb == "look":
            return self._handle_look(cmd.arg)
        elif cmd.verb == "go":
            return self._handle_go(cmd.arg)
        elif cmd.verb == "take":
            return self._handle_take(cmd.arg)
        elif cmd.verb == "drop":
            return self._handle_drop(cmd.arg)
        elif cmd.verb == "inventory":
            return self._handle_inventory()
        elif cmd.verb == "use":
            return self._handle_use(cmd.arg)
        elif cmd.verb == "score":
            return self._handle_score()
        else:
            return "I don't know the word \"{}\".".format(cmd.verb)

    def save(self) -> str:
        """Save the game state to a JSON string."""

        # Format unlocked exits as sorted list of [room, direction] pairs
        unlocked_list = sorted(
            [[room_id, direction] for room_id, direction in self._unlocked_exits]
        )

        visited_list = sorted(list(self._visited_rooms))
        scored_list = sorted(list(self._scored_items))

        data = {
            "version": 2,
            "room": self._current_room,
            "inventory": self._inventory,
            "items": {},
            "moves": self._moves,
            "unlocked": unlocked_list,
            "visited": visited_list,
            "scored": scored_list,
            "score": self._score,
        }

        # Construct items map: room_id -> list of item_ids
        for room_id in self.world.rooms:
            items_list = self._room_items.get(room_id, [])
            data["items"][room_id] = list(items_list)

        return json.dumps(data)

    @classmethod
    def load(cls, world: World, text: str) -> "Game":
        """Load a game state from a JSON string."""
        try:
            data = json.loads(text)
        except json.JSONDecodeError as e:
            raise SaveError(f"Invalid JSON: {e}")

        if not isinstance(data, dict):
            raise SaveError("Save file must be a JSON object")

        # Check required keys for version 2
        required_keys_v2 = ["version", "room", "inventory", "items", "moves", "unlocked", "visited", "scored", "score"]
        required_keys_v1 = ["version", "room", "inventory", "items", "moves"]

        version = data.get("version")

        if version == 2:
            for key in required_keys_v2:
                if key not in data:
                    raise SaveError(f"Missing key: {key}")
        elif version == 1:
            for key in required_keys_v1:
                if key not in data:
                    raise SaveError(f"Missing key: {key}")
        else:
            raise SaveError(f"Unsupported version: {version}")

        # Validate room
        room_id = data["room"]
        if not isinstance(room_id, str) or room_id not in world.rooms:
            raise SaveError(f"Unknown room: {room_id}")

        # Validate moves
        moves = data["moves"]
        if not isinstance(moves, int) or moves < 0:
            raise SaveError("moves must be a non-negative integer")

        # Validate inventory
        inv = data["inventory"]
        if not isinstance(inv, list):
            raise SaveError("inventory must be a list")
        for item_id in inv:
            if not isinstance(item_id, str) or item_id not in world.items:
                raise SaveError(f"Unknown item in inventory: {item_id}")

        # Validate items map
        items_map = data["items"]
        if not isinstance(items_map, dict):
            raise SaveError("items must be an object")

        all_seen_items = set(inv) # Items in inventory are already 'seen' for duplicate check

        # Build room items state
        new_room_items = {}

        for room_key, room_items_list in items_map.items():
            if not isinstance(room_key, str) or room_key not in world.rooms:
                raise SaveError(f"Unknown room key in items: {room_key}")

            if not isinstance(room_items_list, list):
                raise SaveError(f"items['{room_key}'] must be a list")

            room_item_ids = []
            for item_id in room_items_list:
                if not isinstance(item_id, str) or item_id not in world.items:
                    raise SaveError(f"Unknown item in room {room_key}: {item_id}")

                if item_id in all_seen_items:
                    raise SaveError(f"Item {item_id} appears more than once")

                all_seen_items.add(item_id)
                room_item_ids.append(item_id)

            new_room_items[room_key] = room_item_ids

        # Initialize game object
        game = cls(world)

        # Override basic state
        game._current_room = room_id
        game._moves = moves
        game._inventory = list(inv)
        game._room_items = new_room_items

        # Ensure all rooms exist in room_items
        for room_id in world.rooms:
            if room_id not in game._room_items:
                game._room_items[room_id] = []

        if version == 2:
            # Validate and set unlocked exits
            unlocked_data = data["unlocked"]
            if not isinstance(unlocked_data, list):
                raise SaveError("unlocked must be a list")

            for pair in unlocked_data:
                if not isinstance(pair, list) or len(pair) != 2:
                    raise SaveError("unlocked entries must be [room, direction] pairs")

                r_id, dir_str = pair
                if not isinstance(r_id, str) or r_id not in world.rooms:
                    raise SaveError(f"Unknown room in unlocked: {r_id}")
                if not isinstance(dir_str, str):
                    raise SaveError("direction in unlocked must be a string")

                if dir_str not in DIRECTIONS:
                    raise SaveError(f"Invalid direction: {dir_str}")

                room = world.rooms[r_id]
                if dir_str not in room.exits:
                    raise SaveError(f"Not an exit: {r_id} {dir_str}")

                if dir_str not in room.locks:
                    raise SaveError(f"Not a locked exit: {r_id} {dir_str}")

                game._unlocked_exits.add((r_id, dir_str))

            # Validate and set visited rooms
            visited_data = data["visited"]
            if not isinstance(visited_data, list):
                raise SaveError("visited must be a list")

            for r_id in visited_data:
                if not isinstance(r_id, str) or r_id not in world.rooms:
                    raise SaveError(f"Unknown room in visited: {r_id}")
                game._visited_rooms.add(r_id)

            # Ensure start and current room are visited if not in save? 
            # Spec: "visited" (the sorted list of visited room ids).
            # Load should trust the save? 
            # If save is missing start room, it might be inconsistent, but spec says "visited room or ... not in world" raises error.
            # It doesn't say "must contain start room". 
            # However, _visited_rooms was initialized with start in cls(world).
            # If we add from save, we might duplicate. Set handles it.
            # But if save doesn't have start, it stays in set from init? 
            # Wait, if we initialize cls(world), _visited_rooms has start.
            # Then we add from save. 
            # If save is missing start, it's still in set. 
            # Is that correct? "the start room and the saved current room as its visited rooms" for v1.
            # For v2, it uses the list. 
            # If the list is valid, we should probably clear and set, or just add.
            # If we just add, and the list is incomplete, we have extra states.
            # Usually load replaces state. 
            # But _visited_rooms is a set. 
            # If I clear and set:
            game._visited_rooms = set(visited_data)
            # Spec doesn't explicitly say to force start/current if missing in v2, just validates existence in world.
            # But logically v2 save should be consistent. 
            # Let's stick to loading the list provided.

            # Validate and set scored items
            scored_data = data["scored"]
            if not isinstance(scored_data, list):
                raise SaveError("scored must be a list")

            for item_id in scored_data:
                if not isinstance(item_id, str) or item_id not in world.items:
                    raise SaveError(f"Unknown item in scored: {item_id}")
                game._scored_items.add(item_id)

            # Validate and set score
            score_val = data["score"]
            if not isinstance(score_val, int) or score_val < 0:
                raise SaveError("score must be a non-negative integer")

            game._score = score_val

        else: # Version 1
            # "Such a game has every lock still locked, the start room and the saved current room as its visited rooms, nothing scored, and a score of 0."
            # _unlocked_exits is already empty from init.
            # _scored_items is already empty from init.
            # _score is already 0 from init.

            # Visited rooms: start room and current room.
            # cls(world) already added start room to _visited_rooms.
            # We need to ensure current room is in there too.
            game._visited_rooms.add(room_id)

        return game
