from dataclasses import dataclass, field
from typing import Dict, Tuple, Any

DIRECTIONS = ('north', 'south', 'east', 'west', 'up', 'down')


class WorldError(ValueError):
    pass


@dataclass(frozen=True)
class Room:
    id: str
    name: str
    description: str
    exits: Dict[str, str]
    items: Tuple[str, ...]
    locks: Dict[str, str] = field(default_factory=dict)


@dataclass(frozen=True)
class Item:
    id: str
    name: str
    description: str
    portable: bool = True
    treasure: int = 0


class World:
    def __init__(self, start: str, rooms: Dict[str, Room], items: Dict[str, Item]):
        self.start = start
        self.rooms = rooms
        self.items = items

    @classmethod
    def from_dict(cls, data: dict) -> 'World':
        # Extract raw data
        start_room_id = data.get("start")
        raw_rooms = data.get("rooms", {})
        raw_items = data.get("items", {})

        # Validate start
        if not start_room_id:
            raise WorldError("Missing start room")
        if start_room_id not in raw_rooms:
            raise WorldError(f"Start room {start_room_id!r} does not exist")

        # Parse Items first to validate references later
        parsed_items: Dict[str, Item] = {}
        for item_id, item_data in raw_items.items():
            if not item_data.get("name"):
                raise WorldError(f"Item {item_id!r} missing name")
            if not item_data.get("description"):
                raise WorldError(f"Item {item_id!r} missing description")

            portable = item_data.get("portable", True)
            treasure = item_data.get("treasure", 0)

            # Validate treasure
            if not isinstance(treasure, int) or isinstance(treasure, bool) or treasure < 0:
                raise WorldError(f"Item {item_id!r} has invalid treasure value: {treasure!r}")

            parsed_items[item_id] = Item(
                id=item_id,
                name=item_data["name"],
                description=item_data["description"],
                portable=portable,
                treasure=treasure
            )

        # Parse Rooms and track item usage
        parsed_rooms: Dict[str, Room] = {}
        used_items: Dict[str, str] = {} # item_id -> room_id where it was found

        # First pass: basic room validation and structure
        for room_id, room_data in raw_rooms.items():
            if not room_data.get("name"):
                raise WorldError(f"Room {room_id!r} missing name")
            if not room_data.get("description"):
                raise WorldError(f"Room {room_id!r} missing description")

            exits_raw = room_data.get("exits", {})
            items_raw = room_data.get("items", [])

            parsed_exits = {}
            parsed_locks = {}

            for direction, exit_def in exits_raw.items():
                if direction not in DIRECTIONS:
                    raise WorldError(f"Invalid direction {direction!r} in room {room_id!r}")

                target_room_id = None
                key_item_id = None

                if isinstance(exit_def, dict):
                    # Locked exit format
                    if "to" not in exit_def:
                        raise WorldError(f"Exit {direction!r} in room {room_id!r} missing 'to'")
                    if "key" not in exit_def:
                        raise WorldError(f"Exit {direction!r} in room {room_id!r} missing 'key'")

                    target_room_id = exit_def["to"]
                    key_item_id = exit_def["key"]

                    if key_item_id not in raw_items:
                        raise WorldError(f"Exit {direction!r} in room {room_id!r} uses unknown key {key_item_id!r}")
                else:
                    # Unlocked exit format (string)
                    target_room_id = exit_def

                # Validate target room exists
                if target_room_id not in raw_rooms:
                    raise WorldError(f"Room {room_id!r} exit {direction!r} leads to unknown room {target_room_id!r}")

                parsed_exits[direction] = target_room_id

                if key_item_id:
                    parsed_locks[direction] = key_item_id

            parsed_item_ids = []
            for item_id in items_raw:
                if item_id not in parsed_items:
                    raise WorldError(f"Room {room_id!r} lists unknown item {item_id!r}")

                if item_id in used_items:
                    raise WorldError(f"Item {item_id!r} is listed more than once")

                parsed_item_ids.append(item_id)
                used_items[item_id] = room_id

            parsed_rooms[room_id] = Room(
                id=room_id,
                name=room_data["name"],
                description=room_data["description"],
                exits=parsed_exits,
                items=tuple(parsed_item_ids),
                locks=parsed_locks
            )

        return cls(
            start=start_room_id,
            rooms=parsed_rooms,
            items=parsed_items
        )
