from typing import NamedTuple, Optional


class ParseError(ValueError):
    """Raised when input cannot be parsed into a valid command."""
    pass


class Command(NamedTuple):
    """Represents a parsed player command."""
    verb: str
    arg: Optional[str]


DIRECTIONS = ('north', 'south', 'east', 'west', 'up', 'down')

# Map short forms and full names to canonical direction names
DIR_MAP = {
    'n': 'north', 'north': 'north',
    's': 'south', 'south': 'south',
    'e': 'east', 'east': 'east',
    'w': 'west', 'west': 'west',
    'u': 'up', 'up': 'up',
    'd': 'down', 'down': 'down',
}

ARTICLES = {'the', 'a', 'an'}


def parse(line: str) -> Command:
    """
    Parse a text line into a Command object.

    Args:
        line: The raw input string from the player.

    Returns:
        A Command instance with verb and argument.

    Raises:
        ParseError: If the input is empty, contains unknown words, 
                    or is structurally invalid.
    """
    # Normalize case and strip whitespace
    line = line.lower().strip()

    if not line:
        raise ParseError('Say something.')

    words = line.split()
    if not words:
        raise ParseError('Say something.')

    # Keep the first word, filter articles from subsequent words
    # "remove every `the`, `a` and `an` after the first word"
    first_word = words[0]
    rest_words = [w for w in words[1:] if w not in ARTICLES]

    # If filtering removed everything, it's like having no argument
    # But we handle arguments based on the filtered list

    # Check if first word is a direction (implicit 'go')
    if first_word in DIR_MAP:
        if rest_words:
            raise ParseError("I don't understand that.")
        return Command('go', DIR_MAP[first_word])

    # Explicit 'go' command
    if first_word == 'go':
        if not rest_words:
            raise ParseError('Go where?')
        direction = rest_words[0]
        if direction not in DIR_MAP:
            raise ParseError(f'"{" ".join(rest_words)}" is not a direction.')
        # If there are extra words after the direction, it's an error
        if len(rest_words) > 1:
            raise ParseError("I don't understand that.")
        return Command('go', DIR_MAP[direction])

    # Take/Get commands
    if first_word in ('take', 'get'):
        if not rest_words:
            raise ParseError('Take what?')
        return Command('take', ' '.join(rest_words))

    # Drop command
    if first_word == 'drop':
        if not rest_words:
            raise ParseError('Drop what?')
        return Command('drop', ' '.join(rest_words))

    # Use command
    if first_word == 'use':
        if not rest_words:
            raise ParseError('Use what?')
        return Command('use', ' '.join(rest_words))

    # Score command
    if first_word == 'score':
        if rest_words:
            raise ParseError("I don't understand that.")
        return Command('score', None)

    # Look family
    if first_word in ('look', 'l'):
        # Handle "look at X" specifically
        # If the first remaining word is 'at', skip it
        if rest_words and rest_words[0] == 'at':
            rest_words = rest_words[1:]

        if not rest_words:
            return Command('look', None)
        return Command('look', ' '.join(rest_words))

    # Examine/X commands (map to look verb)
    if first_word in ('examine', 'x'):
        if not rest_words:
            raise ParseError('Examine what?')
        return Command('look', ' '.join(rest_words))

    # Inventory commands
    if first_word in ('inventory', 'inv', 'i'):
        if rest_words:
            raise ParseError("I don't understand that.")
        return Command('inventory', None)

    # Unknown word
    raise ParseError(f'I don\'t know the word "{first_word}".')
