        """Return a list of item ids currently in the given room."""
        return list(self._room_items.get(room_id, []))

    def _find_item(self, search_arg: str) -> Optional[Item]:
        """Find an item matching the argument, searching current room then inventory."""
        # Search room first
        for item_id in self._room_items.get(self._current_room, []):
            item = self.world.items[item_id]
            if item_id == search_arg or item.name.lower() == search_arg:
                return item

        # Search inventory
        for item_id in self._inventory:
            item = self.world.items[item_id]
            if item_id == search_arg or item.name.lower() == search_arg:
                return item

        return None

    def _find_item_in_room(self, search_arg: str) -> Optional[str]:
        """Return item id if found in current room, else None."""
        for item_id in self._room_items.get(self._current_room, []):
            item = self.world.items[item_id]
            if item_id == search_arg or item.name.lower() == search_arg:
                return item_id
        return None

    def _find_item_in_inv(self, search_arg: str) -> Optional[str]:
        """Return item id if found in inventory, else None."""
        for item_id in self._inventory:
            item = self.world.items[item_id]
            if item_id == search_arg or item.name.lower() == search_arg:
                return item_id
        return None

    def _is_locked(self, room_id: str, direction: str) -> bool:
        """Check if an exit is currently locked."""
        room = self.world.rooms[room_id]
        if direction not in room.locks:
            return False
        if (room_id, direction) in self._unlocked_exits:
            return False
        return True

    def _look_room(self, room_id: str) -> str:
        """Generate the description text for a room."""
        room = self.world.rooms[room_id]
        lines = []
        lines.append(room.name)
        lines.append(room.description)

        # Exits
        exits = room.exits
        valid_exits = []
        for d in DIRECTIONS:
            if d in exits:
                if self._is_locked(room_id, d):
                    valid_exits.append(f"{d} (locked)")
                else:
                    valid_exits.append(d)

        if valid_exits:
            lines.append("Exits: " + ", ".join(valid_exits) + ".")
        else:
            lines.append("Exits: none.")

        # Items in room
        item_ids = self._room_items.get(room_id, [])
        if item_ids:
            names = [self.world.items[i].name for i in item_ids]
            lines.append("You see: " + ", ".join(names) + ".")

        return "\n".join(lines)

    def _handle_look(self, arg: Optional[str]) -> str:
        """Handle 'look' command (room or item)."""
        if arg is None:
            return self._look_room(self._current_room)

        item = self._find_item(arg)
        if item:
            return item.description

        return f"You see no {arg} here."

    def _handle_go(self, arg: Optional[str]) -> str:
        """Handle 'go' command."""
        if arg is None:
            return "Go where?"

        room = self.world.rooms[self._current_room]
        if arg in room.exits:
            # Check lock
            if self._is_locked(self._current_room, arg):
                return f"The way {arg} is locked."

            self._current_room = room.exits[arg]
            self._moves += 1

            # Score room visit
            if self._current_room not in self._visited_rooms:
                self._visited_rooms.add(self._current_room)
                self._score += 10

            return self._look_room(self._current_room)

        return "You can't go that way."

