# stack/interp.py
"""
Interpreter for a small Forth-like stack language with user-defined words, 
call-depth limits, and a REPL.
"""

import sys
import os
from typing import List, Optional, Dict, Any, Tuple, TextIO
from .lexer import Token, tokenize


class StackError(Exception):
    """Base class for all stack errors."""
    def __init__(self, message: str, word: str = "", line: int = 0, col: int = 0):
        super().__init__(message)
        self.word = word
        self.line = line
        self.col = col


class StackUnderflow(StackError):
    pass


class UnknownWord(StackError):
    pass


class DivisionByZero(StackError):
    pass


class ControlError(StackError):
    pass


class StepLimitExceeded(StackError):
    pass


class CallDepthExceeded(StackError):
    pass


# Reserved words that cannot be defined
CONTROL_WORDS = {'if', 'else', 'then', 'begin', 'until'}
BUILTIN_WORDS = {
    'dup', 'drop', 'swap', 'over', 'rot',
    '+', '-', '*', '/', 'mod',
    'negate', 'abs',
    '.', 'depth',
    ':', ';' # Also reserved
}

class Interpreter:
    def __init__(self, max_steps: int = 100000, max_depth: int = 100):
        self.stack: List[int] = []
        self.output: List[int] = []
        self.max_steps = max_steps
        self.max_depth = max_depth
        self._steps_in_current_run = 0
        self._depth = 0
        # Map name -> (List[Token], Dict jump_maps) for defined words
        self.user_defs: Dict[str, Tuple[List[Token], Dict]] = {}

    def defined(self) -> List[str]:
        return sorted(self.user_defs.keys())

    def _inc_step(self, token: Token):
        self._steps_in_current_run += 1
        if self._steps_in_current_run > self.max_steps:
            word_val = token.value if token.kind == 'word' else str(token.value)
            raise StepLimitExceeded(
                f"Step limit exceeded at '{word_val}'",
                word_val,
                token.line,
                token.col
            )

    def _check_depth(self, token: Token):
        if self._depth >= self.max_depth:
            raise CallDepthExceeded(
                f"Call depth limit exceeded at '{token.value}'",
                str(token.value),
                token.line,
                token.col
            )

    def _pop(self, n: int, token: Token) -> List[int]:
        if len(self.stack) < n:
            raise StackUnderflow(
                f"Stack underflow at '{token.value}'",
                str(token.value),
                token.line,
                token.col
            )
        items = self.stack[-n:]
        self.stack = self.stack[:-n]
        return items

    def _push(self, value: int):
        self.stack.append(value)

    def _validate_and_prepare(self, tokens: List[Token]) -> Dict:
        """
        Validates control structures and definitions for the main source.
        Returns jump maps for the main source.
        """
        ctrl_stack: List[Tuple[str, int]] = []
        def_stack: List[int] = []

        if_else_map: Dict[int, int] = {}
        if_then_map: Dict[int, int] = {}
        else_then_map: Dict[int, int] = {}
        begin_until_map: Dict[int, int] = {}
        until_begin_map: Dict[int, int] = {}
        if_has_else: Dict[int, bool] = {}
        colon_semi_map: Dict[int, int] = {}
        semi_colon_map: Dict[int, int] = {}

        for i, token in enumerate(tokens):
            if token.kind != 'word':
                continue
            w = token.value

            if w == ':':
                if def_stack:
                    raise ControlError("Nested definition", w, token.line, token.col)
                if ctrl_stack:
                    raise ControlError("Definition inside control structure", w, token.line, token.col)

                if i + 1 >= len(tokens):
                    raise ControlError("Incomplete definition, missing name", w, token.line, token.col)

                name_token = tokens[i+1]
                if name_token.kind != 'word':
                    raise ControlError("Definition name must be a word", name_token.value, name_token.line, name_token.col)

                name = name_token.value
                if name in BUILTIN_WORDS or name in CONTROL_WORDS:
                    raise ControlError("Cannot redefine reserved word", name, name_token.line, name_token.col)

                def_stack.append(i)
                colon_semi_map[i] = -1

            elif w == ';':
                if not def_stack:
                    raise ControlError("Semicolon without definition", w, token.line, token.col)

                if ctrl_stack:
                    op_type, op_idx = ctrl_stack[-1]
                    op_token = tokens[op_idx]
                    raise ControlError(f"Open '{op_type.lower()}' at definition end", op_token.value, op_token.line, op_token.col)

                start_idx = def_stack.pop()
                colon_semi_map[start_idx] = i
                semi_colon_map[i] = start_idx

            elif w == 'if':
                ctrl_stack.append(('IF', i))
                if_has_else[i] = False

            elif w == 'else':
                if not ctrl_stack or ctrl_stack[-1][0] != 'IF':
                    raise ControlError("'else' without matching 'if'", w, token.line, token.col)
                idx = ctrl_stack[-1][1]
                if if_has_else[idx]:
                    raise ControlError("second 'else'", w, token.line, token.col)
                if_has_else[idx] = True
                if_else_map[idx] = i

            elif w == 'then':
                if not ctrl_stack or ctrl_stack[-1][0] != 'IF':
                    raise ControlError("'then' without matching 'if'", w, token.line, token.col)
                idx = ctrl_stack.pop()[1]
                if_then_map[idx] = i
                if idx in if_else_map:
                    else_then_map[if_else_map[idx]] = i

            elif w == 'begin':
                ctrl_stack.append(('BEGIN', i))

            elif w == 'until':
                if not ctrl_stack or ctrl_stack[-1][0] != 'BEGIN':
                    raise ControlError("'until' without matching 'begin'", w, token.line, token.col)
                idx = ctrl_stack.pop()[1]
                begin_until_map[idx] = i
                until_begin_map[i] = idx

        if def_stack:
            idx = def_stack[-1]
            token = tokens[idx]
            raise ControlError("Definition left open", token.value, token.line, token.col)

        if ctrl_stack:
            block_type, block_idx = ctrl_stack[-1]
            token = tokens[block_idx]
            raise ControlError(f"Control structure '{block_type}' left open", token.value, token.line, token.col)

        return {
            'if_else': if_else_map,
            'if_then': if_then_map,
            'else_then': else_then_map,
            'begin_until': begin_until_map,
            'until_begin': until_begin_map,
            'colon_semi': colon_semi_map,
            'semi_colon': semi_colon_map
        }

    def _validate_body_only(self, tokens: List[Token]) -> Dict:
        """Validates control flow for a body of tokens (no definitions allowed inside)."""
        ctrl_stack: List[Tuple[str, int]] = []
        if_else_map: Dict[int, int] = {}
        if_then_map: Dict[int, int] = {}
        else_then_map: Dict[int, int] = {}
        begin_until_map: Dict[int, int] = {}
        until_begin_map: Dict[int, int] = {}
        if_has_else: Dict[int, bool] = {}

        for i, token in enumerate(tokens):
            if token.kind != 'word': continue
            w = token.value
            if w in (':', ';'):
                raise ControlError("Nested definition", w, token.line, token.col)

            if w == 'if':
                ctrl_stack.append(('IF', i))
                if_has_else[i] = False
            elif w == 'else':
                if not ctrl_stack or ctrl_stack[-1][0] != 'IF':
                    raise ControlError("'else' without matching 'if'", w, token.line, token.col)
                idx = ctrl_stack[-1][1]
                if if_has_else[idx]:
                    raise ControlError("second 'else'", w, token.line, token.col)
                if_has_else[idx] = True
                if_else_map[idx] = i
            elif w == 'then':
                if not ctrl_stack or ctrl_stack[-1][0] != 'IF':
                    raise ControlError("'then' without matching 'if'", w, token.line, token.col)
                idx = ctrl_stack.pop()[1]
                if_then_map[idx] = i
                if idx in if_else_map:
                    else_then_map[if_else_map[idx]] = i
            elif w == 'begin':
                ctrl_stack.append(('BEGIN', i))
            elif w == 'until':
                if not ctrl_stack or ctrl_stack[-1][0] != 'BEGIN':
                    raise ControlError("'until' without matching 'begin'", w, token.line, token.col)
                idx = ctrl_stack.pop()[1]
                begin_until_map[idx] = i
                until_begin_map[i] = idx

        if ctrl_stack:
             block_type, block_idx = ctrl_stack[-1]
             token = tokens[block_idx]
             raise ControlError("control structure left open in body", token.value, token.line, token.col)

        return {
            'if_else': if_else_map,
            'if_then': if_then_map,
            'else_then': else_then_map,
            'begin_until': begin_until_map,
            'until_begin': until_begin_map
        }

    def run(self, source: str):
        self._steps_in_current_run = 0
        self._depth = 0

        tokens = tokenize(source)
        if not tokens:
            return

        try:
            jump_maps = self._validate_and_prepare(tokens)
            self._execute(tokens, 0, len(tokens), jump_maps)
        except StackError:
            raise

    def _execute(self, tokens: List[Token], start: int, end: int, jump_maps: Dict):
        i = start
        while i < end:
            token = tokens[i]

            if token.kind == 'number':
                self._inc_step(token)
                self._push(token.value)
                i += 1
                continue

            word = token.value

            if word == ':':
                semi_idx = jump_maps['colon_semi'].get(i)
                if semi_idx is None:
                    raise ControlError("Malformed definition", word, token.line, token.col)

                name_token = tokens[i+1]
                body_tokens = tokens[i+2 : semi_idx]
                body_jump_maps = self._validate_body_only(body_tokens)
                self.user_defs[name_token.value] = (body_tokens, body_jump_maps)
                i = semi_idx + 1
                continue

            if word == 'if':
                self._inc_step(token)
                if len(self.stack) < 1:
                    raise StackUnderflow(f"Stack underflow at '{word}'", word, token.line, token.col)
                val = self.stack.pop()

                if_idx = i
                then_idx = jump_maps['if_then'].get(if_idx)
                else_idx = jump_maps['if_else'].get(if_idx)

                if val != 0:
                    stop_at = else_idx if else_idx is not None else then_idx
                    if i + 1 < stop_at:
                        self._execute(tokens, i + 1, stop_at, jump_maps)
                    i = then_idx + 1
                    continue
                else:
                    if else_idx is not None:
                        actual_then_idx = jump_maps['else_then'].get(else_idx)
                        if actual_then_idx is None:
                             raise ControlError("Malformed else/then", word, token.line, token.col)
                        if else_idx + 1 < actual_then_idx:
                            self._execute(tokens, else_idx + 1, actual_then_idx, jump_maps)
                        i = actual_then_idx + 1
                    else:
                        i = then_idx + 1
                    continue

            if word == 'begin':
                i += 1
                continue

            if word == 'until':
                self._inc_step(token)
                if len(self.stack) < 1:
                    raise StackUnderflow(f"Stack underflow at '{word}'", word, token.line, token.col)
                val = self.stack.pop()

                begin_idx = jump_maps['until_begin'].get(i)
                if begin_idx is None:
                    raise ControlError("Malformed until", word, token.line, token.col)

                if val == 0:
                    if begin_idx + 1 < i:
                        self._execute(tokens, begin_idx + 1, i, jump_maps)
                    i = begin_idx + 1
                    continue
                else:
                    i += 1
                    continue

            if word in self.user_defs:
                self._check_depth(token)
                self._inc_step(token)

                body, body_jump_maps = self.user_defs[word]

                self._depth += 1
                try:
                    self._execute(body, 0, len(body), body_jump_maps)
                finally:
                    self._depth -= 1

                i += 1
                continue

            self._inc_step(token)
            self._execute_word(word, token)
            i += 1

    def _execute_word(self, word: str, token: Token):
        if word == 'dup':
            if len(self.stack) < 1:
                raise StackUnderflow("Stack underflow at 'dup'", word, token.line, token.col)
            v = self.stack[-1]
            self._push(v)
        elif word == 'drop':
            self._pop(1, token)
        elif word == 'swap':
            a, b = self._pop(2, token)
            self._push(a)
            self._push(b)
        elif word == 'over':
            a, b = self._pop(2, token)
            self._push(b)
            self._push(a)
            self._push(b)
        elif word == 'rot':
            a, b, c = self._pop(3, token)
            self._push(b)
            self._push(c)
            self._push(a)
        elif word == '+':
            a, b = self._pop(2, token)
            self._push(b + a)
        elif word == '-':
            a, b = self._pop(2, token)
            self._push(b - a)
        elif word == '*':
            a, b = self._pop(2, token)
            self._push(b * a)
        elif word == '/':
            a, b = self._pop(2, token)
            if a == 0:
                raise DivisionByZero("Division by zero", word, token.line, token.col)
            self._push(b // a)
        elif word == 'mod':
            a, b = self._pop(2, token)
            if a == 0:
                raise DivisionByZero("Modulo by zero", word, token.line, token.col)
            self._push(b % a)
        elif word == 'negate':
            v = self._pop(1, token)[0]
            self._push(-v)
        elif word == 'abs':
            v = self._pop(1, token)[0]
            self._push(abs(v))
        elif word == '.':
            v = self._pop(1, token)[0]
            self.output.append(v)
        elif word == 'depth':
            self._push(len(self.stack))
        else:
            raise UnknownWord(f"Unknown word '{word}'", word, token.line, token.col)

def evaluate(source: str, **kwargs) -> List[int]:
    interp = Interpreter(**kwargs)
    interp.run(source)
    return interp.output


def repl(infile: TextIO, outfile: TextIO, interp: Optional[Interpreter] = None) -> int:
    if interp is None:
        interp = Interpreter()

    for line in infile:
        line = line.rstrip('\n\r')
        if not line: continue

        try:
            start_len = len(interp.output)
            interp.run(line)
            new_vals = interp.output[start_len:]
            if new_vals:
                outfile.write(" ".join(str(v) for v in new_vals) + " ok\n")
            else:
                outfile.write("ok\n")
        except StackError as e:
            outfile.write(f"error: {type(e).__name__}: {e.word}\n")

    return 0


def main(argv: Optional[List[str]] = None) -> int:
    if argv is None:
        argv = sys.argv[1:]

    if not argv:
        return repl(sys.stdin, sys.stdout)

    if len(argv) != 1:
        sys.stderr.write("usage: python -m stack.interp [filename]\n")
        return 2

    path = argv[0]
    try:
        with open(path, 'r') as f:
            source = f.read()
    except Exception as e:
        sys.stderr.write(f"error: {e}\n")
        return 2

    interp = Interpreter()
    try:
        interp.run(source)
        if interp.output:
            sys.stdout.write(" ".join(str(v) for v in interp.output) + "\n")
        return 0
    except StackError as e:
        if interp.output:
            sys.stdout.write(" ".join(str(v) for v in interp.output) + "\n")
        sys.stderr.write(f"error: {type(e).__name__}: {e.word} at line {e.line}, column {e.col}\n")
        return 1
